from __future__ import annotations

import heapq
import logging
import threading
import time
from dataclasses import dataclass, field
from enum import Enum
from queue import Empty, Queue
from typing import Dict, List, Optional, Set, Tuple


logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(threadName)s - %(message)s",
)


class EventType(str, Enum):
    CONSULTATION_REQUEST = "consultation_request"
    CLINICIAN_UPDATE = "clinician_update"
    EMERGENCY_ALERT = "emergency_alert"
    SHUTDOWN = "shutdown"


@dataclass(frozen=True)
class ConsultationRequest:
    request_id: str
    patient_id: str
    symptom_severity: int
    wait_time_minutes: int
    specialty_needed: str
    risk_flags: Set[str] = field(default_factory=set)
    created_at: float = field(default_factory=time.time)

    def validate(self) -> None:
        if not self.request_id or not isinstance(self.request_id, str):
            raise ValueError("request_id must be a non-empty string")
        if not self.patient_id or not isinstance(self.patient_id, str):
            raise ValueError("patient_id must be a non-empty string")
        if not self.specialty_needed or not isinstance(self.specialty_needed, str):
            raise ValueError("specialty_needed must be a non-empty string")
        if not isinstance(self.symptom_severity, int) or not (0 <= self.symptom_severity <= 10):
            raise ValueError("symptom_severity must be an integer between 0 and 10")
        if not isinstance(self.wait_time_minutes, int) or self.wait_time_minutes < 0:
            raise ValueError("wait_time_minutes must be a non-negative integer")
        if not isinstance(self.risk_flags, set):
            raise ValueError("risk_flags must be a set of strings")


@dataclass(frozen=True)
class ClinicianStatusUpdate:
    clinician_id: str
    specialty: str
    available: bool
    capacity: int = 1

    def validate(self) -> None:
        if not self.clinician_id or not isinstance(self.clinician_id, str):
            raise ValueError("clinician_id must be a non-empty string")
        if not self.specialty or not isinstance(self.specialty, str):
            raise ValueError("specialty must be a non-empty string")
        if not isinstance(self.available, bool):
            raise ValueError("available must be a boolean")
        if not isinstance(self.capacity, int) or self.capacity < 0:
            raise ValueError("capacity must be a non-negative integer")


@dataclass(frozen=True)
class EmergencyAlert:
    patient_id: str
    specialty_needed: str
    message: str = ""
    severity_override: int = 10

    def validate(self) -> None:
        if not self.patient_id or not isinstance(self.patient_id, str):
            raise ValueError("patient_id must be a non-empty string")
        if not self.specialty_needed or not isinstance(self.specialty_needed, str):
            raise ValueError("specialty_needed must be a non-empty string")
        if not isinstance(self.severity_override, int) or not (0 <= self.severity_override <= 10):
            raise ValueError("severity_override must be an integer between 0 and 10")


@dataclass
class ClinicianRecord:
    clinician_id: str
    specialty: str
    available: bool = True
    capacity: int = 1
    assigned_patients: Set[str] = field(default_factory=set)

    @property
    def remaining_capacity(self) -> int:
        return max(0, self.capacity - len(self.assigned_patients))

    def can_accept(self) -> bool:
        return self.available and self.remaining_capacity > 0


@dataclass(order=True)
class PrioritizedItem:
    sort_key: Tuple[float, float]
    request: ConsultationRequest = field(compare=False)


class TelemedicineScheduler:
    HIGH_RISK_FLAGS = {"stroke", "chest_pain", "suicidal", "anaphylaxis", "sepsis", "respiratory_distress"}

    def __init__(self, worker_count: int = 4, event_queue_size: int = 0) -> None:
        if worker_count <= 0:
            raise ValueError("worker_count must be positive")

        self._event_queue: Queue = Queue(maxsize=event_queue_size)
        self._lock = threading.RLock()
        self._cv = threading.Condition(self._lock)
        self._shutdown = threading.Event()

        self._request_index: Dict[str, ConsultationRequest] = {}
        self._patient_to_request: Dict[str, str] = {}
        self._queues: Dict[str, List[PrioritizedItem]] = {}
        self._clinicians: Dict[str, ClinicianRecord] = {}
        self._escalation_log: List[Dict[str, object]] = []
        self._assigned_patients: Set[str] = set()

        self._workers: List[threading.Thread] = [
            threading.Thread(target=self._worker_loop, name=f"telemed-worker-{i+1}", daemon=True)
            for i in range(worker_count)
        ]
        for worker in self._workers:
            worker.start()

    def _compute_priority_score(self, request: ConsultationRequest) -> float:
        severity_weight = request.symptom_severity * 10.0
        wait_weight = min(request.wait_time_minutes, 240) * 0.5
        risk_weight = 0.0

        if request.risk_flags:
            risk_weight += len(request.risk_flags) * 7.5
            if self.HIGH_RISK_FLAGS.intersection(request.risk_flags):
                risk_weight += 50.0

        return severity_weight + wait_weight + risk_weight

    def _make_prioritized_item(self, request: ConsultationRequest) -> PrioritizedItem:
        score = self._compute_priority_score(request)
        # heapq is min-heap, so negate score for highest priority first.
        # created_at ensures FIFO among same score.
        return PrioritizedItem(sort_key=(-score, request.created_at), request=request)

    def add_consultation_request(self, request: ConsultationRequest, timeout: Optional[float] = None) -> None:
        request.validate()
        self._submit_event((EventType.CONSULTATION_REQUEST, request), timeout=timeout)

    def update_clinician_status(self, update: ClinicianStatusUpdate, timeout: Optional[float] = None) -> None:
        update.validate()
        self._submit_event((EventType.CLINICIAN_UPDATE, update), timeout=timeout)

    def submit_emergency_alert(self, alert: EmergencyAlert, timeout: Optional[float] = None) -> None:
        alert.validate()
        self._submit_event((EventType.EMERGENCY_ALERT, alert), timeout=timeout)

    def _submit_event(self, event: Tuple[EventType, object], timeout: Optional[float] = None) -> None:
        if self._shutdown.is_set():
            raise RuntimeError("scheduler is shutting down")
        try:
            self._event_queue.put(event, timeout=timeout)
        except Exception as exc:
            raise RuntimeError(f"failed to submit event: {exc}") from exc

    def fetch_next_highest_priority_patient(self, specialty: str) -> Optional[ConsultationRequest]:
        if not specialty or not isinstance(specialty, str):
            raise ValueError("specialty must be a non-empty string")

        with self._cv:
            queue = self._queues.get(specialty)
            if not queue:
                return None

            clinician = self._find_available_clinician_locked(specialty)
            if clinician is None:
                return None

            while queue:
                item = heapq.heappop(queue)
                request = item.request

                current_request_id = self._patient_to_request.get(request.patient_id)
                if current_request_id != request.request_id:
                    continue

                if request.patient_id in self._assigned_patients:
                    continue

                if request.request_id not in self._request_index:
                    continue

                clinician.assigned_patients.add(request.patient_id)
                self._assigned_patients.add(request.patient_id)

                del self._request_index[request.request_id]
                self._patient_to_request.pop(request.patient_id, None)

                logging.info(
                    "Assigned patient %s to clinician %s for specialty %s",
                    request.patient_id,
                    clinician.clinician_id,
                    specialty,
                )
                return request

            return None

    def complete_consultation(self, clinician_id: str, patient_id: str) -> None:
        if not clinician_id or not patient_id:
            raise ValueError("clinician_id and patient_id are required")

        with self._cv:
            clinician = self._clinicians.get(clinician_id)
            if clinician is None:
                raise KeyError(f"unknown clinician_id: {clinician_id}")

            if patient_id not in clinician.assigned_patients:
                raise ValueError(f"patient {patient_id} is not assigned to clinician {clinician_id}")

            clinician.assigned_patients.remove(patient_id)
            self._assigned_patients.discard(patient_id)
            self._cv.notify_all()

    def log_escalation(self, request: ConsultationRequest, reason: str) -> None:
        if not reason:
            raise ValueError("reason is required")

        with self._lock:
            entry = {
                "timestamp": time.time(),
                "request_id": request.request_id,
                "patient_id": request.patient_id,
                "specialty": request.specialty_needed,
                "reason": reason,
                "risk_flags": sorted(request.risk_flags),
            }
            self._escalation_log.append(entry)
            logging.warning("Escalation logged: %s", entry)

    def get_escalation_log(self) -> List[Dict[str, object]]:
        with self._lock:
            return list(self._escalation_log)

    def get_clinician_snapshot(self) -> Dict[str, Dict[str, object]]:
        with self._lock:
            return {
                cid: {
                    "specialty": c.specialty,
                    "available": c.available,
                    "capacity": c.capacity,
                    "assigned_patients": sorted(c.assigned_patients),
                    "remaining_capacity": c.remaining_capacity,
                }
                for cid, c in self._clinicians.items()
            }

    def get_queue_snapshot(self, specialty: Optional[str] = None) -> Dict[str, List[Dict[str, object]]]:
        with self._lock:
            specialties = [specialty] if specialty else list(self._queues.keys())
            snapshot: Dict[str, List[Dict[str, object]]] = {}
            for spec in specialties:
                items = self._queues.get(spec, [])
                ordered = sorted(items)
                snapshot[spec] = [
                    {
                        "request_id": item.request.request_id,
                        "patient_id": item.request.patient_id,
                        "priority_score": -item.sort_key[0],
                        "wait_time_minutes": item.request.wait_time_minutes,
                        "severity": item.request.symptom_severity,
                        "risk_flags": sorted(item.request.risk_flags),
                    }
                    for item in ordered
                    if item.request.request_id in self._request_index
                ]
            return snapshot

    def shutdown(self, wait: bool = True, timeout: Optional[float] = 5.0) -> None:
        if self._shutdown.is_set():
            return

        self._shutdown.set()
        for _ in self._workers:
            try:
                self._event_queue.put_nowait((EventType.SHUTDOWN, None))
            except Exception:
                pass

        if wait:
            deadline = None if timeout is None else time.time() + timeout
            for worker in self._workers:
                remaining = None if deadline is None else max(0.0, deadline - time.time())
                worker.join(timeout=remaining)

    def _worker_loop(self) -> None:
        while not self._shutdown.is_set():
            try:
                event_type, payload = self._event_queue.get(timeout=0.25)
            except Empty:
                continue
            except Exception:
                logging.exception("Unexpected queue error")
                continue

            try:
                if event_type == EventType.SHUTDOWN:
                    return
                if event_type == EventType.CONSULTATION_REQUEST:
                    self._handle_consultation_request(payload)
                elif event_type == EventType.CLINICIAN_UPDATE:
                    self._handle_clinician_update(payload)
                elif event_type == EventType.EMERGENCY_ALERT:
                    self._handle_emergency_alert(payload)
                else:
                    logging.error("Unknown event type: %s", event_type)
            except Exception:
                logging.exception("Error while processing event: %s", event_type)
            finally:
                try:
                    self._event_queue.task_done()
                except Exception:
                    pass

    def _handle_consultation_request(self, request: ConsultationRequest) -> None:
        if not isinstance(request, ConsultationRequest):
            raise TypeError("payload must be ConsultationRequest")

        with self._cv:
            existing_request_id = self._patient_to_request.get(request.patient_id)
            if existing_request_id and existing_request_id in self._request_index:
                old_request = self._request_index[existing_request_id]
                if self._compute_priority_score(request) <= self._compute_priority_score(old_request):
                    logging.info(
                        "Ignored lower/equal priority duplicate request for patient %s",
                        request.patient_id,
                    )
                    return

            self._request_index[request.request_id] = request
            self._patient_to_request[request.patient_id] = request.request_id
            heap = self._queues.setdefault(request.specialty_needed, [])
            heapq.heappush(heap, self._make_prioritized_item(request))

            if self.HIGH_RISK_FLAGS.intersection(request.risk_flags):
                self.log_escalation(request, "high-risk consultation request")

            self._cv.notify_all()

    def _handle_clinician_update(self, update: ClinicianStatusUpdate) -> None:
        if not isinstance(update, ClinicianStatusUpdate):
            raise TypeError("payload must be ClinicianStatusUpdate")

        with self._cv:
            clinician = self._clinicians.get(update.clinician_id)
            if clinician is None:
                clinician = ClinicianRecord(
                    clinician_id=update.clinician_id,
                    specialty=update.specialty,
                    available=update.available,
                    capacity=update.capacity,
                )
                self._clinicians[update.clinician_id] = clinician
            else:
                clinician.specialty = update.specialty
                clinician.available = update.available
                clinician.capacity = update.capacity
                if len(clinician.assigned_patients) > clinician.capacity:
                    logging.warning(
                        "Clinician %s capacity reduced below current assignments",
                        clinician.clinician_id,
                    )

            self._cv.notify_all()

    def _handle_emergency_alert(self, alert: EmergencyAlert) -> None:
        if not isinstance(alert, EmergencyAlert):
            raise TypeError("payload must be EmergencyAlert")

        emergency_request = ConsultationRequest(
            request_id=f"emergency:{alert.patient_id}:{int(time.time() * 1000)}",
            patient_id=alert.patient_id,
            symptom_severity=alert.severity_override,
            wait_time_minutes=0,
            specialty_needed=alert.specialty_needed,
            risk_flags={"emergency"} | self.HIGH_RISK_FLAGS,
        )

        with self._cv:
            self._request_index[emergency_request.request_id] = emergency_request
            self._patient_to_request[emergency_request.patient_id] = emergency_request.request_id
            heap = self._queues.setdefault(emergency_request.specialty_needed, [])
            heapq.heappush(heap, self._make_prioritized_item(emergency_request))
            self.log_escalation(emergency_request, f"emergency alert: {alert.message or 'no message'}")
            self._cv.notify_all()

    def _find_available_clinician_locked(self, specialty: str) -> Optional[ClinicianRecord]:
        candidates = [
            clinician
            for clinician in self._clinicians.values()
            if clinician.specialty == specialty and clinician.can_accept()
        ]
        if not candidates:
            return None
        candidates.sort(key=lambda c: (len(c.assigned_patients), c.clinician_id))
        return candidates[0]

    def __enter__(self) -> "TelemedicineScheduler":
        return self

    def __exit__(self, exc_type, exc, tb) -> None:
        self.shutdown(wait=True)


if __name__ == "__main__":
    scheduler = TelemedicineScheduler(worker_count=3)

    try:
        scheduler.update_clinician_status(
            ClinicianStatusUpdate(clinician_id="c1", specialty="cardiology", available=True, capacity=2)
        )
        scheduler.update_clinician_status(
            ClinicianStatusUpdate(clinician_id="c2", specialty="neurology", available=True, capacity=1)
        )

        scheduler.add_consultation_request(
            ConsultationRequest(
                request_id="r1",
                patient_id="p1",
                symptom_severity=8,
                wait_time_minutes=20,
                specialty_needed="cardiology",
                risk_flags={"chest_pain"},
            )
        )
        scheduler.add_consultation_request(
            ConsultationRequest(
                request_id="r2",
                patient_id="p2",
                symptom_severity=5,
                wait_time_minutes=45,
                specialty_needed="cardiology",
                risk_flags=set(),
            )
        )
        scheduler.submit_emergency_alert(
            EmergencyAlert(patient_id="p3", specialty_needed="neurology", message="possible stroke")
        )

        time.sleep(0.5)

        next_cardio = scheduler.fetch_next_highest_priority_patient("cardiology")
        next_neuro = scheduler.fetch_next_highest_priority_patient("neurology")

        print("Next cardiology:", next_cardio)
        print("Next neurology:", next_neuro)
        print("Escalations:", scheduler.get_escalation_log())

        if next_cardio:
            scheduler.complete_consultation("c1", next_cardio.patient_id)

    finally:
        scheduler.shutdown()

class VirtualMachine:
    def __init__(self, vm_id, name, cpu_cores, memory_gb, hourly_cost):
        self.vm_id = vm_id
        self.name = name
        self.cpu_cores = cpu_cores
        self.memory_gb = memory_gb
        self.hourly_cost = hourly_cost
        self.status = "stopped"

    def start(self):
        if self.status == "running":
            print(f"VM '{self.name}' is already running.")
        else:
            self.status = "running"
            print(f"VM '{self.name}' started successfully.")

    def stop(self):
        if self.status == "stopped":
            print(f"VM '{self.name}' is already stopped.")
        else:
            self.status = "stopped"
            print(f"VM '{self.name}' stopped successfully.")

    def display_info(self):
        print(f"VM ID       : {self.vm_id}")
        print(f"Name        : {self.name}")
        print(f"CPU Cores   : {self.cpu_cores}")
        print(f"Memory (GB) : {self.memory_gb}")
        print(f"Hourly Cost : ${self.hourly_cost:.2f}")
        print(f"Status      : {self.status}")
        print("-" * 35)


class CloudManager:
    def __init__(self):
        self.virtual_machines = []

    def find_vm_by_id(self, vm_id):
        for vm in self.virtual_machines:
            if vm.vm_id == vm_id:
                return vm
        return None

    def add_virtual_machine(self, vm):
        if self.find_vm_by_id(vm.vm_id) is not None:
            print(f"Error: A VM with ID '{vm.vm_id}' already exists.")
            return False
        self.virtual_machines.append(vm)
        print(f"VM '{vm.name}' added successfully.")
        return True

    def list_virtual_machines(self):
        if not self.virtual_machines:
            print("No virtual machines found.")
            return

        print("\nList of Virtual Machines")
        print("=" * 35)
        for vm in self.virtual_machines:
            vm.display_info()

    def start_vm(self, vm_id):
        vm = self.find_vm_by_id(vm_id)
        if vm is None:
            print(f"Error: No VM found with ID '{vm_id}'.")
        else:
            vm.start()

    def stop_vm(self, vm_id):
        vm = self.find_vm_by_id(vm_id)
        if vm is None:
            print(f"Error: No VM found with ID '{vm_id}'.")
        else:
            vm.stop()

    def calculate_total_running_cost(self):
        total_cost = 0
        for vm in self.virtual_machines:
            if vm.status == "running":
                total_cost += vm.hourly_cost
        return total_cost


def get_positive_int(prompt):
    while True:
        value = input(prompt).strip()
        try:
            number = int(value)
            if number > 0:
                return number
            else:
                print("Please enter a positive whole number.")
        except ValueError:
            print("Invalid input. Please enter a whole number.")


def get_positive_float(prompt):
    while True:
        value = input(prompt).strip()
        try:
            number = float(value)
            if number >= 0:
                return number
            else:
                print("Please enter a number greater than or equal to 0.")
        except ValueError:
            print("Invalid input. Please enter a valid number.")


def show_menu():
    print("\nCloud Resource Manager")
    print("=" * 25)
    print("1. Add Virtual Machine")
    print("2. List All Virtual Machines")
    print("3. Start a Virtual Machine")
    print("4. Stop a Virtual Machine")
    print("5. Show Total Hourly Cost of Running VMs")
    print("6. Exit")


def main():
    manager = CloudManager()

    while True:
        show_menu()
        choice = input("Enter your choice (1-6): ").strip()

        if choice == "1":
            print("\nAdd New Virtual Machine")
            print("-" * 25)

            vm_id = input("Enter VM ID: ").strip()
            if vm_id == "":
                print("VM ID cannot be empty.")
                continue

            if manager.find_vm_by_id(vm_id) is not None:
                print(f"Error: A VM with ID '{vm_id}' already exists.")
                continue

            name = input("Enter VM name: ").strip()
            if name == "":
                print("VM name cannot be empty.")
                continue

            cpu_cores = get_positive_int("Enter number of CPU cores: ")
            memory_gb = get_positive_int("Enter memory size in GB: ")
            hourly_cost = get_positive_float("Enter hourly cost: $")

            vm = VirtualMachine(vm_id, name, cpu_cores, memory_gb, hourly_cost)
            manager.add_virtual_machine(vm)

        elif choice == "2":
            manager.list_virtual_machines()

        elif choice == "3":
            vm_id = input("Enter VM ID to start: ").strip()
            if vm_id == "":
                print("VM ID cannot be empty.")
            else:
                manager.start_vm(vm_id)

        elif choice == "4":
            vm_id = input("Enter VM ID to stop: ").strip()
            if vm_id == "":
                print("VM ID cannot be empty.")
            else:
                manager.stop_vm(vm_id)

        elif choice == "5":
            total_cost = manager.calculate_total_running_cost()
            print(f"Total hourly cost of running VMs: ${total_cost:.2f}")

        elif choice == "6":
            print("Exiting Cloud Resource Manager. Goodbye!")
            break

        else:
            print("Invalid choice. Please enter a number from 1 to 6.")


if __name__ == "__main__":
    main()

