import os
import logging
from functools import lru_cache
from typing import Dict, List, Optional, Any

import joblib
import numpy as np
from fastapi import FastAPI, HTTPException, Request
from fastapi.exceptions import RequestValidationError
from fastapi.responses import JSONResponse
from pydantic import BaseModel, Field, validator

# -----------------------------------------------------------------------------
# Configuration
# -----------------------------------------------------------------------------

APP_NAME = os.getenv("APP_NAME", "AI Diagnostic Support Service")
APP_VERSION = os.getenv("APP_VERSION", "1.0.0")
MODEL_PATH = os.getenv("MODEL_PATH", "model.joblib")
HOST = os.getenv("HOST", "0.0.0.0")
PORT = int(os.getenv("PORT", "8000"))
LOG_LEVEL = os.getenv("LOG_LEVEL", "INFO").upper()

logging.basicConfig(level=LOG_LEVEL)
logger = logging.getLogger(APP_NAME)

# -----------------------------------------------------------------------------
# Request / Response Schemas
# -----------------------------------------------------------------------------

class Vitals(BaseModel):
    temperature_c: float = Field(..., ge=30.0, le=45.0, description="Body temperature in Celsius")
    heart_rate: int = Field(..., ge=20, le=250, description="Heart rate in bpm")
    systolic_bp: int = Field(..., ge=50, le=300, description="Systolic blood pressure")
    diastolic_bp: int = Field(..., ge=30, le=200, description="Diastolic blood pressure")
    respiratory_rate: int = Field(..., ge=5, le=80, description="Respiratory rate")
    oxygen_saturation: float = Field(..., ge=50.0, le=100.0, description="SpO2 percentage")

    @validator("diastolic_bp")
    def validate_bp(cls, v: int, values: Dict[str, Any]) -> int:
        systolic = values.get("systolic_bp")
        if systolic is not None and v >= systolic:
            raise ValueError("diastolic_bp must be less than systolic_bp")
        return v


class PatientInput(BaseModel):
    age: int = Field(..., ge=0, le=120, description="Patient age")
    sex: str = Field(..., description="Patient sex: male, female, other")
    symptoms: List[str] = Field(..., min_items=1, description="List of symptoms")
    vitals: Vitals
    medical_history: Optional[List[str]] = Field(default_factory=list, description="Optional medical history items")

    @validator("sex")
    def validate_sex(cls, v: str) -> str:
        allowed = {"male", "female", "other"}
        value = v.strip().lower()
        if value not in allowed:
            raise ValueError(f"sex must be one of {sorted(allowed)}")
        return value

    @validator("symptoms", each_item=True)
    def validate_symptoms(cls, v: str) -> str:
        value = v.strip().lower()
        if not value:
            raise ValueError("symptom entries must not be empty")
        return value

    @validator("medical_history", each_item=True)
    def validate_history(cls, v: str) -> str:
        value = v.strip().lower()
        if not value:
            raise ValueError("medical_history entries must not be empty")
        return value


