# Fallback Model
# -----------------------------------------------------------------------------

class RuleBasedFallbackModel:
    """
    Simple fallback model used when no serialized model is available.
    It mimics a classifier with predict() and predict_proba() methods.
    """

    def predict(self, X: np.ndarray) -> List[str]:
        return [self._score_to_label(self._compute_score(row)) for row in X]

    def predict_proba(self, X: np.ndarray) -> np.ndarray:
        probs = []
        for row in X:
            score = self._compute_score(row)
            if score >= 7:
                probs.append([0.05, 0.20, 0.75])  # low, medium, high
            elif score >= 4:
                probs.append([0.15, 0.70, 0.15])
            else:
                probs.append([0.80, 0.15, 0.05])
        return np.array(probs)

    @staticmethod
    def _score_to_label(score: int) -> str:
        if score >= 7:
            return "high"
        if score >= 4:
            return "medium"
        return "low"

    @staticmethod
    def _compute_score(row: np.ndarray) -> int:
        (
            age,
            sex_encoded,
            symptom_count,
            history_count,
            temperature_c,
            heart_rate,
            systolic_bp,
            diastolic_bp,
            respiratory_rate,
            oxygen_saturation,
            fever_flag,
            chest_pain_flag,
            shortness_breath_flag,
            diabetes_flag,
            hypertension_flag,
        ) = row.tolist()

        score = 0

        if age >= 65:
            score += 2
        elif age >= 45:
            score += 1

        if symptom_count >= 4:
            score += 2
        elif symptom_count >= 2:
            score += 1

        if history_count >= 2:
            score += 1

        if temperature_c >= 39.0:
            score += 2
        elif temperature_c >= 38.0:
            score += 1

        if heart_rate >= 120:
            score += 2
        elif heart_rate >= 100:
            score += 1

        if respiratory_rate >= 30:
            score += 2
        elif respiratory_rate >= 22:
            score += 1

        if oxygen_saturation < 90:
            score += 3
        elif oxygen_saturation < 95:
            score += 1

        if systolic_bp < 90:
            score += 2

        if fever_flag:
            score += 1
        if chest_pain_flag:
            score += 2
        if shortness_breath_flag:
            score += 2
        if diabetes_flag:
            score += 1
        if hypertension_flag:
            score += 1

        return score


