class DiagnosticPredictor:
    def __init__(self, model_path: str):
        self.model_path = model_path
        self.model = self._load_model()
        self.model_loaded_from_disk = not isinstance(self.model, RuleBasedFallbackModel)

    def _load_model(self):
        try:
            if os.path.exists(self.model_path):
                logger.info("Loading model from %s", self.model_path)
                return joblib.load(self.model_path)
            logger.warning("Model file not found at %s. Using fallback model.", self.model_path)
        except Exception as exc:
            logger.exception("Failed to load model from disk: %s", exc)
        return RuleBasedFallbackModel()

    def _featurize(self, patient: PatientInput) -> np.ndarray:
        symptoms = {s.lower() for s in patient.symptoms}
        history = {h.lower() for h in (patient.medical_history or [])}

        sex_map = {"male": 0, "female": 1, "other": 2}

        features = np.array(
            [
                patient.age,
                sex_map[patient.sex],
                len(patient.symptoms),
                len(patient.medical_history or []),
                patient.vitals.temperature_c,
                patient.vitals.heart_rate,
                patient.vitals.systolic_bp,
                patient.vitals.diastolic_bp,
                patient.vitals.respiratory_rate,
                patient.vitals.oxygen_saturation,
                int("fever" in symptoms),
                int("chest pain" in symptoms),
                int("shortness of breath" in symptoms or "dyspnea" in symptoms),
                int("diabetes" in history),
                int("hypertension" in history),
            ],
            dtype=float,
        )
        return features.reshape(1, -1)

    def predict(self, patient: PatientInput) -> PredictionResponse:
        try:
            X = self._featurize(patient)
            prediction = self.model.predict(X)[0]

            confidence = None
            if hasattr(self.model, "predict_proba"):
                try:
                    proba = self.model.predict_proba(X)[0]
                    classes = getattr(self.model, "classes_", ["low", "medium", "high"])
                    class_to_prob = {str(cls): float(prob) for cls, prob in zip(classes, proba)}
                    confidence = class_to_prob.get(str(prediction), max(proba))
                except Exception:
                    confidence = None

            explanation = self._build_explanation(patient, str(prediction), confidence)
            return PredictionResponse(risk_category=str(prediction), explanation=explanation)

        except Exception as exc:
            logger.exception("Prediction failed: %s", exc)
            raise HTTPException(status_code=500, detail="Prediction failed due to an internal error")

    @staticmethod
    def _build_explanation(
        patient: PatientInput,
        risk_category: str,
        confidence: Optional[float] = None,
    ) -> str:
        reasons = []

        if patient.age >= 65:
            reasons.append("advanced age")
        if patient.vitals.temperature_c >= 38.0:
            reasons.append("elevated temperature")
        if patient.vitals.heart_rate >= 100:
            reasons.append("tachycardia")
        if patient.vitals.respiratory_rate >= 22:
            reasons.append("increased respiratory rate")
        if patient.vitals.oxygen_saturation < 95:
            reasons.append("reduced oxygen saturation")

        symptom_set = {s.lower() for s in patient.symptoms}
        if "chest pain" in symptom_set:
            reasons.append("chest pain")
        if "shortness of breath" in symptom_set or "dyspnea" in symptom_set:
            reasons.append("shortness of breath")

        if not reasons:
            reasons.append("currently limited high-risk indicators")

        base = f"Predicted {risk_category} risk based on " + ", ".join(reasons[:4]) + "."
        if confidence is not None:
            base += f" Estimated model confidence: {confidence:.2f}."
        return base


