from dataclasses import dataclass


@dataclass
class Model:
    name: str
    version: str
    framework: str
    status: str

    def matches(self, keyword: str) -> bool:
        keyword = keyword.lower().strip()
        return (
            keyword in self.name.lower()
            or keyword in self.version.lower()
            or keyword in self.framework.lower()
            or keyword in self.status.lower()
        )

    def __str__(self) -> str:
        return (
            f"Name: {self.name} | "
            f"Version: {self.version} | "
            f"Framework: {self.framework} | "
            f"Status: {self.status}"
        )


class ModelRegistry:
    def __init__(self):
        self.models = []

    def add_model(self, model: Model) -> bool:
        if self.find_exact_model(model.name, model.version) is not None:
            return False
        self.models.append(model)
        return True

    def list_models(self):
        return self.models

    def search_models(self, keyword: str):
        return [model for model in self.models if model.matches(keyword)]

    def find_exact_model(self, name: str, version: str):
        for model in self.models:
            if model.name.lower() == name.lower() and model.version.lower() == version.lower():
                return model
        return None

    def delete_model(self, name: str, version: str) -> bool:
        model = self.find_exact_model(name, version)
        if model is not None:
            self.models.remove(model)
            return True
        return False


