from __future__ import annotations

import base64
import json
import os
import shutil
import tempfile
import threading
import unittest
from contextlib import AbstractContextManager
from dataclasses import dataclass
from datetime import datetime, timedelta, timezone
from pathlib import Path
from typing import Any, Dict, Iterable, List, Mapping, Optional, Protocol


class ComplianceError(Exception):
    """Base exception for compliance and audit-related failures."""


class EventValidationError(ComplianceError):
    """Raised when an event payload is malformed or missing required fields."""


class ResourceLifecycleError(ComplianceError):
    """Raised when a managed resource cannot be opened, written, or closed safely."""


class ArchivalError(ComplianceError):
    """Raised when retention or archival operations fail."""


class EncryptionProvider(Protocol):
    def encrypt(self, data: bytes) -> bytes:
        ...

    def decrypt(self, data: bytes) -> bytes:
        ...


class SimpleXOREncryptionProvider:
    """
    Test-friendly encryption provider.

    This is not cryptographically secure and is intended only for demonstration
    and unit testing in a self-contained module.
    """

    def __init__(self, key: bytes) -> None:
        if not key:
            raise ValueError("Encryption key must not be empty.")
        self._key = key

    def encrypt(self, data: bytes) -> bytes:
        xored = bytes(b ^ self._key[i % len(self._key)] for i, b in enumerate(data))
        return base64.b64encode(xored)

    def decrypt(self, data: bytes) -> bytes:
        raw = base64.b64decode(data)
        return bytes(b ^ self._key[i % len(self._key)] for i, b in enumerate(raw))


@dataclass(frozen=True)
class RetentionPolicy:
    retention_days: int
    archive_enabled: bool = True

    def should_archive(self, created_at: datetime, now: Optional[datetime] = None) -> bool:
        now = now or datetime.now(timezone.utc)
        return created_at < now - timedelta(days=self.retention_days)


class Archiver(Protocol):
    def archive(self, source: Path, destination_dir: Path) -> Path:
        ...


class FileSystemArchiver:
    def archive(self, source: Path, destination_dir: Path) -> Path:
        destination_dir.mkdir(parents=True, exist_ok=True)
        destination = destination_dir / source.name
        shutil.move(str(source), str(destination))
        return destination


class SessionEventValidator:
    REQUIRED_BASE_FIELDS = {"event_type", "session_id", "timestamp"}
    ALLOWED_EVENT_TYPES = {
        "clinician_login",
        "patient_join",
        "patient_leave",
        "prescription_action",
        "file_access",
        "session_termination",
    }
    REQUIRED_BY_TYPE = {
        "clinician_login": {"clinician_id"},
        "patient_join": {"patient_id"},
        "patient_leave": {"patient_id"},
        "prescription_action": {"clinician_id", "patient_id", "prescription_id", "action"},
        "file_access": {"actor_id", "file_id", "access_type"},
        "session_termination": {"reason"},
    }

    def validate(self, event: Mapping[str, Any]) -> None:
        missing = self.REQUIRED_BASE_FIELDS - set(event.keys())
        if missing:
            raise EventValidationError(f"Missing required base fields: {sorted(missing)}")

        event_type = event.get("event_type")
        if event_type not in self.ALLOWED_EVENT_TYPES:
            raise EventValidationError(f"Unsupported event_type: {event_type!r}")

        session_id = event.get("session_id")
        if not isinstance(session_id, str) or not session_id.strip():
            raise EventValidationError("session_id must be a non-empty string")

        timestamp = event.get("timestamp")
        if not isinstance(timestamp, str):
            raise EventValidationError("timestamp must be an ISO-8601 UTC string")
        if not timestamp.endswith("Z"):
            raise EventValidationError("timestamp must be in UTC and end with 'Z'")

        required_specific = self.REQUIRED_BY_TYPE.get(event_type, set())
        missing_specific = required_specific - set(event.keys())
        if missing_specific:
            raise EventValidationError(
                f"Missing required fields for {event_type}: {sorted(missing_specific)}"
            )

        for key, value in event.items():
            if value is None:
                raise EventValidationError(f"Field {key!r} must not be None")


class SessionScopedLockRegistry:
    def __init__(self) -> None:
        self._global_lock = threading.RLock()
        self._locks: Dict[str, threading.RLock] = {}

    def get_lock(self, session_id: str) -> threading.RLock:
        with self._global_lock:
            lock = self._locks.get(session_id)
            if lock is None:
                lock = threading.RLock()
                self._locks[session_id] = lock
            return lock


class BaseSessionResource(AbstractContextManager):
    def __init__(self, session_id: str) -> None:
        self.session_id = session_id
        self._entered = False

    def __enter__(self) -> "BaseSessionResource":
        self._entered = True
        return self

    def __exit__(self, exc_type, exc, tb) -> bool:
        self._entered = False
        return False


class TranscriptResource(BaseSessionResource):
    def __init__(self, session_id: str, path: Path) -> None:
        super().__init__(session_id)
        self.path = path
        self._fh: Optional[Any] = None
        self._lock = threading.RLock()

    def __enter__(self) -> "TranscriptResource":
        super().__enter__()
        try:
            self.path.parent.mkdir(parents=True, exist_ok=True)
            self._fh = self.path.open("a", encoding="utf-8")
            return self
        except OSError as exc:
            raise ResourceLifecycleError(f"Failed to open transcript resource: {exc}") from exc

    def append(self, line: str) -> None:
        if not self._fh:
            raise ResourceLifecycleError("Transcript resource is not open")
        with self._lock:
            self._fh.write(line + "\n")
            self._fh.flush()

    def __exit__(self, exc_type, exc, tb) -> bool:
        try:
            if self._fh:
                self._fh.close()
        except OSError as exc2:
            raise ResourceLifecycleError(f"Failed to close transcript resource: {exc2}") from exc2
        finally:
            self._fh = None
        return super().__exit__(exc_type, exc, tb)


class BillingTrackerResource(BaseSessionResource):
    def __init__(self, session_id: str) -> None:
        super().__init__(session_id)
        self._entries: List[Dict[str, Any]] = []
        self._lock = threading.RLock()

    def add_charge(self, code: str, amount: float, description: str) -> None:
        if not self._entered:
            raise ResourceLifecycleError("Billing tracker is not active")
        if not code or amount < 0:
            raise ComplianceError("Invalid billing entry")
        with self._lock:
            self._entries.append(
                {
                    "code": code,
                    "amount": amount,
                    "description": description,
                    "timestamp": utc_now_iso(),
                }
            )

    @property
    def entries(self) -> List[Dict[str, Any]]:
        with self._lock:
            return list(self._entries)


class EncryptedAuditLog(BaseSessionResource):
    def __init__(
        self,
        session_id: str,
        path: Path,
        encryption_provider: EncryptionProvider,
        validator: Optional[SessionEventValidator] = None,
        lock_registry: Optional[SessionScopedLockRegistry] = None,
    ) -> None:
        super().__init__(session_id)
        self.path = path
        self.encryption_provider = encryption_provider
        self.validator = validator or SessionEventValidator()
        self._fh: Optional[Any] = None
        self._lock_registry = lock_registry or SessionScopedLockRegistry()
        self._session_lock = self._lock_registry.get_lock(session_id)

    def __enter__(self) -> "EncryptedAuditLog":
        super().__enter__()
        try:
            self.path.parent.mkdir(parents=True, exist_ok=True)
            self._fh = self.path.open("ab")
            return self
        except OSError as exc:
            raise ResourceLifecycleError(f"Failed to open audit log: {exc}") from exc

    def log_event(self, event_type: str, **payload: Any) -> Dict[str, Any]:
        event = {
            "event_type": event_type,
            "session_id": self.session_id,
            "timestamp": utc_now_iso(),
            **payload,
        }
        self.validator.validate(event)
        self._write_event(event)
        return event

    def _write_event(self, event: Mapping[str, Any]) -> None:
        if not self._fh:
            raise ResourceLifecycleError("Audit log is not open")
        try:
            serialized = json.dumps(event, sort_keys=True, separators=(",", ":")).encode("utf-8")
            encrypted = self.encryption_provider.encrypt(serialized) + b"\n"
            with self._session_lock:
                self._fh.write(encrypted)
                self._fh.flush()
                os.fsync(self._fh.fileno())
        except (OSError, TypeError, ValueError) as exc:
            raise ResourceLifecycleError(f"Failed to write audit event: {exc}") from exc

    def read_events(self) -> List[Dict[str, Any]]:
        if self._fh and not self._fh.closed:
            self._fh.flush()
        events: List[Dict[str, Any]] = []
        if not self.path.exists():
            return events
        with self._session_lock:
            with self.path.open("rb") as fh:
                for line in fh:
                    line = line.strip()
                    if not line:
                        continue
                    decrypted = self.encryption_provider.decrypt(line)
                    events.append(json.loads(decrypted.decode("utf-8")))
        return events

    def __exit__(self, exc_type, exc, tb) -> bool:
        try:
            if self._fh:
                self._fh.close()
        except OSError as exc2:
            raise ResourceLifecycleError(f"Failed to close audit log: {exc2}") from exc2
        finally:
            self._fh = None
        return super().__exit__(exc_type, exc, tb)


class SessionLogManager:
    def __init__(
        self,
        base_dir: Path,
        encryption_provider: EncryptionProvider,
        retention_policy: Optional[RetentionPolicy] = None,
        archiver: Optional[Archiver] = None,
        validator: Optional[SessionEventValidator] = None,
        lock_registry: Optional[SessionScopedLockRegistry] = None,
    ) -> None:
        self.base_dir = Path(base_dir)
        self.encryption_provider = encryption_provider
        self.retention_policy = retention_policy or RetentionPolicy(retention_days=30)
        self.archiver = archiver or FileSystemArchiver()
        self.validator = validator or SessionEventValidator()
        self.lock_registry = lock_registry or SessionScopedLockRegistry()
        self._admin_lock = threading.RLock()

    def audit_log_path(self, session_id: str) -> Path:
        return self.base_dir / "audit" / f"{session_id}.audit.log"

    def transcript_path(self, session_id: str) -> Path:
        return self.base_dir / "transcripts" / f"{session_id}.txt"

    def archive_dir(self) -> Path:
        return self.base_dir / "archive"

    def open_audit_log(self, session_id: str) -> EncryptedAuditLog:
        return EncryptedAuditLog(
            session_id=session_id,
            path=self.audit_log_path(session_id),
            encryption_provider=self.encryption_provider,
            validator=self.validator,
            lock_registry=self.lock_registry,
        )

    def open_transcript(self, session_id: str) -> TranscriptResource:
        return TranscriptResource(session_id=session_id, path=self.transcript_path(session_id))

    def open_billing_tracker(self, session_id: str) -> BillingTrackerResource:
        return BillingTrackerResource(session_id=session_id)

    def archive_expired_logs(self, now: Optional[datetime] = None) -> List[Path]:
        archived: List[Path] = []
        audit_dir = self.base_dir / "audit"
        if not audit_dir.exists():
            return archived

        with self._admin_lock:
            try:
                for path in audit_dir.glob("*.audit.log"):
                    stat = path.stat()
                    created_at = datetime.fromtimestamp(stat.st_mtime, tz=timezone.utc)
                    if self.retention_policy.archive_enabled and self.retention_policy.should_archive(
                        created_at, now=now
                    ):
                        archived.append(self.archiver.archive(path, self.archive_dir()))
            except OSError as exc:
                raise ArchivalError(f"Failed during archival process: {exc}") from exc
        return archived


def utc_now_iso() -> str:
    return datetime.now(timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")


class TestTelemedicineSessionLogging(unittest.TestCase):
    def setUp(self) -> None:
        self.temp_dir = tempfile.TemporaryDirectory()
        self.base_dir = Path(self.temp_dir.name)
        self.encryption = SimpleXOREncryptionProvider(b"unit-test-key")
        self.manager = SessionLogManager(base_dir=self.base_dir, encryption_provider=self.encryption)

    def tearDown(self) -> None:
        self.temp_dir.cleanup()

    def test_normal_execution_logs_events(self) -> None:
