            audit.log_event(
                "prescription_action",
                clinician_id="clin-1",
                patient_id="pat-1",
                prescription_id="rx-1",
                action="create",
            )
            audit.log_event("session_termination", reason="completed")

        with self.manager.open_audit_log(session_id) as audit:
            events = audit.read_events()

        self.assertEqual(len(events), 4)
        self.assertEqual(events[0]["event_type"], "clinician_login")
        self.assertEqual(events[1]["event_type"], "patient_join")
        self.assertEqual(events[2]["event_type"], "prescription_action")
        self.assertEqual(events[3]["event_type"], "session_termination")

    def test_validation_rejects_malformed_event(self) -> None:
        session_id = "sess-002"
        with self.manager.open_audit_log(session_id) as audit:
            with self.assertRaises(EventValidationError):
                audit.log_event("patient_join")

    def test_cleanup_on_exception_inside_context(self) -> None:
        session_id = "sess-003"
        try:
            with self.manager.open_audit_log(session_id) as audit:
                audit.log_event("clinician_login", clinician_id="clin-2")
                raise RuntimeError("session failure")
        except RuntimeError:
            pass

        path = self.manager.audit_log_path(session_id)
        self.assertTrue(path.exists())

        with self.manager.open_audit_log(session_id) as audit:
            events = audit.read_events()
        self.assertEqual(len(events), 1)
        self.assertEqual(events[0]["event_type"], "clinician_login")

    def test_nested_resource_management(self) -> None:
        session_id = "sess-004"
        with self.manager.open_audit_log(session_id) as audit, self.manager.open_transcript(
            session_id
        ) as transcript, self.manager.open_billing_tracker(session_id) as billing:
            audit.log_event("clinician_login", clinician_id="clin-3")
            transcript.append("Consultation started.")
            billing.add_charge("CONSULT", 125.0, "Virtual consultation")
            audit.log_event("file_access", actor_id="clin-3", file_id="lab-1", access_type="read")
            audit.log_event("session_termination", reason="completed")

        with self.manager.open_audit_log(session_id) as audit:
            events = audit.read_events()
        self.assertEqual(len(events), 3)
        self.assertTrue(self.manager.transcript_path(session_id).exists())

    def test_concurrent_sessions_thread_safe(self) -> None:
        errors: List[Exception] = []
        session_ids = [f"sess-thread-{i}" for i in range(8)]

        def worker(session_id: str) -> None:
            try:
                with self.manager.open_audit_log(session_id) as audit:
                    audit.log_event("clinician_login", clinician_id=f"clin-{session_id}")
                    audit.log_event("patient_join", patient_id=f"pat-{session_id}")
                    audit.log_event("patient_leave", patient_id=f"pat-{session_id}")
                    audit.log_event("session_termination", reason="completed")
            except Exception as exc:
                errors.append(exc)

        threads = [threading.Thread(target=worker, args=(sid,)) for sid in session_ids]
        for t in threads:
            t.start()
        for t in threads:
            t.join()

        self.assertEqual(errors, [])
        for sid in session_ids:
            with self.manager.open_audit_log(sid) as audit:
                events = audit.read_events()
            self.assertEqual(len(events), 4)
            self.assertEqual({e["session_id"] for e in events}, {sid})

    def test_archival_behavior(self) -> None:
        session_id = "sess-archive"
        with self.manager.open_audit_log(session_id) as audit:
            audit.log_event("clinician_login", clinician_id="clin-archive")

        path = self.manager.audit_log_path(session_id)
        old_time = datetime.now(timezone.utc) - timedelta(days=60)
        os.utime(path, (old_time.timestamp(), old_time.timestamp()))

        manager = SessionLogManager(
            base_dir=self.base_dir,
            encryption_provider=self.encryption,
            retention_policy=RetentionPolicy(retention_days=30, archive_enabled=True),
        )
        archived = manager.archive_expired_logs(now=datetime.now(timezone.utc))
        self.assertEqual(len(archived), 1)
        self.assertFalse(path.exists())
        self.assertTrue(archived[0].exists())


