    unittest.main()

#!/usr/bin/env python3
import argparse
import csv
import json
import heapq
import logging
import os
import sys
from collections import defaultdict, deque
from datetime import datetime, timedelta, timezone
from itertools import groupby


LOG = logging.getLogger("ehr_readmission")


def parse_args():
    parser = argparse.ArgumentParser(
        description="Stream NDJSON EHR events and compute 30-day readmission risk features."
    )
    parser.add_argument(
        "--input",
        nargs="+",
        required=True,
        help="One or more NDJSON input files containing EHR events.",
    )
    parser.add_argument(
        "--chronic-icd-file",
        required=True,
        help="Path to file containing chronic ICD codes, one per line.",
    )
    parser.add_argument(
        "--lab-thresholds-file",
        required=True,
        help="Path to JSON file with lab thresholds.",
    )
    parser.add_argument(
        "--output",
        required=True,
        help="Output CSV path.",
    )
    parser.add_argument(
        "--log-level",
        default="WARNING",
        choices=["DEBUG", "INFO", "WARNING", "ERROR", "CRITICAL"],
        help="Logging level.",
    )
    return parser.parse_args()


def setup_logging(level):
    logging.basicConfig(
        level=getattr(logging, level.upper(), logging.WARNING),
        format="%(asctime)s %(levelname)s %(message)s",
    )


def parse_datetime(value):
    if value is None:
        return None
    if isinstance(value, (int, float)):
        try:
            return datetime.fromtimestamp(value, tz=timezone.utc)
        except Exception:
            return None
    if not isinstance(value, str):
        return None
    s = value.strip()
    if not s:
        return None
    try:
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        dt = datetime.fromisoformat(s)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return dt
    except Exception:
        pass
    fmts = [
        "%Y-%m-%d %H:%M:%S",
        "%Y-%m-%d",
        "%m/%d/%Y %H:%M:%S",
        "%m/%d/%Y",
    ]
    for fmt in fmts:
        try:
            dt = datetime.strptime(s, fmt)
            return dt.replace(tzinfo=timezone.utc)
        except Exception:
            continue
    return None


def normalize_str(value):
    if value is None:
        return None
    return str(value).strip()


def normalize_code(value):
    s = normalize_str(value)
    if not s:
        return None
    return s.upper().replace(".", "")


def safe_float(value):
    if value is None or value == "":
        return None
    try:
        return float(value)
    except Exception:
        return None


def load_chronic_icd_codes(path):
    codes = set()
    with open(path, "r", encoding="utf-8") as f:
        for line_no, line in enumerate(f, 1):
            s = line.strip()
            if not s or s.startswith("#"):
                continue
            codes.add(normalize_code(s))
    return codes


def load_lab_thresholds(path):
    with open(path, "r", encoding="utf-8") as f:
        raw = json.load(f)
    thresholds = {}
    if not isinstance(raw, dict):
        raise ValueError("Lab thresholds file must contain a JSON object.")
    for lab_name, cfg in raw.items():
        if not isinstance(cfg, dict):
            continue
        key = normalize_str(lab_name)
        if not key:
            continue
        thresholds[key.lower()] = {
            "low": safe_float(cfg.get("low")),
            "high": safe_float(cfg.get("high")),
        }
    return thresholds


def infer_event_type(rec):
    candidates = [
        rec.get("event_type"),
        rec.get("type"),
        rec.get("record_type"),
        rec.get("resource_type"),
        rec.get("category"),
    ]
    for c in candidates:
        s = normalize_str(c)
        if s:
            return s.lower()
    if rec.get("discharge_time") or rec.get("discharge_date"):
        return "discharge"
    if rec.get("admission_time") or rec.get("admit_time") or rec.get("admission_date"):
        return "admission"
    if rec.get("diagnosis_code") or rec.get("icd_code"):
        return "diagnosis"
    if rec.get("procedure_code"):
        return "procedure"
    if rec.get("medication_name") or rec.get("med_name") or rec.get("medication_id"):
        return "medication"
    if rec.get("lab_name") or rec.get("test_name") or rec.get("lab_code"):
        return "lab"
    return "unknown"


def extract_timestamp(rec, event_type):
    keys_by_type = {
        "admission": ["admission_time", "admit_time", "admission_date", "timestamp", "event_time"],
        "discharge": ["discharge_time", "discharge_date", "timestamp", "event_time"],
        "diagnosis": ["diagnosis_time", "timestamp", "event_time"],
        "procedure": ["procedure_time", "timestamp", "event_time"],
        "medication": ["medication_time", "order_time", "administration_time", "timestamp", "event_time"],
        "lab": ["result_time", "collection_time", "timestamp", "event_time"],
        "unknown": ["timestamp", "event_time"],
    }
    keys = keys_by_type.get(event_type, keys_by_type["unknown"])
    for key in keys:
        dt = parse_datetime(rec.get(key))
        if dt is not None:
            return dt
    for key, value in rec.items():
        if "time" in key.lower() or "date" in key.lower():
            dt = parse_datetime(value)
            if dt is not None:
                return dt
    return None


def extract_patient_id(rec):
    for key in ("patient_id", "person_id", "member_id", "subject_id"):
        value = normalize_str(rec.get(key))
        if value:
            return value
    return None


def extract_encounter_id(rec):
    for key in ("encounter_id", "visit_id", "admission_id", "stay_id"):
        value = normalize_str(rec.get(key))
        if value:
            return value
    return None


def extract_birth_date(rec):
    for key in ("birth_date", "date_of_birth", "dob"):
        dt = parse_datetime(rec.get(key))
        if dt is not None:
            return dt
    return None


def canonicalize_record(raw, source_file, line_no):
    if not isinstance(raw, dict):
        return None, "record_not_object"
    patient_id = extract_patient_id(raw)
    encounter_id = extract_encounter_id(raw)
    event_type = infer_event_type(raw)
    timestamp = extract_timestamp(raw, event_type)
    if not patient_id:
        return None, "missing_patient_id"
    if not encounter_id:
        return None, "missing_encounter_id"
    if timestamp is None:
        return None, "missing_timestamp"
    rec = {
        "patient_id": patient_id,
        "encounter_id": encounter_id,
        "event_type": event_type,
        "timestamp": timestamp,
        "source_file": source_file,
        "line_no": line_no,
        "raw": raw,
    }
    return rec, None


def iter_ndjson_records(path):
    with open(path, "r", encoding="utf-8") as f:
        for line_no, line in enumerate(f, 1):
            s = line.strip()
            if not s:
                continue
            try:
                raw = json.loads(s)
            except json.JSONDecodeError:
                LOG.warning("Malformed JSON skipped: %s:%s", path, line_no)
                continue
            rec, err = canonicalize_record(raw, path, line_no)
            if err:
                LOG.warning("Invalid record skipped (%s): %s:%s", err, path, line_no)
                continue
            yield rec


def sorted_record_stream(paths):
    streams = [iter_ndjson_records(path) for path in paths]
    return heapq.merge(
        *streams,
        key=lambda r: (
            r["patient_id"],
            r["encounter_id"],
            r["timestamp"],
            r["event_type"],
            r["source_file"],
            r["line_no"],
        ),
    )


def dedupe_records(records):
    seen = set()
    for rec in records:
        raw = rec["raw"]
        raw_sig = json.dumps(raw, sort_keys=True, separators=(",", ":"), default=str)
        sig = (
            rec["patient_id"],
            rec["encounter_id"],
            rec["event_type"],
            rec["timestamp"].isoformat(),
            raw_sig,
        )
        if sig in seen:
            continue
        seen.add(sig)
        yield rec


def group_encounters(records):
    keyfunc = lambda r: (r["patient_id"], r["encounter_id"])
    for (patient_id, encounter_id), grp in groupby(records, key=keyfunc):
        yield patient_id, encounter_id, dedupe_records(grp)


def age_in_years(birth_dt, ref_dt):
    if birth_dt is None or ref_dt is None:
        return None
    years = ref_dt.year - birth_dt.year
    if (ref_dt.month, ref_dt.day) < (birth_dt.month, birth_dt.day):
        years -= 1
    return years if years >= 0 else None


def days_between(start, end):
    if start is None or end is None:
        return None
    delta = end - start
    return round(delta.total_seconds() / 86400.0, 4)


def extract_diagnosis_code(raw):
    for key in ("diagnosis_code", "icd_code", "code"):
        code = normalize_code(raw.get(key))
        if code:
            return code
    return None


def extract_lab_name(raw):
    for key in ("lab_name", "test_name", "lab_code", "name"):
        value = normalize_str(raw.get(key))
        if value:
            return value.lower()
    return None


def extract_lab_value(raw):
    for key in ("result_value", "value", "lab_value", "numeric_value"):
        val = safe_float(raw.get(key))
        if val is not None:
            return val
    return None


def extract_med_signature(raw):
    med = None
    for key in ("medication_name", "med_name", "medication_id", "drug_name"):
        med = normalize_str(raw.get(key))
        if med:
            break
    action = None
    for key in ("action", "status", "change_type", "event_subtype"):
        action = normalize_str(raw.get(key))
        if action:
            break
    dose = None
    for key in ("dose", "dosage", "strength"):
        dose = normalize_str(raw.get(key))
        if dose:
            break
    route = normalize_str(raw.get("route"))
    return (med or "", action or "", dose or "", route or "")


def build_encounter_summary(patient_id, encounter_id, records, chronic_codes, lab_thresholds):
    records = list(records)
    if not records:
        return None

    records.sort(key=lambda r: (r["timestamp"], r["event_type"], r["line_no"]))

    admission_time = None
    discharge_time = None
    birth_date = None
    chronic_codes_seen = set()
    abnormal_lab_count = 0
    medication_changes = 0
    med_prev = {}
    med_event_seen = set()

    for rec in records:
        raw = rec["raw"]
        event_type = rec["event_type"]
        ts = rec["timestamp"]

        if birth_date is None:
            birth_date = extract_birth_date(raw)

        if event_type == "admission":
            if admission_time is None or ts < admission_time:
                admission_time = ts
        elif event_type == "discharge":
            if discharge_time is None or ts > discharge_time:
                discharge_time = ts

        if event_type == "diagnosis":
            code = extract_diagnosis_code(raw)
            if code and code in chronic_codes:
                chronic_codes_seen.add(code)

        elif event_type == "lab":
            lab_name = extract_lab_name(raw)
            lab_value = extract_lab_value(raw)
            if lab_name and lab_value is not None:
                cfg = lab_thresholds.get(lab_name)
                if cfg:
                    low = cfg.get("low")
                    high = cfg.get("high")
                    if (low is not None and lab_value < low) or (high is not None and lab_value > high):
                        abnormal_lab_count += 1

        elif event_type == "medication":
            sig = extract_med_signature(raw)
            med_key = sig[0]
            if med_key:
                event_sig = (med_key, sig[1], sig[2], sig[3], ts.isoformat())
                if event_sig not in med_event_seen:
                    med_event_seen.add(event_sig)
                    prev = med_prev.get(med_key)
                    curr = (sig[1], sig[2], sig[3])
                    if prev is None:
                        medication_changes += 1
                    elif prev != curr:
                        medication_changes += 1
                    med_prev[med_key] = curr

    if admission_time is None:
        admission_time = min((r["timestamp"] for r in records), default=None)
    if discharge_time is None:
        discharge_time = max((r["timestamp"] for r in records), default=None)

    if admission_time is None or discharge_time is None:
        return None

    if discharge_time < admission_time:
        admission_time, discharge_time = discharge_time, admission_time

    return {
        "patient_id": patient_id,
        "encounter_id": encounter_id,
        "admission_time": admission_time,
        "discharge_time": discharge_time,
        "length_of_stay_days": days_between(admission_time, discharge_time),
        "age_at_admission": age_in_years(birth_date, admission_time),
        "chronic_diagnosis_count": len(chronic_codes_seen),
        "abnormal_lab_count": abnormal_lab_count,
        "medication_changes": medication_changes,
        "is_inpatient_discharge": True,
    }


def iter_encounter_summaries(paths, chronic_codes, lab_thresholds):
    records = sorted_record_stream(paths)
    for patient_id, encounter_id, encounter_records in group_encounters(records):
        summary = build_encounter_summary(
            patient_id, encounter_id, encounter_records, chronic_codes, lab_thresholds
        )
        if summary is not None:
            yield summary


def compute_readmission_rows(encounter_summaries):
    current_patient = None
    patient_encounters = []

    def flush_patient(encounters):
        if not encounters:
            return
        encounters.sort(key=lambda e: (e["admission_time"], e["discharge_time"], e["encounter_id"]))

        prior_admissions = deque()
        n = len(encounters)

        for i, enc in enumerate(encounters):
            admit = enc["admission_time"]
            while prior_admissions and prior_admissions[0] < admit - timedelta(days=365):
                prior_admissions.popleft()
            prior_count = len(prior_admissions)

            readmitted_30d = 0
            for j in range(i + 1, n):
                next_enc = encounters[j]
                next_admit = next_enc["admission_time"]
                if next_admit < enc["discharge_time"]:
                    continue
                delta = next_admit - enc["discharge_time"]
                if delta <= timedelta(days=30):
                    readmitted_30d = 1
                    break
                if delta > timedelta(days=30):
                    break

            row = {
                "patient_id": enc["patient_id"],
                "encounter_id": enc["encounter_id"],
                "discharge_date": enc["discharge_time"].date().isoformat(),
                "readmitted_30d": readmitted_30d,
                "prior_admissions_12m": prior_count,
                "chronic_diagnosis_count": enc["chronic_diagnosis_count"],
                "abnormal_lab_count": enc["abnormal_lab_count"],
                "medication_changes": enc["medication_changes"],
                "length_of_stay_days": enc["length_of_stay_days"],
                "age_at_admission": enc["age_at_admission"],
            }
            yield row
            prior_admissions.append(admit)

    for enc in encounter_summaries:
        patient_id = enc["patient_id"]
        if current_patient is None:
            current_patient = patient_id
        if patient_id != current_patient:
            for row in flush_patient(patient_encounters):
                yield row
            patient_encounters = []
            current_patient = patient_id
        patient_encounters.append(enc)

    for row in flush_patient(patient_encounters):
        yield row


def write_csv(rows, output_path):
    fieldnames = [
        "patient_id",
        "encounter_id",
        "discharge_date",
        "readmitted_30d",
        "prior_admissions_12m",
        "chronic_diagnosis_count",
        "abnormal_lab_count",
        "medication_changes",
        "length_of_stay_days",
        "age_at_admission",
    ]
    with open(output_path, "w", newline="", encoding="utf-8") as f:
        writer = csv.DictWriter(f, fieldnames=fieldnames)
        writer.writeheader()
        for row in rows:
            writer.writerow(row)


def validate_inputs(args):
    for path in args.input:
        if not os.path.exists(path):
            raise FileNotFoundError(f"Input file not found: {path}")
    if not os.path.exists(args.chronic_icd_file):
        raise FileNotFoundError(f"Chronic ICD file not found: {args.chronic_icd_file}")
    if not os.path.exists(args.lab_thresholds_file):
        raise FileNotFoundError(f"Lab thresholds file not found: {args.lab_thresholds_file}")


def main():
    args = parse_args()
    setup_logging(args.log_level)
    validate_inputs(args)

    chronic_codes = load_chronic_icd_codes(args.chronic_icd_file)
    lab_thresholds = load_lab_thresholds(args.lab_thresholds_file)

    encounter_summaries = iter_encounter_summaries(
        args.input,
        chronic_codes=chronic_codes,
        lab_thresholds=lab_thresholds,
    )
    rows = compute_readmission_rows(encounter_summaries)
    write_csv(rows, args.output)


if __name__ == "__main__":
    try:
        main()
    except BrokenPipeError:
        try:
            sys.stdout.close()
        except Exception:
            pass
    except Exception as exc:
        logging.basicConfig(level=logging.ERROR, format="%(asctime)s %(levelname)s %(message)s")
        LOG.exception("Fatal error: %s", exc)
        sys.exit(1)

