def get_over_provisioned_services(records: List[Dict[str, Any]]) -> List[str]:
    allowed_platforms = {"AWS", "Azure"}
    return [
        record["service_name"]
        for record in records
        if record["platform"] in allowed_platforms
        and record["allocated_instances"] - record["active_instances"] >= 3
    ]


