def summarize_ehr(patient_name, age, current_medications, allergy_information):
    # Validate patient_name
    if not isinstance(patient_name, str) or patient_name.strip() == "":
        raise ValueError("patient_name must be a non-empty string.")

    # Validate age
    if not isinstance(age, int) or age < 0:
        raise ValueError("age must be a non-negative integer.")

    # Validate current_medications
    if not isinstance(current_medications, list):
        raise ValueError("current_medications must be a list of strings.")
    for medication in current_medications:
        if not isinstance(medication, str):
            raise ValueError("Each medication must be a string.")

    # Validate allergy_information
    if not isinstance(allergy_information, dict):
        raise ValueError("allergy_information must be a dictionary.")
    for allergen, reaction in allergy_information.items():
        if not isinstance(allergen, str) or not isinstance(reaction, str):
            raise ValueError("All allergy keys and values must be strings.")

    # Count medications and allergies
    total_medications = len(current_medications)
    total_allergies = len(allergy_information)

    # Create the summary dictionary
    patient_summary = {
        "patient_name": patient_name,
        "age": age,
        "total_medications": total_medications,
        "total_recorded_allergies": total_allergies,
    }

    # Create an age-based warning message
    if age >= 65:
        warning_message = "Warning: Patient is age 65 or older."
    else:
        warning_message = "No age-based warning"

    # Return both the summary and warning message
    return patient_summary, warning_message


