    print(summary)
    print(warning)

from __future__ import annotations

from abc import ABC, abstractmethod
from collections import defaultdict, deque
from dataclasses import dataclass
from datetime import datetime, timedelta
from typing import Any, Deque, Dict, Iterable, List, Optional


@dataclass(frozen=True)
class Transaction:
    """
    Represents a financial transaction.
    """

    transaction_id: str
    account_id: str
    amount: float
    timestamp: datetime
    country: str
    merchant_category: str

    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> "Transaction":
        """
        Create a Transaction instance from a dictionary with validation.
        """
        required_fields = {
            "transaction_id",
            "account_id",
            "amount",
            "timestamp",
            "country",
            "merchant_category",
        }
        if not isinstance(data, dict):
            raise TypeError("Each transaction record must be a dictionary.")

        missing = required_fields - data.keys()
        if missing:
            raise ValueError(f"Missing required transaction fields: {sorted(missing)}")

        transaction_id = str(data["transaction_id"]).strip()
        account_id = str(data["account_id"]).strip()
        country = str(data["country"]).strip()
        merchant_category = str(data["merchant_category"]).strip()

        if not transaction_id:
            raise ValueError("transaction_id must be a non-empty string.")
        if not account_id:
            raise ValueError("account_id must be a non-empty string.")
        if not country:
            raise ValueError("country must be a non-empty string.")
        if not merchant_category:
            raise ValueError("merchant_category must be a non-empty string.")

        try:
            amount = float(data["amount"])
        except (TypeError, ValueError) as exc:
            raise ValueError("amount must be a numeric value.") from exc

        timestamp = cls._parse_timestamp(data["timestamp"])

        return cls(
            transaction_id=transaction_id,
            account_id=account_id,
            amount=amount,
            timestamp=timestamp,
            country=country,
            merchant_category=merchant_category,
        )

    @staticmethod
    def _parse_timestamp(value: Any) -> datetime:
        """
        Parse timestamp values from datetime objects or ISO-8601 strings.
        """
        if isinstance(value, datetime):
            return value

        if isinstance(value, str):
            text = value.strip()
            if not text:
                raise ValueError("timestamp string cannot be empty.")
            if text.endswith("Z"):
                text = text[:-1] + "+00:00"
            try:
                return datetime.fromisoformat(text)
            except ValueError as exc:
                raise ValueError(
                    f"Invalid timestamp format: {value!r}. Expected ISO-8601 string."
                ) from exc

        raise ValueError("timestamp must be a datetime object or ISO-8601 string.")


class FraudRule(ABC):
    """
    Abstract base class for fraud detection rules.
    """

    def __init__(self, name: str) -> None:
        if not name or not isinstance(name, str):
            raise ValueError("Rule name must be a non-empty string.")
        self.name = name

    @abstractmethod
    def apply(self, transactions: List[Transaction]) -> Dict[str, List[str]]:
        """
        Apply the rule to a list of transactions.

        Returns:
            Mapping of transaction_id to a list of triggered rule names.
        """
        raise NotImplementedError


class AmountThresholdRule(FraudRule):
    """
    Flags transactions whose amount exceeds a configured threshold.
    """

    def __init__(self, threshold: float) -> None:
        if threshold < 0:
            raise ValueError("amount_threshold must be non-negative.")
        super().__init__("amount_threshold_exceeded")
        self.threshold = float(threshold)

    def apply(self, transactions: List[Transaction]) -> Dict[str, List[str]]:
        flagged: Dict[str, List[str]] = defaultdict(list)
        for tx in transactions:
            if tx.amount > self.threshold:
                flagged[tx.transaction_id].append(self.name)
        return dict(flagged)


class CountryChangeWithinWindowRule(FraudRule):
    """
    Flags transactions for the same account when the country differs from the
    previous transaction and occurs within a configured time window.
    """

    def __init__(self, window_minutes: int) -> None:
        if window_minutes < 0:
            raise ValueError("country_change_window_minutes must be non-negative.")
        super().__init__("country_change_within_window")
        self.window = timedelta(minutes=window_minutes)

    def apply(self, transactions: List[Transaction]) -> Dict[str, List[str]]:
        flagged: Dict[str, List[str]] = defaultdict(list)
        previous_by_account: Dict[str, Transaction] = {}

        for tx in sorted(transactions, key=lambda t: (t.account_id, t.timestamp, t.transaction_id)):
            previous = previous_by_account.get(tx.account_id)
            if previous is not None:
                time_diff = tx.timestamp - previous.timestamp
                if (
                    time_diff >= timedelta(0)
                    and time_diff <= self.window
                    and tx.country != previous.country
                ):
                    flagged[tx.transaction_id].append(self.name)
            previous_by_account[tx.account_id] = tx

        return dict(flagged)


class VelocityRule(FraudRule):
    """
    Flags transactions when an account exceeds a configured number of transactions
    within a given time period.
    """

    def __init__(self, max_transactions: int, period_minutes: int) -> None:
        if max_transactions < 1:
            raise ValueError("velocity_max_transactions must be at least 1.")
        if period_minutes < 0:
            raise ValueError("velocity_period_minutes must be non-negative.")
        super().__init__("transaction_velocity_exceeded")
        self.max_transactions = int(max_transactions)
        self.period = timedelta(minutes=period_minutes)

    def apply(self, transactions: List[Transaction]) -> Dict[str, List[str]]:
        flagged: Dict[str, List[str]] = defaultdict(list)
        account_windows: Dict[str, Deque[Transaction]] = defaultdict(deque)

        for tx in sorted(transactions, key=lambda t: (t.account_id, t.timestamp, t.transaction_id)):
            window = account_windows[tx.account_id]
            cutoff = tx.timestamp - self.period

            while window and window[0].timestamp < cutoff:
                window.popleft()

            window.append(tx)

            if len(window) > self.max_transactions:
                flagged[tx.transaction_id].append(self.name)

        return dict(flagged)


class FraudDetector:
    """
    Coordinates fraud detection by applying configured fraud rules to transactions.
    """

    def __init__(self, rules: Iterable[FraudRule]) -> None:
        self.rules = list(rules)
        if not self.rules:
            raise ValueError("At least one fraud rule must be provided.")

    def detect(self, transactions: List[Transaction]) -> List[Dict[str, Any]]:
        """
        Apply all rules and return flagged transactions with triggered rule names.
        """
        flagged_by_tx: Dict[str, Dict[str, Any]] = {}

        tx_lookup = {tx.transaction_id: tx for tx in transactions}

        for rule in self.rules:
            rule_results = rule.apply(transactions)
            for transaction_id, triggered_rules in rule_results.items():
                if transaction_id not in tx_lookup:
                    continue
                tx = tx_lookup[transaction_id]
                if transaction_id not in flagged_by_tx:
                    flagged_by_tx[transaction_id] = {
                        "transaction_id": tx.transaction_id,
                        "account_id": tx.account_id,
                        "rules_triggered": [],
                    }
                existing = flagged_by_tx[transaction_id]["rules_triggered"]
                for rule_name in triggered_rules:
                    if rule_name not in existing:
                        existing.append(rule_name)

        return sorted(
            flagged_by_tx.values(),
            key=lambda item: (item["account_id"], item["transaction_id"]),
        )


def _validate_config(config: Dict[str, Any]) -> Dict[str, Any]:
    """
    Validate and normalize the fraud detection configuration.
    """
    if not isinstance(config, dict):
        raise TypeError("config must be a dictionary.")

    required_keys = {
        "amount_threshold",
        "country_change_window_minutes",
        "velocity_max_transactions",
        "velocity_period_minutes",
    }
    missing = required_keys - config.keys()
    if missing:
        raise ValueError(f"Missing required config keys: {sorted(missing)}")

    try:
        normalized = {
            "amount_threshold": float(config["amount_threshold"]),
            "country_change_window_minutes": int(config["country_change_window_minutes"]),
            "velocity_max_transactions": int(config["velocity_max_transactions"]),
            "velocity_period_minutes": int(config["velocity_period_minutes"]),
        }
    except (TypeError, ValueError) as exc:
        raise ValueError("Configuration values must be numeric where applicable.") from exc

    if normalized["amount_threshold"] < 0:
        raise ValueError("amount_threshold must be non-negative.")
    if normalized["country_change_window_minutes"] < 0:
        raise ValueError("country_change_window_minutes must be non-negative.")
    if normalized["velocity_max_transactions"] < 1:
        raise ValueError("velocity_max_transactions must be at least 1.")
    if normalized["velocity_period_minutes"] < 0:
        raise ValueError("velocity_period_minutes must be non-negative.")

    return normalized


def detect_fraudulent_transactions(
    transaction_records: List[Dict[str, Any]],
    config: Dict[str, Any],
) -> List[Dict[str, Any]]:
    """
    Detect potentially fraudulent transactions using configurable business rules.

    Args:
        transaction_records:
            A list of transaction dictionaries. Each record must contain:
            transaction_id, account_id, amount, timestamp, country, merchant_category.
        config:
            A dictionary containing fraud rule thresholds:
                - amount_threshold
                - country_change_window_minutes
                - velocity_max_transactions
                - velocity_period_minutes

    Returns:
        A list of dictionaries for flagged transactions, each containing:
            - transaction_id
            - account_id
            - rules_triggered
    """
    if not isinstance(transaction_records, list):
        raise TypeError("transaction_records must be a list of dictionaries.")

    normalized_config = _validate_config(config)
    transactions = [Transaction.from_dict(record) for record in transaction_records]

    rules: List[FraudRule] = [
        AmountThresholdRule(normalized_config["amount_threshold"]),
        CountryChangeWithinWindowRule(
            normalized_config["country_change_window_minutes"]
        ),
        VelocityRule(
            normalized_config["velocity_max_transactions"],
            normalized_config["velocity_period_minutes"],
        ),
    ]

    detector = FraudDetector(rules)
    return detector.detect(transactions)

from __future__ import annotations

from datetime import datetime, timezone
from typing import Dict, Generator, Iterable, Iterator, Optional, Tuple, Any


EventKey = Tuple[str, str, str]


def _parse_utc_timestamp(value: str) -> datetime:
    if not isinstance(value, str):
        raise ValueError("timestamp must be an ISO 8601 UTC string")
    if value.endswith("Z"):
        value = value[:-1] + "+00:00"
    dt = datetime.fromisoformat(value)
    if dt.tzinfo is None:
        raise ValueError("timestamp must include UTC timezone information")
    dt = dt.astimezone(timezone.utc)
    return dt


def deployment_latency_summaries(
    records: Iterable[Dict[str, Any]],
) -> Iterator[Dict[str, Any]]:
    valid_event_types = {
        "build_started",
        "build_passed",
        "deploy_started",
        "deploy_succeeded",
        "deploy_failed",
    }

    states: Dict[EventKey, Dict[str, Optional[datetime]]] = {}

    for record in records:
        if not isinstance(record, dict):
            raise ValueError("each record must be a dictionary")

        try:
            service = record["service"]
            environment = record["environment"]
            commit_sha = record["commit_sha"]
            event_type = record["event_type"]
            timestamp_raw = record["timestamp"]
        except KeyError as exc:
            raise ValueError(f"missing required field: {exc.args[0]}") from None

        if event_type not in valid_event_types:
            raise ValueError(f"invalid event_type: {event_type}")

        timestamp = _parse_utc_timestamp(timestamp_raw)
        key: EventKey = (service, environment, commit_sha)
        state = states.get(key)

        if state is None:
            state = {
                "build_started": None,
                "build_passed": None,
                "deploy_started": None,
            }
            states[key] = state

        build_started = state["build_started"]
        build_passed = state["build_passed"]
        deploy_started = state["deploy_started"]

        if event_type == "build_started":
            if build_started is not None:
                raise ValueError(
                    f"duplicate build_started for service={service}, "
                    f"environment={environment}, commit_sha={commit_sha}"
                )
            state["build_started"] = timestamp

        elif event_type == "build_passed":
            if build_started is None:
                raise ValueError(
                    f"build_passed before build_started for service={service}, "
                    f"environment={environment}, commit_sha={commit_sha}"
                )
            if build_passed is not None:
                raise ValueError(
                    f"duplicate build_passed for service={service}, "
                    f"environment={environment}, commit_sha={commit_sha}"
                )
            if timestamp < build_started:
                raise ValueError(
                    f"build_passed timestamp before build_started for service={service}, "
                    f"environment={environment}, commit_sha={commit_sha}"
                )
            state["build_passed"] = timestamp

        elif event_type == "deploy_started":
            if build_started is None:
                raise ValueError(
                    f"deploy_started before build_started for service={service}, "
                    f"environment={environment}, commit_sha={commit_sha}"
                )
            if build_passed is None:
                raise ValueError(
                    f"deploy_started before build_passed for service={service}, "
                    f"environment={environment}, commit_sha={commit_sha}"
                )
            if deploy_started is not None:
                raise ValueError(
                    f"duplicate deploy_started for service={service}, "
                    f"environment={environment}, commit_sha={commit_sha}"
                )
            if timestamp < build_passed:
                raise ValueError(
                    f"deploy_started timestamp before build_passed for service={service}, "
                    f"environment={environment}, commit_sha={commit_sha}"
                )
            state["deploy_started"] = timestamp

        elif event_type == "deploy_succeeded":
            if build_started is None:
                raise ValueError(
                    f"deploy_succeeded before build_started for service={service}, "
                    f"environment={environment}, commit_sha={commit_sha}"
                )
            if build_passed is None:
                raise ValueError(
                    f"deploy_succeeded before build_passed for service={service}, "
                    f"environment={environment}, commit_sha={commit_sha}"
                )
            if deploy_started is None:
                raise ValueError(
                    f"deploy_succeeded before deploy_started for service={service}, "
                    f"environment={environment}, commit_sha={commit_sha}"
                )
            if timestamp < deploy_started:
                raise ValueError(
                    f"deploy_succeeded timestamp before deploy_started for service={service}, "
                    f"environment={environment}, commit_sha={commit_sha}"
                )

            summary = {
                "service": service,
                "environment": environment,
                "commit_sha": commit_sha,
                "build_duration_seconds": (build_passed - build_started).total_seconds(),
                "deploy_duration_seconds": (timestamp - deploy_started).total_seconds(),
                "total_lead_time_seconds": (timestamp - build_started).total_seconds(),
            }
            del states[key]
            yield summary

        elif event_type == "deploy_failed":
            if build_started is None:
                raise ValueError(
                    f"deploy_failed before build_started for service={service}, "
                    f"environment={environment}, commit_sha={commit_sha}"
                )
            if build_passed is None:
                raise ValueError(
                    f"deploy_failed before build_passed for service={service}, "
                    f"environment={environment}, commit_sha={commit_sha}"
                )
            if deploy_started is None:
                raise ValueError(
                    f"deploy_failed before deploy_started for service={service}, "
                    f"environment={environment}, commit_sha={commit_sha}"
                )
            if timestamp < deploy_started:
                raise ValueError(
                    f"deploy_failed timestamp before deploy_started for service={service}, "
                    f"environment={environment}, commit_sha={commit_sha}"
                )
            del states[key]

from __future__ import annotations

from collections import defaultdict, deque
from concurrent.futures import ThreadPoolExecutor, as_completed
from dataclasses import dataclass, field
from datetime import datetime, timezone
from threading import Lock
from typing import Any, Deque, Dict, Iterable, List, Optional, Tuple
import math
import os


@dataclass
class FraudConfig:
    """
    Assumptions:
    - Input is an iterable of dict-like transaction records with keys:
      transaction_id, account_id, timestamp, amount, merchant_category,
      country, device_id, ip_address
    - timestamp may be:
      * UNIX epoch seconds (int/float)
      * ISO-8601 string
      * datetime instance
    - Concurrency model:
      * Transactions are first normalized and globally sorted by timestamp.
      * Processing is then parallelized in chunks.
      * Shared state is protected with fine-grained locks.
      * To preserve rule correctness for time-dependent checks, workers acquire
        per-entity locks before reading/updating state.
      * For transactions touching multiple entities (account/device/ip), locks are
        acquired in a deterministic order to avoid deadlocks.
    - Performance considerations:
      * Uses bounded rolling windows via deque for memory efficiency.
      * Uses lock striping by entity key rather than a single global lock.
      * Suitable for high-volume streaming/batch scenarios where ordering by event
        time is acceptable before concurrent evaluation.
      * For true distributed/real-time systems, external state stores and partitioning
        by account/device/IP would be recommended.
    """

    max_workers: int = max(4, (os.cpu_count() or 4))
    chunk_size: int = 1000

    recent_amount_window: int = 20
    large_amount_min_history: int = 5
    large_amount_std_floor: float = 50.0
    large_amount_zscore_threshold: float = 3.0
    large_amount_absolute_floor: float = 1000.0

    rapid_txn_window_seconds: int = 120
    rapid_txn_count_threshold: int = 3

    geo_window_seconds: int = 3600

    shared_origin_window_seconds: int = 1800
    shared_origin_distinct_accounts_threshold: int = 3

    score_large_amount: int = 40
    score_rapid_successive: int = 25
    score_geo_inconsistency: int = 30
    score_shared_device: int = 20
    score_shared_ip: int = 20

    max_risk_score: int = 100


@dataclass
class NormalizedTransaction:
    transaction_id: str
    account_id: str
    timestamp: float
    amount: float
    merchant_category: Optional[str]
    country: Optional[str]
    device_id: Optional[str]
    ip_address: Optional[str]
    raw: Dict[str, Any] = field(default_factory=dict)


@dataclass
class AccountState:
    amount_history: Deque[float] = field(default_factory=deque)
    recent_timestamps: Deque[float] = field(default_factory=deque)
    recent_countries: Deque[Tuple[float, Optional[str]]] = field(default_factory=deque)


@dataclass
class OriginState:
    recent_accounts: Deque[Tuple[float, str]] = field(default_factory=deque)


class FraudDetector:
    def __init__(self, config: Optional[FraudConfig] = None) -> None:
        self.config = config or FraudConfig()

        self._account_states: Dict[str, AccountState] = {}
        self._device_states: Dict[str, OriginState] = {}
        self._ip_states: Dict[str, OriginState] = {}

        self._account_locks: Dict[str, Lock] = defaultdict(Lock)
        self._device_locks: Dict[str, Lock] = defaultdict(Lock)
        self._ip_locks: Dict[str, Lock] = defaultdict(Lock)

        self._results_lock = Lock()
        self._flagged: List[Dict[str, Any]] = []

    def detect(self, transactions: Iterable[Dict[str, Any]]) -> Dict[str, Any]:
        normalized = [self._normalize_transaction(tx) for tx in transactions]
        normalized.sort(key=lambda t: (t.timestamp, t.transaction_id))

        chunks = [
            normalized[i:i + self.config.chunk_size]
            for i in range(0, len(normalized), self.config.chunk_size)
        ]

        with ThreadPoolExecutor(max_workers=self.config.max_workers) as executor:
            futures = [executor.submit(self._process_chunk, chunk) for chunk in chunks]
            for future in as_completed(futures):
                future.result()

        flagged_sorted = sorted(
            self._flagged,
            key=lambda x: (x["timestamp_epoch"], x["transaction_id"])
        )

        return {
            "summary": {
                "total_transactions": len(normalized),
                "flagged_transactions": len(flagged_sorted),
                "max_workers": self.config.max_workers,
                "chunk_size": self.config.chunk_size,
                "rules": {
                    "large_amount_relative_to_history": {
                        "recent_amount_window": self.config.recent_amount_window,
                        "min_history": self.config.large_amount_min_history,
                        "zscore_threshold": self.config.large_amount_zscore_threshold,
                        "absolute_floor": self.config.large_amount_absolute_floor,
                    },
                    "rapid_successive_transactions": {
                        "window_seconds": self.config.rapid_txn_window_seconds,
                        "count_threshold": self.config.rapid_txn_count_threshold,
                    },
                    "geographic_inconsistency": {
                        "window_seconds": self.config.geo_window_seconds,
                    },
                    "shared_device_or_ip_across_accounts": {
                        "window_seconds": self.config.shared_origin_window_seconds,
                        "distinct_accounts_threshold": self.config.shared_origin_distinct_accounts_threshold,
                    },
                },
            },
            "flagged_transactions": flagged_sorted,
        }

    def _process_chunk(self, chunk: List[NormalizedTransaction]) -> None:
        for tx in chunk:
            result = self._evaluate_transaction(tx)
            if result is not None:
                with self._results_lock:
                    self._flagged.append(result)

    def _evaluate_transaction(self, tx: NormalizedTransaction) -> Optional[Dict[str, Any]]:
        account_key = tx.account_id
        device_key = tx.device_id or ""
        ip_key = tx.ip_address or ""

        lock_specs = [("account", account_key)]
        if device_key:
            lock_specs.append(("device", device_key))
        if ip_key:
            lock_specs.append(("ip", ip_key))
        lock_specs.sort()

        acquired: List[Lock] = []
        try:
            for kind, key in lock_specs:
                lock = self._get_lock(kind, key)
                lock.acquire()
                acquired.append(lock)

            account_state = self._account_states.setdefault(account_key, AccountState())
            device_state = self._device_states.setdefault(device_key, OriginState()) if device_key else None
            ip_state = self._ip_states.setdefault(ip_key, OriginState()) if ip_key else None

            triggered_rules: List[str] = []
            rule_details: Dict[str, Any] = {}
            risk_score = 0

            large_amount_flag, large_amount_detail = self._check_large_amount(tx, account_state)
            if large_amount_flag:
                triggered_rules.append("large_amount_relative_to_history")
                rule_details["large_amount_relative_to_history"] = large_amount_detail
                risk_score += self.config.score_large_amount

            rapid_flag, rapid_detail = self._check_rapid_successive(tx, account_state)
            if rapid_flag:
                triggered_rules.append("rapid_successive_transactions")
                rule_details["rapid_successive_transactions"] = rapid_detail
                risk_score += self.config.score_rapid_successive

            geo_flag, geo_detail = self._check_geo_inconsistency(tx, account_state)
            if geo_flag:
                triggered_rules.append("geographic_inconsistency")
                rule_details["geographic_inconsistency"] = geo_detail
                risk_score += self.config.score_geo_inconsistency

            if device_state is not None:
                shared_device_flag, shared_device_detail = self._check_shared_origin(
                    tx, device_state, origin_type="device"
                )
                if shared_device_flag:
                    triggered_rules.append("shared_device_across_accounts")
                    rule_details["shared_device_across_accounts"] = shared_device_detail
                    risk_score += self.config.score_shared_device

            if ip_state is not None:
                shared_ip_flag, shared_ip_detail = self._check_shared_origin(
                    tx, ip_state, origin_type="ip"
                )
                if shared_ip_flag:
                    triggered_rules.append("shared_ip_across_accounts")
                    rule_details["shared_ip_across_accounts"] = shared_ip_detail
                    risk_score += self.config.score_shared_ip

            self._update_account_state(tx, account_state)
            if device_state is not None:
                self._update_origin_state(tx, device_state)
            if ip_state is not None:
                self._update_origin_state(tx, ip_state)

            if not triggered_rules:
                return None

            return {
                "transaction_id": tx.transaction_id,
                "account_id": tx.account_id,
                "timestamp": datetime.fromtimestamp(tx.timestamp, tz=timezone.utc).isoformat(),
                "timestamp_epoch": tx.timestamp,
                "amount": tx.amount,
                "merchant_category": tx.merchant_category,
                "country": tx.country,
                "device_id": tx.device_id,
                "ip_address": tx.ip_address,
                "triggered_rules": triggered_rules,
                "rule_details": rule_details,
                "fraud_risk_score": min(risk_score, self.config.max_risk_score),
            }
        finally:
            for lock in reversed(acquired):
                lock.release()

    def _check_large_amount(
        self, tx: NormalizedTransaction, state: AccountState
    ) -> Tuple[bool, Dict[str, Any]]:
        history = list(state.amount_history)
        if len(history) < self.config.large_amount_min_history:
            return False, {}

        mean = sum(history) / len(history)
        variance = sum((x - mean) ** 2 for x in history) / len(history)
        std_dev = max(math.sqrt(variance), self.config.large_amount_std_floor)
        zscore = (tx.amount - mean) / std_dev if std_dev > 0 else 0.0

        flagged = (
            tx.amount >= self.config.large_amount_absolute_floor
            and zscore >= self.config.large_amount_zscore_threshold
        )

        return flagged, {
            "current_amount": tx.amount,
            "historical_mean": round(mean, 2),
            "historical_std_dev": round(std_dev, 2),
            "zscore": round(zscore, 2),
            "history_count": len(history),
        }

    def _check_rapid_successive(
        self, tx: NormalizedTransaction, state: AccountState
    ) -> Tuple[bool, Dict[str, Any]]:
        window_start = tx.timestamp - self.config.rapid_txn_window_seconds
        recent = [ts for ts in state.recent_timestamps if ts >= window_start]
        count_in_window = len(recent) + 1
        flagged = count_in_window >= self.config.rapid_txn_count_threshold

        return flagged, {
            "window_seconds": self.config.rapid_txn_window_seconds,
            "transactions_in_window_including_current": count_in_window,
        }

    def _check_geo_inconsistency(
        self, tx: NormalizedTransaction, state: AccountState
    ) -> Tuple[bool, Dict[str, Any]]:
        if not tx.country:
            return False, {}

        window_start = tx.timestamp - self.config.geo_window_seconds
        recent_countries = {
            country
            for ts, country in state.recent_countries
            if ts >= window_start and country
        }

        inconsistent = len(recent_countries - {tx.country}) > 0
        return inconsistent, {
            "window_seconds": self.config.geo_window_seconds,
            "current_country": tx.country,
            "recent_other_countries": sorted(recent_countries - {tx.country}),
        }

    def _check_shared_origin(
        self, tx: NormalizedTransaction, state: OriginState, origin_type: str
    ) -> Tuple[bool, Dict[str, Any]]:
        window_start = tx.timestamp - self.config.shared_origin_window_seconds
        distinct_accounts = {
            account_id
            for ts, account_id in state.recent_accounts
            if ts >= window_start
        }
        distinct_accounts.add(tx.account_id)

        flagged = len(distinct_accounts) >= self.config.shared_origin_distinct_accounts_threshold
        return flagged, {
            "origin_type": origin_type,
            "window_seconds": self.config.shared_origin_window_seconds,
            "distinct_accounts_in_window_including_current": len(distinct_accounts),
            "accounts_sample": sorted(distinct_accounts)[:10],
        }

    def _update_account_state(self, tx: NormalizedTransaction, state: AccountState) -> None:
        state.amount_history.append(tx.amount)
        while len(state.amount_history) > self.config.recent_amount_window:
            state.amount_history.popleft()

        state.recent_timestamps.append(tx.timestamp)
        rapid_cutoff = tx.timestamp - self.config.rapid_txn_window_seconds
        while state.recent_timestamps and state.recent_timestamps[0] < rapid_cutoff:
            state.recent_timestamps.popleft()

        state.recent_countries.append((tx.timestamp, tx.country))
        geo_cutoff = tx.timestamp - self.config.geo_window_seconds
        while state.recent_countries and state.recent_countries[0][0] < geo_cutoff:
            state.recent_countries.popleft()

    def _update_origin_state(self, tx: NormalizedTransaction, state: OriginState) -> None:
        state.recent_accounts.append((tx.timestamp, tx.account_id))
        cutoff = tx.timestamp - self.config.shared_origin_window_seconds
        while state.recent_accounts and state.recent_accounts[0][0] < cutoff:
            state.recent_accounts.popleft()

    def _get_lock(self, kind: str, key: str) -> Lock:
        if kind == "account":
            return self._account_locks[key]
        if kind == "device":
            return self._device_locks[key]
        if kind == "ip":
            return self._ip_locks[key]
        raise ValueError(f"Unknown lock kind: {kind}")

    @staticmethod
    def _normalize_transaction(record: Dict[str, Any]) -> NormalizedTransaction:
        required = ["transaction_id", "account_id", "timestamp", "amount"]
        missing = [k for k in required if k not in record]
        if missing:
            raise ValueError(f"Missing required transaction fields: {missing}")

        return NormalizedTransaction(
            transaction_id=str(record["transaction_id"]),
            account_id=str(record["account_id"]),
            timestamp=_parse_timestamp(record["timestamp"]),
            amount=float(record["amount"]),
            merchant_category=_optional_str(record.get("merchant_category")),
            country=_optional_str(record.get("country")),
            device_id=_optional_str(record.get("device_id")),
            ip_address=_optional_str(record.get("ip_address")),
            raw=dict(record),
        )


def detect_potentially_fraudulent_transactions(
    transactions: Iterable[Dict[str, Any]],
    config: Optional[FraudConfig] = None,
) -> Dict[str, Any]:
    detector = FraudDetector(config=config)
    return detector.detect(transactions)


def _parse_timestamp(value: Any) -> float:
    if isinstance(value, datetime):
        dt = value if value.tzinfo else value.replace(tzinfo=timezone.utc)
        return dt.timestamp()
    if isinstance(value, (int, float)):
        return float(value)
    if isinstance(value, str):
        text = value.strip()
        if text.endswith("Z"):
            text = text[:-1] + "+00:00"
        try:
            return datetime.fromisoformat(text).timestamp()
        except ValueError:
            pass
        for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%d"):
            try:
                return datetime.strptime(text, fmt).replace(tzinfo=timezone.utc).timestamp()
            except ValueError:
                continue
    raise ValueError(f"Unsupported timestamp format: {value!r}")


def _optional_str(value: Any) -> Optional[str]:
    if value is None:
        return None
    text = str(value).strip()
    return text if text else None


