import math
import threading
import queue
import time
from dataclasses import dataclass, field
from collections import defaultdict, deque
from concurrent.futures import ThreadPoolExecutor, as_completed
from datetime import datetime, timezone
from typing import Any, Callable, Deque, Dict, List, Optional, Tuple


@dataclass(frozen=True)
class Transaction:
    transaction_id: str
    account_id: str
    timestamp: datetime
    amount: float
    merchant_id: str
    country: str
    device_id: str
    payment_method: str
    status: str = "approved"

    @staticmethod
    def from_dict(data: Dict[str, Any]) -> "Transaction":
        ts = data.get("timestamp")
        if isinstance(ts, str):
            try:
                ts = datetime.fromisoformat(ts.replace("Z", "+00:00"))
            except ValueError:
                raise ValueError(f"Invalid timestamp format: {data.get('timestamp')}")
        elif isinstance(ts, (int, float)):
            ts = datetime.fromtimestamp(ts, tz=timezone.utc)
        elif isinstance(ts, datetime):
            if ts.tzinfo is None:
                ts = ts.replace(tzinfo=timezone.utc)
        else:
            raise ValueError("timestamp must be datetime, ISO string, or unix epoch")

        return Transaction(
            transaction_id=str(data["transaction_id"]),
            account_id=str(data["account_id"]),
            timestamp=ts,
            amount=float(data["amount"]),
            merchant_id=str(data["merchant_id"]),
            country=str(data["country"]),
            device_id=str(data["device_id"]),
            payment_method=str(data["payment_method"]),
            status=str(data.get("status", "approved")).lower(),
        )


@dataclass
class FraudAlert:
    transaction_id: str
    account_id: str
    risk_score: float
    reasons: List[str]
    timestamp: datetime
    transaction: Dict[str, Any] = field(default_factory=dict)


@dataclass
class AccountProfile:
    amounts_count: int = 0
    amounts_sum: float = 0.0
    amounts_sum_sq: float = 0.0
    known_countries: set = field(default_factory=set)
    recent_transactions: Deque[Transaction] = field(default_factory=deque)
    recent_declines: Deque[datetime] = field(default_factory=deque)
    recent_devices: Deque[Tuple[datetime, str]] = field(default_factory=deque)
    risk_score: float = 0.0

    def mean_amount(self) -> float:
        if self.amounts_count == 0:
            return 0.0
        return self.amounts_sum / self.amounts_count

    def std_amount(self) -> float:
        if self.amounts_count < 2:
            return 0.0
        mean = self.mean_amount()
        variance = max((self.amounts_sum_sq / self.amounts_count) - (mean * mean), 0.0)
        return math.sqrt(variance)


class FraudRule:
    name: str = "base_rule"

    def evaluate(
        self,
        transaction: Transaction,
        profile_snapshot: Dict[str, Any],
        config: Dict[str, Any],
    ) -> Optional[Tuple[str, float]]:
        raise NotImplementedError


class RapidSuccessiveTransactionsRule(FraudRule):
    name = "rapid_successive_transactions"

    def evaluate(
        self,
        transaction: Transaction,
        profile_snapshot: Dict[str, Any],
        config: Dict[str, Any],
    ) -> Optional[Tuple[str, float]]:
        window_seconds = config["rapid_successive"]["window_seconds"]
        max_count = config["rapid_successive"]["max_count"]
        weight = config["rapid_successive"]["risk_weight"]

        recent = profile_snapshot["recent_transactions"]
        cutoff = transaction.timestamp.timestamp() - window_seconds
        count = sum(1 for tx in recent if tx.timestamp.timestamp() >= cutoff)
        if count >= max_count:
            return (
                f"Rapid successive transactions detected: {count + 1} transactions within {window_seconds}s",
                weight,
            )
        return None


class AbnormalAmountRule(FraudRule):
    name = "abnormal_amount"

    def evaluate(
        self,
        transaction: Transaction,
        profile_snapshot: Dict[str, Any],
        config: Dict[str, Any],
    ) -> Optional[Tuple[str, float]]:
        min_history = config["abnormal_amount"]["min_history"]
        stddev_multiplier = config["abnormal_amount"]["stddev_multiplier"]
        min_absolute_amount = config["abnormal_amount"]["min_absolute_amount"]
        weight = config["abnormal_amount"]["risk_weight"]

        count = profile_snapshot["amounts_count"]
        mean = profile_snapshot["mean_amount"]
        std = profile_snapshot["std_amount"]

        if count < min_history:
            return None

        threshold = max(mean + stddev_multiplier * std, min_absolute_amount)
        if transaction.amount > threshold:
            return (
                f"Abnormal amount detected: amount={transaction.amount:.2f}, historical_mean={mean:.2f}, threshold={threshold:.2f}",
                weight,
            )
        return None


class GeographicInconsistencyRule(FraudRule):
    name = "geographic_inconsistency"

    def evaluate(
        self,
        transaction: Transaction,
        profile_snapshot: Dict[str, Any],
        config: Dict[str, Any],
    ) -> Optional[Tuple[str, float]]:
        weight = config["geo_inconsistency"]["risk_weight"]
        known_countries = profile_snapshot["known_countries"]
        recent = profile_snapshot["recent_transactions"]
        impossible_window_seconds = config["geo_inconsistency"]["impossible_window_seconds"]

        if known_countries and transaction.country not in known_countries:
            for tx in reversed(recent):
                if tx.country != transaction.country:
                    delta = abs(transaction.timestamp.timestamp() - tx.timestamp.timestamp())
                    if delta <= impossible_window_seconds:
                        return (
                            f"Geographically inconsistent purchase: {tx.country} -> {transaction.country} within {int(delta)}s",
                            weight,
                        )
                    break
        return None


class DeclinesThenApprovalRule(FraudRule):
    name = "declines_then_approval"

    def evaluate(
        self,
        transaction: Transaction,
        profile_snapshot: Dict[str, Any],
        config: Dict[str, Any],
    ) -> Optional[Tuple[str, float]]:
        if transaction.status != "approved":
            return None

        window_seconds = config["declines_then_approval"]["window_seconds"]
        min_declines = config["declines_then_approval"]["min_declines"]
        weight = config["declines_then_approval"]["risk_weight"]

        declines = profile_snapshot["recent_declines"]
        cutoff = transaction.timestamp.timestamp() - window_seconds
        count = sum(1 for ts in declines if ts.timestamp() >= cutoff)
        if count >= min_declines:
            return (
                f"Repeated declines followed by approval: {count} declines within {window_seconds}s before approval",
                weight,
            )
        return None


class MultipleDevicesRule(FraudRule):
    name = "multiple_devices"

    def evaluate(
        self,
        transaction: Transaction,
        profile_snapshot: Dict[str, Any],
        config: Dict[str, Any],
    ) -> Optional[Tuple[str, float]]:
        window_seconds = config["multiple_devices"]["window_seconds"]
        max_devices = config["multiple_devices"]["max_devices"]
        weight = config["multiple_devices"]["risk_weight"]

        devices = profile_snapshot["recent_devices"]
        cutoff = transaction.timestamp.timestamp() - window_seconds
        unique_devices = {device_id for ts, device_id in devices if ts.timestamp() >= cutoff}
        unique_devices.add(transaction.device_id)

        if len(unique_devices) > max_devices:
            return (
                f"Excessive device diversity: {len(unique_devices)} devices used within {window_seconds}s",
                weight,
            )
        return None


class RealTimeFraudMonitor:
    DEFAULT_CONFIG: Dict[str, Any] = {
        "queue_maxsize": 10000,
        "worker_count": 4,
        "rule_worker_count": 5,
        "history_retention_seconds": 3600,
        "alert_risk_threshold": 50.0,
        "rapid_successive": {
            "window_seconds": 60,
            "max_count": 5,
            "risk_weight": 20.0,
        },
        "abnormal_amount": {
            "min_history": 5,
            "stddev_multiplier": 3.0,
            "min_absolute_amount": 1000.0,
            "risk_weight": 25.0,
        },
        "geo_inconsistency": {
            "impossible_window_seconds": 7200,
            "risk_weight": 30.0,
        },
        "declines_then_approval": {
            "window_seconds": 900,
            "min_declines": 3,
            "risk_weight": 20.0,
        },
        "multiple_devices": {
            "window_seconds": 600,
            "max_devices": 3,
            "risk_weight": 25.0,
        },
    }

    def __init__(self, config: Optional[Dict[str, Any]] = None):
        self.config = self._deep_merge(dict(self.DEFAULT_CONFIG), config or {})
        self._queue: "queue.Queue[Optional[Transaction]]" = queue.Queue(maxsize=self.config["queue_maxsize"])
        self._profiles: Dict[str, AccountProfile] = defaultdict(AccountProfile)
        self._alerts: List[FraudAlert] = []
        self._processed_count = 0

        self._profiles_lock = threading.RLock()
        self._alerts_lock = threading.Lock()
        self._count_lock = threading.Lock()
        self._stop_event = threading.Event()
        self._workers: List[threading.Thread] = []

        self._rules: List[FraudRule] = []
        self._rule_executor = ThreadPoolExecutor(max_workers=self.config["rule_worker_count"])

        self._register_default_rules()

    def _register_default_rules(self) -> None:
        self.add_rule(RapidSuccessiveTransactionsRule())
        self.add_rule(AbnormalAmountRule())
        self.add_rule(GeographicInconsistencyRule())
        self.add_rule(DeclinesThenApprovalRule())
        self.add_rule(MultipleDevicesRule())

    def add_rule(self, rule: FraudRule) -> None:
        if not isinstance(rule, FraudRule):
            raise TypeError("rule must be an instance of FraudRule")
        self._rules.append(rule)

    def start(self) -> None:
        if self._workers:
            return
        for idx in range(self.config["worker_count"]):
            t = threading.Thread(target=self._worker_loop, name=f"fraud-worker-{idx}", daemon=True)
            t.start()
            self._workers.append(t)

    def stop(self, wait: bool = True) -> None:
        self._stop_event.set()
        for _ in self._workers:
            self._queue.put(None)
        if wait:
            for t in self._workers:
                t.join()
            self._rule_executor.shutdown(wait=True)

    def add_transaction(self, transaction: Any, block: bool = True, timeout: Optional[float] = None) -> None:
        tx = transaction if isinstance(transaction, Transaction) else Transaction.from_dict(transaction)
        self._queue.put(tx, block=block, timeout=timeout)

    def process_transaction(self, transaction: Any) -> Optional[FraudAlert]:
        tx = transaction if isinstance(transaction, Transaction) else Transaction.from_dict(transaction)
        return self._process_single_transaction(tx)

    def get_flagged_transactions(self) -> List[FraudAlert]:
        with self._alerts_lock:
            return list(self._alerts)

    def get_account_risk_score(self, account_id: str) -> float:
        with self._profiles_lock:
            return self._profiles[account_id].risk_score

    def get_processed_count(self) -> int:
        with self._count_lock:
            return self._processed_count

    def wait_until_idle(self) -> None:
        self._queue.join()

    def _worker_loop(self) -> None:
        while not self._stop_event.is_set():
            tx = self._queue.get()
            try:
                if tx is None:
                    return
                self._process_single_transaction(tx)
            finally:
                self._queue.task_done()

    def _process_single_transaction(self, transaction: Transaction) -> Optional[FraudAlert]:
        snapshot = self._snapshot_profile(transaction.account_id)
        reasons, risk_delta = self._evaluate_rules_concurrently(transaction, snapshot)
        alert = self._update_state_and_maybe_alert(transaction, reasons, risk_delta)
        with self._count_lock:
            self._processed_count += 1
        return alert

    def _snapshot_profile(self, account_id: str) -> Dict[str, Any]:
        with self._profiles_lock:
            profile = self._profiles[account_id]
            return {
                "amounts_count": profile.amounts_count,
                "mean_amount": profile.mean_amount(),
                "std_amount": profile.std_amount(),
                "known_countries": set(profile.known_countries),
                "recent_transactions": list(profile.recent_transactions),
                "recent_declines": list(profile.recent_declines),
                "recent_devices": list(profile.recent_devices),
                "risk_score": profile.risk_score,
            }

    def _evaluate_rules_concurrently(
        self,
        transaction: Transaction,
        profile_snapshot: Dict[str, Any],
    ) -> Tuple[List[str], float]:
        futures = [
            self._rule_executor.submit(rule.evaluate, transaction, profile_snapshot, self.config)
            for rule in self._rules
        ]
        reasons: List[str] = []
        risk_delta = 0.0

        for future in as_completed(futures):
            result = future.result()
            if result:
                reason, weight = result
                reasons.append(reason)
                risk_delta += float(weight)

        return reasons, risk_delta

    def _update_state_and_maybe_alert(
        self,
        transaction: Transaction,
        reasons: List[str],
        risk_delta: float,
    ) -> Optional[FraudAlert]:
        with self._profiles_lock:
            profile = self._profiles[transaction.account_id]
            self._prune_profile(profile, transaction.timestamp)

            profile.recent_transactions.append(transaction)
            profile.recent_devices.append((transaction.timestamp, transaction.device_id))
            profile.known_countries.add(transaction.country)

            if transaction.status == "declined":
                profile.recent_declines.append(transaction.timestamp)

            if transaction.status == "approved":
                profile.amounts_count += 1
                profile.amounts_sum += transaction.amount
                profile.amounts_sum_sq += transaction.amount * transaction.amount

            profile.risk_score += risk_delta
            current_risk = profile.risk_score

        if reasons and current_risk >= self.config["alert_risk_threshold"]:
            alert = FraudAlert(
                transaction_id=transaction.transaction_id,
                account_id=transaction.account_id,
                risk_score=current_risk,
                reasons=sorted(reasons),
                timestamp=transaction.timestamp,
                transaction={
                    "transaction_id": transaction.transaction_id,
                    "account_id": transaction.account_id,
                    "timestamp": transaction.timestamp.isoformat(),
                    "amount": transaction.amount,
                    "merchant_id": transaction.merchant_id,
                    "country": transaction.country,
                    "device_id": transaction.device_id,
                    "payment_method": transaction.payment_method,
                    "status": transaction.status,
                },
            )
            with self._alerts_lock:
                self._alerts.append(alert)
            return alert
        return None

    def _prune_profile(self, profile: AccountProfile, now: datetime) -> None:
        retention = self.config["history_retention_seconds"]
        cutoff = now.timestamp() - retention

        while profile.recent_transactions and profile.recent_transactions[0].timestamp.timestamp() < cutoff:
            profile.recent_transactions.popleft()

        while profile.recent_declines and profile.recent_declines[0].timestamp() < cutoff:
            profile.recent_declines.popleft()

        while profile.recent_devices and profile.recent_devices[0][0].timestamp() < cutoff:
            profile.recent_devices.popleft()

    @staticmethod
    def _deep_merge(base: Dict[str, Any], override: Dict[str, Any]) -> Dict[str, Any]:
        for k, v in override.items():
            if k in base and isinstance(base[k], dict) and isinstance(v, dict):
                base[k] = RealTimeFraudMonitor._deep_merge(base[k], v)
            else:
                base[k] = v
        return base


