from __future__ import annotations

import json
from contextlib import AbstractContextManager
from dataclasses import dataclass, field
from datetime import datetime, timedelta, timezone
from pathlib import Path
from typing import Any, Dict, Iterable, List, Optional, TextIO, Tuple


ALLOWED_EVENT_TYPES = {"join", "message", "file_upload", "leave"}
REQUIRED_FIELDS = {
    "session_id",
    "patient_id",
    "provider_id",
    "event_type",
    "timestamp",
}


class SchemaError(ValueError):
    """Raised when an unrecoverable schema issue is encountered."""


@dataclass(frozen=True)
class EventRecord:
    session_id: str
    patient_id: str
    provider_id: str
    event_type: str
    timestamp: datetime


@dataclass
class InvalidRecord:
    line_number: int
    raw_record: str
    reason: str


@dataclass
class SessionAccumulator:
    session_id: str
    events: List[EventRecord] = field(default_factory=list)
    patient_present: bool = False
    provider_present: bool = False

    def add_event(self, event: EventRecord) -> None:
        self.events.append(event)
        if event.patient_id.strip():
            self.patient_present = True
        if event.provider_id.strip():
            self.provider_present = True


class StructuredErrorLogger(AbstractContextManager["StructuredErrorLogger"]):
    """
    Custom context manager for collecting structured processing errors and
    ensuring they are attached to the final report payload.
    """

    def __init__(self) -> None:
        self.errors: List[Dict[str, Any]] = []

    def __enter__(self) -> "StructuredErrorLogger":
        return self

    def log(
        self,
        *,
        stage: str,
        message: str,
        line_number: Optional[int] = None,
        session_id: Optional[str] = None,
    ) -> None:
        entry: Dict[str, Any] = {
            "stage": stage,
            "message": message,
        }
        if line_number is not None:
            entry["line_number"] = line_number
        if session_id is not None:
            entry["session_id"] = session_id
        self.errors.append(entry)

    def __exit__(self, exc_type, exc, tb) -> bool:
        return False


def _parse_iso8601_timestamp(value: str) -> datetime:
    if not isinstance(value, str) or not value.strip():
        raise ValueError("timestamp must be a non-empty ISO 8601 string")
    normalized = value.strip()
    if normalized.endswith("Z"):
        normalized = normalized[:-1] + "+00:00"
    dt = datetime.fromisoformat(normalized)
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    return dt


def _validate_and_build_event(record: Dict[str, Any]) -> EventRecord:
    if not isinstance(record, dict):
        raise ValueError("record must be a JSON object")

    missing = REQUIRED_FIELDS - record.keys()
    if missing:
        raise ValueError(f"missing required fields: {sorted(missing)}")

    extra_required_type_checks = {
        "session_id": record["session_id"],
        "patient_id": record["patient_id"],
        "provider_id": record["provider_id"],
        "event_type": record["event_type"],
        "timestamp": record["timestamp"],
    }

    for field_name, field_value in extra_required_type_checks.items():
        if field_name == "timestamp":
            continue
        if not isinstance(field_value, str):
            raise ValueError(f"{field_name} must be a string")

    session_id = record["session_id"].strip()
    patient_id = record["patient_id"].strip()
    provider_id = record["provider_id"].strip()
    event_type = record["event_type"].strip()

    if not session_id:
        raise ValueError("session_id must be a non-empty string")
    if event_type not in ALLOWED_EVENT_TYPES:
        raise ValueError(
            f"event_type must be one of {sorted(ALLOWED_EVENT_TYPES)}"
        )

    timestamp = _parse_iso8601_timestamp(record["timestamp"])

    return EventRecord(
        session_id=session_id,
        patient_id=patient_id,
        provider_id=provider_id,
        event_type=event_type,
        timestamp=timestamp,
    )


def _iter_validated_events(
    input_path: Path,
    error_logger: StructuredErrorLogger,
) -> Tuple[Dict[str, SessionAccumulator], List[InvalidRecord]]:
    sessions: Dict[str, SessionAccumulator] = {}
    invalid_records: List[InvalidRecord] = []

    with input_path.open("r", encoding="utf-8") as infile:
        for line_number, line in enumerate(infile, start=1):
            raw_line = line.rstrip("\n")
            if not raw_line.strip():
                invalid = InvalidRecord(
                    line_number=line_number,
                    raw_record=raw_line,
                    reason="empty line",
                )
                invalid_records.append(invalid)
                error_logger.log(
                    stage="read_input",
                    message=invalid.reason,
                    line_number=line_number,
                )
                continue

            try:
                parsed = json.loads(raw_line)
            except json.JSONDecodeError as exc:
                invalid = InvalidRecord(
                    line_number=line_number,
                    raw_record=raw_line,
                    reason=f"invalid JSON: {exc.msg}",
                )
                invalid_records.append(invalid)
                error_logger.log(
                    stage="parse_json",
                    message=invalid.reason,
                    line_number=line_number,
                )
                continue

            try:
                event = _validate_and_build_event(parsed)
            except ValueError as exc:
                invalid = InvalidRecord(
                    line_number=line_number,
                    raw_record=raw_line,
                    reason=str(exc),
                )
                invalid_records.append(invalid)
                error_logger.log(
                    stage="validate_record",
                    message=invalid.reason,
                    line_number=line_number,
                    session_id=parsed.get("session_id")
                    if isinstance(parsed, dict)
                    else None,
                )
                continue

            accumulator = sessions.setdefault(
                event.session_id,
                SessionAccumulator(session_id=event.session_id),
            )
            accumulator.add_event(event)

    return sessions, invalid_records


def _compute_session_summary(
    session: SessionAccumulator,
    inactivity_timeout: timedelta,
    error_logger: StructuredErrorLogger,
) -> Dict[str, Any]:
    if not session.events:
        raise SchemaError(f"session {session.session_id!r} contains no valid events")

    ordered_events = sorted(session.events, key=lambda e: e.timestamp)
    start_time = ordered_events[0].timestamp
    end_time = ordered_events[-1].timestamp
    total_duration = max((end_time - start_time).total_seconds(), 0.0)

    inactivity_violation = False
    inactivity_gaps: List[Dict[str, Any]] = []

    for previous, current in zip(ordered_events, ordered_events[1:]):
        gap = current.timestamp - previous.timestamp
        if gap > inactivity_timeout:
            inactivity_violation = True
            inactivity_gaps.append(
                {
                    "from_event_type": previous.event_type,
                    "to_event_type": current.event_type,
                    "gap_seconds": gap.total_seconds(),
                    "from_timestamp": previous.timestamp.isoformat(),
                    "to_timestamp": current.timestamp.isoformat(),
                }
            )

    required_participants_present = (
        session.patient_present and session.provider_present
    )

    if not required_participants_present:
        error_logger.log(
            stage="aggregate_session",
            message="missing required participant",
            session_id=session.session_id,
        )

    return {
        "session_id": session.session_id,
        "start_time": start_time.isoformat(),
        "end_time": end_time.isoformat(),
        "total_duration_seconds": total_duration,
        "inactivity_timeout_exceeded": inactivity_violation,
        "inactivity_gaps": inactivity_gaps,
        "required_participants_present": required_participants_present,
        "event_count": len(ordered_events),
        "participants": {
            "patient_present": session.patient_present,
            "provider_present": session.provider_present,
        },
    }


def _build_aggregate_metrics(
    session_summaries: Iterable[Dict[str, Any]],
) -> Dict[str, Any]:
    summaries = list(session_summaries)
    total_sessions = len(summaries)
    total_duration = sum(
        float(summary["total_duration_seconds"]) for summary in summaries
    )
    inactivity_violations = sum(
        1 for summary in summaries if summary["inactivity_timeout_exceeded"]
    )
    missing_required_participant = sum(
        1 for summary in summaries if not summary["required_participants_present"]
    )

    average_duration = total_duration / total_sessions if total_sessions else 0.0

    return {
        "total_sessions_processed": total_sessions,
        "average_session_duration_seconds": average_duration,
        "sessions_with_inactivity_violations": inactivity_violations,
        "sessions_missing_required_participant": missing_required_participant,
    }


def _serialize_report(
    output_path: Path,
    report: Dict[str, Any],
) -> None:
    with output_path.open("w", encoding="utf-8") as outfile:
        json.dump(report, outfile, indent=2, ensure_ascii=False)
        outfile.write("\n")


def generate_telemedicine_compliance_report(
    input_file_path: str,
    output_report_path: str,
    inactivity_timeout_minutes: int,
) -> Dict[str, Any]:
    """
    Process newline-delimited JSON telemedicine session events and generate
    a compliance report.

    Args:
        input_file_path: Path to the NDJSON input file containing session events.
        output_report_path: Path where the JSON compliance report will be written.
        inactivity_timeout_minutes: Inactivity timeout threshold in minutes.

    Returns:
        The generated report as a dictionary.

    Raises:
        FileNotFoundError: If the input file does not exist.
        IsADirectoryError: If an input or output path points to a directory.
        PermissionError: If file access is denied.
        ValueError: If inactivity_timeout_minutes is invalid.
        SchemaError: If unrecoverable session-level schema issues are encountered.
    """
    if not isinstance(inactivity_timeout_minutes, int) or inactivity_timeout_minutes <= 0:
        raise ValueError("inactivity_timeout_minutes must be a positive integer")

    input_path = Path(input_file_path)
    output_path = Path(output_report_path)

    if not input_path.exists():
        raise FileNotFoundError(f"input file not found: {input_path}")
    if input_path.is_dir():
        raise IsADirectoryError(f"input path is a directory: {input_path}")
    if output_path.exists() and output_path.is_dir():
        raise IsADirectoryError(f"output path is a directory: {output_path}")

    inactivity_timeout = timedelta(minutes=inactivity_timeout_minutes)

    with StructuredErrorLogger() as error_logger:
        sessions, invalid_records = _iter_validated_events(input_path, error_logger)

        session_summaries: List[Dict[str, Any]] = []
        for session_id, session in sessions.items():
            try:
                summary = _compute_session_summary(
                    session,
                    inactivity_timeout,
                    error_logger,
                )
                session_summaries.append(summary)
            except SchemaError:
                raise
            except Exception as exc:
                error_logger.log(
                    stage="aggregate_session",
                    message=f"unexpected aggregation error: {exc}",
                    session_id=session_id,
                )
                raise SchemaError(
                    f"failed to aggregate session {session_id!r}: {exc}"
                ) from exc

        session_summaries.sort(key=lambda item: (item["start_time"], item["session_id"]))

        report = {
            "valid_session_summaries": session_summaries,
            "invalid_records": [
                {
                    "line_number": item.line_number,
                    "raw_record": item.raw_record,
                    "reason": item.reason,
                }
                for item in invalid_records
            ],
            "aggregate_metrics": _build_aggregate_metrics(session_summaries),
            "processing_errors": error_logger.errors,
            "configuration": {
                "inactivity_timeout_minutes": inactivity_timeout_minutes,
            },
        }

        _serialize_report(output_path, report)
        return report

