from collections import Counter, defaultdict
from datetime import datetime, date
from typing import Any, Dict, Iterable, List, Set


class FraudTransactionAnalyzer:
    REQUIRED_KEYS = {"transaction_id", "account_id", "amount", "timestamp", "location"}

    def __init__(self, transactions: List[Dict[str, Any]]) -> None:
        self.transactions = self._validate_transactions(transactions)

    def _validate_transactions(self, transactions: Any) -> List[Dict[str, Any]]:
        if not isinstance(transactions, list):
            raise TypeError("transactions must be a list of dictionaries")

        validated: List[Dict[str, Any]] = []
        seen_transaction_ids: Set[Any] = set()

        for index, tx in enumerate(transactions):
            if not isinstance(tx, dict):
                raise TypeError(f"Transaction at index {index} must be a dictionary")

            missing = self.REQUIRED_KEYS - tx.keys()
            if missing:
                raise ValueError(f"Transaction at index {index} is missing keys: {sorted(missing)}")

            transaction_id = tx["transaction_id"]
            account_id = tx["account_id"]
            amount = tx["amount"]
            timestamp = tx["timestamp"]
            location = tx["location"]

            if transaction_id in seen_transaction_ids:
                raise ValueError(f"Duplicate transaction_id found: {transaction_id}")
            seen_transaction_ids.add(transaction_id)

            if not isinstance(account_id, (str, int)):
                raise TypeError(f"account_id for transaction {transaction_id} must be a string or integer")

            if not isinstance(location, str) or not location.strip():
                raise ValueError(f"location for transaction {transaction_id} must be a non-empty string")

            if not isinstance(amount, (int, float)):
                raise TypeError(f"amount for transaction {transaction_id} must be numeric")

            parsed_timestamp = self._parse_timestamp(timestamp, transaction_id)

            validated.append(
                {
                    "transaction_id": transaction_id,
                    "account_id": account_id,
                    "amount": float(amount),
                    "timestamp": parsed_timestamp,
                    "location": location.strip(),
                }
            )

        return validated

    @staticmethod
    def _parse_timestamp(timestamp: Any, transaction_id: Any) -> datetime:
        if isinstance(timestamp, datetime):
            return timestamp

        if not isinstance(timestamp, str) or not timestamp.strip():
            raise ValueError(f"timestamp for transaction {transaction_id} must be a non-empty ISO datetime string")

        try:
            return datetime.fromisoformat(timestamp)
        except ValueError as exc:
            raise ValueError(
                f"timestamp for transaction {transaction_id} must be a valid ISO datetime string"
            ) from exc

    def get_high_risk_transactions(self, threshold: float) -> List[Dict[str, Any]]:
        if not isinstance(threshold, (int, float)):
            raise TypeError("threshold must be numeric")
        return [tx for tx in self.transactions if tx["amount"] > float(threshold)]

    def get_accounts_with_excessive_daily_transactions(self, max_transactions_per_day: int) -> List[Any]:
        if not isinstance(max_transactions_per_day, int) or max_transactions_per_day < 0:
            raise ValueError("max_transactions_per_day must be a non-negative integer")

        account_day_pairs = [(tx["account_id"], tx["timestamp"].date()) for tx in self.transactions]
        counts = Counter(account_day_pairs)

        return list(
            {
                account_id
                for (account_id, _day), count in counts.items()
                if count > max_transactions_per_day
            }
        )

    def get_unapproved_location_transactions(
        self, approved_locations_by_account: Dict[Any, Iterable[str]]
    ) -> List[Dict[str, Any]]:
        if not isinstance(approved_locations_by_account, dict):
            raise TypeError("approved_locations_by_account must be a dictionary")

        normalized_approved: Dict[Any, Set[str]] = {}
        for account_id, locations in approved_locations_by_account.items():
            if not isinstance(locations, Iterable) or isinstance(locations, (str, bytes)):
                raise TypeError(f"Approved locations for account {account_id} must be a non-string iterable")
            normalized_approved[account_id] = {
                location.strip()
                for location in locations
                if isinstance(location, str) and location.strip()
            }

        return [
            tx
            for tx in self.transactions
            if tx["location"] not in normalized_approved.get(tx["account_id"], set())
        ]

    def generate_suspicious_activity_report(
        self,
        high_risk_threshold: float,
        max_transactions_per_day: int,
        approved_locations_by_account: Dict[Any, Iterable[str]],
    ) -> Dict[str, Any]:
        high_risk = self.get_high_risk_transactions(high_risk_threshold)
        excessive_accounts = set(
            self.get_accounts_with_excessive_daily_transactions(max_transactions_per_day)
        )
        unapproved_location_transactions = self.get_unapproved_location_transactions(
            approved_locations_by_account
        )

        excessive_account_transactions = [
            tx for tx in self.transactions if tx["account_id"] in excessive_accounts
        ]

        suspicious_transactions = {
            tx["transaction_id"]: tx
            for tx in (
                high_risk + excessive_account_transactions + unapproved_location_transactions
            )
        }

        return {
            "total_suspicious_transactions": len(suspicious_transactions),
            "affected_account_ids": sorted(
                {tx["account_id"] for tx in suspicious_transactions.values()},
                key=str,
            ),
            "flagged_transaction_ids": sorted(suspicious_transactions.keys(), key=str),
        }


