@dataclass
class Position:
    symbol: str
    quantity: float = 0.0
    avg_price: float = 0.0
    market_price: Optional[float] = None
    unrealized_pnl: float = 0.0

    def recompute_unrealized_pnl(self) -> None:
        if self.market_price is None or self.quantity == 0:
            self.unrealized_pnl = 0.0
            return
        self.unrealized_pnl = (self.market_price - self.avg_price) * self.quantity

    @property
    def notional_exposure(self) -> float:
        reference_price = self.market_price if self.market_price is not None else self.avg_price
        return abs(self.quantity) * reference_price


