    created_at: datetime = field(default_factory=datetime.utcnow)


@dataclass
class AccountState:
    account_id: str
    positions: Dict[str, Position] = field(default_factory=dict)
    pending_orders: Dict[str, Order] = field(default_factory=dict)
    daily_realized_pnl: float = 0.0


class RiskViolationError(Exception):
    def __init__(self, reasons: List[str]):
        self.reasons = reasons
        super().__init__("; ".join(reasons))


class TradingRiskControlService:
    def __init__(self, risk_limits: RiskLimits, valid_account_ids: Optional[List[str]] = None):
        self.risk_limits = risk_limits
        self.valid_account_ids = set(valid_account_ids or ["ACC-001", "ACC-002", "ACC-003"])
        self.accounts: Dict[str, AccountState] = {
            account_id: AccountState(account_id=account_id) for account_id in self.valid_account_ids
        }
        self.market_prices: Dict[str, float] = {}
        self._lock = RLock()
        self.app = FastAPI(
            title="Automated Trading Risk-Control Service",
            version="1.0.0",
            description="In-memory RESTful API for order risk checks, exposure, and real-time P&L metrics.",
        )
        self._register_routes()

    def _register_routes(self) -> None:
        @self.app.post(
            "/orders",
            response_model=OrderResponse,
            responses={400: {"model": ErrorResponse}, 404: {"model": ErrorResponse}, 409: {"model": ErrorResponse}},
        )
        def submit_order(request: OrderRequest) -> OrderResponse:
            order = self.submit_order(request)
            return self._to_order_response(order)

        @self.app.post(
            "/orders/cancel",
            response_model=OrderResponse,
            responses={404: {"model": ErrorResponse}, 409: {"model": ErrorResponse}},
        )
        def cancel_order(request: CancelOrderRequest) -> OrderResponse:
            order = self.cancel_order(request.account_id, request.order_id)
            return self._to_order_response(order)

        @self.app.get(
            "/accounts/{account_id}/exposure/{symbol}",
            response_model=PositionResponse,
            responses={404: {"model": ErrorResponse}},
        )
        def get_exposure(
            account_id: str = Path(..., min_length=1),
            symbol: str = Path(..., min_length=1),
        ) -> PositionResponse:
            position = self.get_exposure(account_id, symbol.upper().strip())
            return self._to_position_response(symbol.upper().strip(), position)

        @self.app.post(
            "/risk/check",
            response_model=RiskCheckResponse,
            responses={404: {"model": ErrorResponse}},
        )
        def check_risk(request: RiskCheckRequest) -> RiskCheckResponse:
            return self.check_order_risk(
                account_id=request.account_id,
                symbol=request.symbol,
                side=request.side,
                quantity=request.quantity,
                price=request.price,
            )

        @self.app.post(
            "/market-price",
            response_model=dict,
            responses={400: {"model": ErrorResponse}},
        )
        def update_market_price(request: MarketPriceUpdateRequest) -> dict:
            self.update_market_price(request.symbol, request.price)
            return {"symbol": request.symbol, "price": request.price, "status": "updated"}

        @self.app.get(
            "/accounts/{account_id}/risk-metrics",
            response_model=AccountRiskMetricsResponse,
            responses={404: {"model": ErrorResponse}},
        )
        def get_account_risk_metrics(account_id: str = Path(..., min_length=1)) -> AccountRiskMetricsResponse:
            return self.get_account_risk_metrics(account_id)

    def _get_account(self, account_id: str) -> AccountState:
        account = self.accounts.get(account_id)
        if account is None:
            raise HTTPException(status_code=404, detail=f"Invalid account ID: {account_id}")
        return account

    def _signed_quantity(self, side: Side, quantity: float) -> float:
        return quantity if side == Side.BUY else -quantity

    def _recompute_account_unrealized_pnl(self, account: AccountState) -> None:
        for position in account.positions.values():
            if position.symbol in self.market_prices:
                position.market_price = self.market_prices[position.symbol]
            position.recompute_unrealized_pnl()

    def _account_total_notional_exposure(self, account: AccountState) -> float:
        return sum(position.notional_exposure for position in account.positions.values())

    def _account_total_unrealized_pnl(self, account: AccountState) -> float:
        return sum(position.unrealized_pnl for position in account.positions.values())

    def _account_daily_total_pnl(self, account: AccountState) -> float:
        return account.daily_realized_pnl + self._account_total_unrealized_pnl(account)

    def check_order_risk(
        self,
        account_id: str,
        symbol: str,
        side: Side,
        quantity: float,
        price: float,
    ) -> RiskCheckResponse:
        with self._lock:
            account = self._get_account(account_id)
            self._recompute_account_unrealized_pnl(account)

            current_position = account.positions.get(symbol, Position(symbol=symbol))
            signed_delta = self._signed_quantity(side, quantity)
            projected_quantity = current_position.quantity + signed_delta
            projected_position_size = abs(projected_quantity)

            temp_notional = 0.0
            for pos_symbol, pos in account.positions.items():
                if pos_symbol == symbol:
                    continue
                temp_notional += pos.notional_exposure

            projected_reference_price = self.market_prices.get(symbol, price)
            projected_notional_exposure = temp_notional + abs(projected_quantity) * projected_reference_price
            current_daily_pnl = self._account_daily_total_pnl(account)

            reasons: List[str] = []
            if projected_position_size > self.risk_limits.max_position_size:
                reasons.append(
                    f"Projected position size {projected_position_size:.2f} exceeds max {self.risk_limits.max_position_size:.2f}"
                )
            if projected_notional_exposure > self.risk_limits.max_notional_exposure:
                reasons.append(
                    f"Projected notional exposure {projected_notional_exposure:.2f} exceeds max {self.risk_limits.max_notional_exposure:.2f}"
                )
            if current_daily_pnl < -self.risk_limits.daily_loss_threshold:
                reasons.append(
                    f"Daily loss threshold breached: {current_daily_pnl:.2f} < -{self.risk_limits.daily_loss_threshold:.2f}"
                )

            return RiskCheckResponse(
                allowed=len(reasons) == 0,
                reasons=reasons,
                projected_position_size=projected_position_size,
                projected_notional_exposure=projected_notional_exposure,
                current_daily_pnl=current_daily_pnl,
                risk_limits=self.risk_limits,
            )

    def submit_order(self, request: OrderRequest) -> Order:
        with self._lock:
            account = self._get_account(request.account_id)

            if request.order_id in account.pending_orders:
                raise HTTPException(
                    status_code=409,
                    detail=f"Duplicate order ID for account {request.account_id}: {request.order_id}",
                )

            risk_result = self.check_order_risk(
                account_id=request.account_id,
                symbol=request.symbol,
                side=request.side,
                quantity=request.quantity,
                price=request.price,
            )
            if not risk_result.allowed:
                raise HTTPException(
                    status_code=409,
                    detail=f"Risk violation: {'; '.join(risk_result.reasons)}",
                )

            order = Order(
                order_id=request.order_id,
                account_id=request.account_id,
                symbol=request.symbol,
                side=request.side,
                quantity=request.quantity,
                price=request.price,
            )
            account.pending_orders[order.order_id] = order

            self._apply_fill(account, order)
            order.status = OrderStatus.FILLED
            del account.pending_orders[order.order_id]

            return order

    def cancel_order(self, account_id: str, order_id: str) -> Order:
        with self._lock:
            account = self._get_account(account_id)
            order = account.pending_orders.get(order_id)
            if order is None:
                raise HTTPException(
                    status_code=404,
                    detail=f"Order not found or not cancelable: {order_id}",
                )
            order.status = OrderStatus.CANCELED
            del account.pending_orders[order_id]
            return order

    def _apply_fill(self, account: AccountState, order: Order) -> None:
        position = account.positions.get(order.symbol)
        if position is None:
            position = Position(symbol=order.symbol)
            account.positions[order.symbol] = position

        fill_qty = self._signed_quantity(order.side, order.quantity)
        fill_price = order.price

        old_qty = position.quantity
        old_avg = position.avg_price
        new_qty = old_qty + fill_qty

        if old_qty == 0:
            position.quantity = fill_qty
            position.avg_price = fill_price
        elif old_qty > 0 and fill_qty > 0:
            total_cost = (old_qty * old_avg) + (fill_qty * fill_price)
            position.quantity = new_qty
            position.avg_price = total_cost / position.quantity
        elif old_qty < 0 and fill_qty < 0:
            total_cost = (abs(old_qty) * old_avg) + (abs(fill_qty) * fill_price)
            position.quantity = new_qty
            position.avg_price = total_cost / abs(position.quantity)
        else:
            closing_qty = min(abs(old_qty), abs(fill_qty))
            if old_qty > 0:
                realized = closing_qty * (fill_price - old_avg)
            else:
                realized = closing_qty * (old_avg - fill_price)
            account.daily_realized_pnl += realized

            if new_qty == 0:
                position.quantity = 0.0
                position.avg_price = 0.0
            elif (old_qty > 0 and new_qty > 0) or (old_qty < 0 and new_qty < 0):
                position.quantity = new_qty
            else:
                position.quantity = new_qty
                position.avg_price = fill_price

        if order.symbol in self.market_prices:
            position.market_price = self.market_prices[order.symbol]
        else:
            position.market_price = fill_price

        position.recompute_unrealized_pnl()

    def update_market_price(self, symbol: str, price: float) -> None:
        with self._lock:
            self.market_prices[symbol] = price
            for account in self.accounts.values():
                position = account.positions.get(symbol)
                if position is not None:
                    position.market_price = price
                    position.recompute_unrealized_pnl()

    def get_exposure(self, account_id: str, symbol: str) -> Position:
        with self._lock:
            account = self._get_account(account_id)
            position = account.positions.get(symbol)
            if position is None:
                return Position(symbol=symbol)
            if symbol in self.market_prices:
                position.market_price = self.market_prices[symbol]
                position.recompute_unrealized_pnl()
            return position

    def get_account_risk_metrics(self, account_id: str) -> AccountRiskMetricsResponse:
        with self._lock:
            account = self._get_account(account_id)
            self._recompute_account_unrealized_pnl(account)

            positions = [
                self._to_position_response(symbol, position)
                for symbol, position in sorted(account.positions.items())
            ]
            pending_orders = [
                self._to_order_response(order)
                for _, order in sorted(account.pending_orders.items(), key=lambda item: item[0])
            ]

            total_unrealized_pnl = self._account_total_unrealized_pnl(account)
            daily_total_pnl = account.daily_realized_pnl + total_unrealized_pnl

            return AccountRiskMetricsResponse(
                account_id=account.account_id,
                total_notional_exposure=self._account_total_notional_exposure(account),
                total_unrealized_pnl=total_unrealized_pnl,
                daily_realized_pnl=account.daily_realized_pnl,
                daily_total_pnl=daily_total_pnl,
                positions=positions,
                pending_orders=pending_orders,
            )

    def _to_position_response(self, symbol: str, position: Position) -> PositionResponse:
        return PositionResponse(
            symbol=symbol,
            quantity=position.quantity,
            avg_price=position.avg_price,
            market_price=position.market_price,
            notional_exposure=position.notional_exposure,
            unrealized_pnl=position.unrealized_pnl,
        )

    def _to_order_response(self, order: Order) -> OrderResponse:
        return OrderResponse(
            order_id=order.order_id,
            account_id=order.account_id,
            symbol=order.symbol,
            side=order.side,
            quantity=order.quantity,
            price=order.price,
            status=order.status,
            created_at=order.created_at,
        )


default_risk_limits = RiskLimits(
    max_position_size=100000.0,
    max_notional_exposure=5_000_000.0,
    daily_loss_threshold=100_000.0,
)

service = TradingRiskControlService(
    risk_limits=default_risk_limits,
    valid_account_ids=["ACC-001", "ACC-002", "ACC-003"],
)

app = service.app

import csv
import sys
from collections import defaultdict
from datetime import datetime, timedelta
from pathlib import Path


REQUIRED_FIELDS = {
    "transaction_id",
    "account_id",
    "transaction_amount",
    "transaction_time",
    "merchant_category",
    "country",
}


def parse_datetime(value: str) -> datetime:
    value = value.strip()
    formats = [
        "%Y-%m-%d %H:%M:%S",
        "%Y-%m-%dT%H:%M:%S",
        "%Y-%m-%d %H:%M",
        "%Y-%m-%dT%H:%M",
        "%Y-%m-%d",
    ]
    for fmt in formats:
        try:
            return datetime.strptime(value, fmt)
        except ValueError:
            continue
    try:
        return datetime.fromisoformat(value)
    except ValueError as exc:
        raise ValueError(f"Invalid datetime format: {value}") from exc


def read_transactions(csv_path: str):
    transactions = []
    errors = []

    with open(csv_path, "r", newline="", encoding="utf-8-sig") as f:
        reader = csv.DictReader(f)

        if not reader.fieldnames:
            raise ValueError("CSV file is missing a header row.")

        missing_headers = REQUIRED_FIELDS - set(reader.fieldnames)
        if missing_headers:
            raise ValueError(
                f"CSV file is missing required columns: {', '.join(sorted(missing_headers))}"
            )

        for line_num, row in enumerate(reader, start=2):
            missing_fields = [field for field in REQUIRED_FIELDS if not str(row.get(field, "")).strip()]
            if missing_fields:
                errors.append(
                    {
                        "line": line_num,
                        "transaction_id": row.get("transaction_id", ""),
                        "error": f"Missing required field(s): {', '.join(sorted(missing_fields))}",
                    }
                )
                continue

            try:
                amount = float(str(row["transaction_amount"]).strip())
            except (TypeError, ValueError):
                errors.append(
                    {
                        "line": line_num,
                        "transaction_id": row.get("transaction_id", ""),
                        "error": f"Invalid numeric value for transaction_amount: {row.get('transaction_amount')}",
                    }
                )
                continue

            try:
                tx_time = parse_datetime(str(row["transaction_time"]))
            except ValueError as exc:
                errors.append(
                    {
                        "line": line_num,
                        "transaction_id": row.get("transaction_id", ""),
                        "error": str(exc),
                    }
                )
                continue

            transactions.append(
                {
                    "transaction_id": str(row["transaction_id"]).strip(),
                    "account_id": str(row["account_id"]).strip(),
                    "transaction_amount": amount,
                    "transaction_time": tx_time,
                    "merchant_category": str(row["merchant_category"]).strip(),
                    "country": str(row["country"]).strip(),
                    "line": line_num,
                }
            )

    return transactions, errors


def compute_account_averages(transactions):
    amounts_by_account = defaultdict(list)
    for tx in transactions:
        amounts_by_account[tx["account_id"]].append(tx["transaction_amount"])

    return {
        account_id: (sum(amounts) / len(amounts) if amounts else 0.0)
        for account_id, amounts in amounts_by_account.items()
    }


def flag_large_amounts(transactions, account_averages, multiplier=3.0, minimum_threshold=1000.0):
    flagged = defaultdict(list)
    for tx in transactions:
        avg = account_averages.get(tx["account_id"], 0.0)
        if avg > 0 and tx["transaction_amount"] >= max(avg * multiplier, minimum_threshold):
            flagged[tx["transaction_id"]].append(
                f"large_amount: amount={tx['transaction_amount']:.2f}, account_avg={avg:.2f}"
            )
    return flagged


def flag_rapid_transactions(transactions, window_minutes=5, min_count=3):
    flagged = defaultdict(list)
    by_account = defaultdict(list)

    for tx in transactions:
        by_account[tx["account_id"]].append(tx)

    window = timedelta(minutes=window_minutes)

    for account_id, txs in by_account.items():
        sorted_txs = sorted(txs, key=lambda x: x["transaction_time"])
        for i, current_tx in enumerate(sorted_txs):
            recent = [
                tx
                for tx in sorted_txs[max(0, i - min_count + 1) : i + 1]
                if current_tx["transaction_time"] - tx["transaction_time"] <= window
            ]
            if len(recent) >= min_count:
                flagged[current_tx["transaction_id"]].append(
                    f"rapid_transactions: {len(recent)} transactions within {window_minutes} minutes"
                )

    return flagged


def flag_new_country_usage(transactions):
    flagged = defaultdict(list)
    by_account = defaultdict(list)

    for tx in transactions:
        by_account[tx["account_id"]].append(tx)

    for account_id, txs in by_account.items():
        sorted_txs = sorted(txs, key=lambda x: x["transaction_time"])
        seen_countries = set()

        for tx in sorted_txs:
            country = tx["country"]
            if seen_countries and country not in seen_countries:
                flagged[tx["transaction_id"]].append(
                    f"new_country: first use of country '{country}' for account '{account_id}'"
                )
            seen_countries.add(country)

    return flagged


def combine_flags(*flag_maps):
    combined = defaultdict(list)
    for flag_map in flag_maps:
        for tx_id, indicators in flag_map.items():
            combined[tx_id].extend(indicators)
    return combined


def build_summary(transactions, combined_flags):
    tx_lookup = {tx["transaction_id"]: tx for tx in transactions}
    flagged_ids = [tx["transaction_id"] for tx in transactions if tx["transaction_id"] in combined_flags]

    return [
        {
            "transaction_id": tx_id,
            "account_id": tx_lookup[tx_id]["account_id"],
            "transaction_amount": tx_lookup[tx_id]["transaction_amount"],
            "transaction_time": tx_lookup[tx_id]["transaction_time"].isoformat(sep=" "),
            "merchant_category": tx_lookup[tx_id]["merchant_category"],
            "country": tx_lookup[tx_id]["country"],
            "indicators": combined_flags[tx_id],
        }
        for tx_id in flagged_ids
    ]


def print_report(summary, errors):
    print("=" * 80)
    print("FRAUD ANALYSIS REPORT")
    print("=" * 80)
    print(f"Flagged transactions: {len(summary)}")
    print(f"Input errors skipped: {len(errors)}")
    print()

    if summary:
        for item in summary:
            print(f"Transaction ID   : {item['transaction_id']}")
            print(f"Account ID       : {item['account_id']}")
            print(f"Amount           : {item['transaction_amount']:.2f}")
            print(f"Time             : {item['transaction_time']}")
            print(f"Merchant Category: {item['merchant_category']}")
            print(f"Country          : {item['country']}")
            print("Indicators       :")
            for indicator in item["indicators"]:
                print(f"  - {indicator}")
            print("-" * 80)
    else:
        print("No suspicious transactions detected.")
        print("-" * 80)

    if errors:
        print()
        print("INPUT ERRORS")
        print("-" * 80)
        for err in errors:
            tx_id = err["transaction_id"] or "<unknown>"
            print(f"Line {err['line']} | Transaction {tx_id} | {err['error']}")


def analyze_transactions(csv_path: str):
    transactions, errors = read_transactions(csv_path)

    if not transactions:
        print_report([], errors)
        return

    account_averages = compute_account_averages(transactions)
    large_amount_flags = flag_large_amounts(transactions, account_averages)
    rapid_flags = flag_rapid_transactions(transactions)
    new_country_flags = flag_new_country_usage(transactions)

    combined_flags = combine_flags(large_amount_flags, rapid_flags, new_country_flags)
    summary = build_summary(transactions, combined_flags)
    print_report(summary, errors)


def main():
    if len(sys.argv) != 2:
        script_name = Path(sys.argv[0]).name
        print(f"Usage: python {script_name} <transactions.csv>")
        sys.exit(1)

    csv_path = sys.argv[1]

    try:
        analyze_transactions(csv_path)
    except FileNotFoundError:
        print(f"Error: File not found: {csv_path}")
        sys.exit(1)
    except ValueError as exc:
        print(f"Error: {exc}")
        sys.exit(1)
    except Exception as exc:
        print(f"Unexpected error: {exc}")
        sys.exit(1)


if __name__ == "__main__":
    main()

from __future__ import annotations

from collections import defaultdict
from concurrent.futures import ThreadPoolExecutor
from dataclasses import dataclass
from datetime import datetime, date
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP, getcontext
from threading import Lock
from typing import Any, DefaultDict, Dict, Iterable, List, Mapping, MutableMapping, Optional, Sequence, Tuple

getcontext().prec = 28


@dataclass(frozen=True)
class TransactionRecord:
    """
    Optional strongly-typed transaction record representation.

    The main processing function accepts generic mappings/dicts for flexibility,
    but this dataclass is provided for callers that prefer typed records.
    """
    user_id: Any
    timestamp: Any
    amount: Any
    currency: Any
    category: Any
    type: Any


@dataclass(frozen=True)
class SkippedRecordError:
    """
    Structured information about a skipped/malformed transaction record.
    """
    index: int
    reason: str
    record: Mapping[str, Any]


SummaryType = Dict[str, Dict[str, Dict[str, str]]]
ErrorListType = List[Dict[str, Any]]
ExchangeRatesType = Mapping[str, Mapping[str, Any]]


def process_transactions(
    transactions: Sequence[Mapping[str, Any]],
    base_currency: str,
    exchange_rates_by_day: ExchangeRatesType,
    worker_threads: int = 4,
) -> Tuple[SummaryType, ErrorListType]:
    """
    Process a high-volume stream of bank transactions into a thread-safe monthly spending
    summary per category for each user.

    The function:
    - Uses multithreading to parallelize normalization and aggregation.
    - Converts transaction amounts to `base_currency` using the historical exchange rate
      for the transaction date.
    - Includes only `debit` transactions in spending totals.
    - Groups totals by user_id -> YYYY-MM -> category.
    - Skips malformed records and returns structured error information.
    - Produces deterministic output regardless of thread scheduling by:
        1) partitioning work by stable input index ranges,
        2) aggregating locally within each worker,
        3) merging worker results in fixed worker order,
        4) sorting final nested keys.

    Synchronization choices and concurrency tradeoffs:
    - To reduce lock contention on millions of records, each worker aggregates into a local
      dictionary rather than updating a shared global structure for every record.
    - A lock is still used when publishing worker results into shared result slots to satisfy
      explicit thread-safety requirements around shared state updates.
    - This hybrid approach is typically faster and more memory-efficient than fine-grained
      locking on every transaction update.
    - Python's GIL limits CPU-bound scaling, but this design still performs well when parsing,
      validation, and dictionary operations are interleaved and when workloads involve I/O-like
      waiting or C-accelerated operations. It also keeps the implementation portable and simple.

    Edge cases handled:
    - Missing exchange rates for a transaction date or currency.
    - Invalid timestamps or unsupported timestamp formats.
    - Negative amounts.
    - Unknown transaction types.
    - Empty input.
    - Duplicate transaction records: duplicates are preserved and counted independently.
      (No deduplication is performed because records may legitimately repeat unless a unique
      transaction identifier is provided.)

    Accepted timestamp inputs:
    - datetime.datetime
    - datetime.date
    - ISO-8601-like strings, including those ending with 'Z'

    Expected exchange rate structure:
    {
        "YYYY-MM-DD": {
            "USD": 1,
            "EUR": 1.08,
            ...
        },
        ...
    }

    Rate semantics:
    - `exchange_rates_by_day[day][currency]` is interpreted as the value of 1 unit of
      `currency` expressed in `base_currency`.
    - Therefore: normalized_amount = amount * rate

    Args:
        transactions: Sequence of transaction records. Each record must contain:
            user_id, timestamp, amount, currency, category, type
        base_currency: Target currency code for normalization.
        exchange_rates_by_day: Historical exchange rates keyed by day string YYYY-MM-DD.
        worker_threads: Number of worker threads to use. Values < 1 are treated as 1.

    Returns:
        A tuple:
            (
                summary,
                skipped_errors
            )

        summary format:
            {
                "user_id": {
                    "YYYY-MM": {
                        "category": "normalized_amount_as_string"
                    }
                }
            }

        skipped_errors format:
            [
                {
                    "index": <input index>,
                    "reason": <string>,
                    "record": <original record>
                },
                ...
            ]
    """
    if not transactions:
        return {}, []

    worker_threads = max(1, int(worker_threads))
    normalized_base_currency = _normalize_currency_code(base_currency)
    if not normalized_base_currency:
        raise ValueError("base_currency must be a non-empty string")

    prepared_rates = _prepare_exchange_rates(exchange_rates_by_day)

    total_records = len(transactions)
    chunk_ranges = _build_chunk_ranges(total_records, worker_threads)

    # Shared publication structures. Workers publish exactly once, minimizing synchronization.
    published_partials: List[Optional[MutableMapping[str, MutableMapping[str, MutableMapping[str, Decimal]]]]] = [None] * len(chunk_ranges)
    published_errors: List[Optional[List[SkippedRecordError]]] = [None] * len(chunk_ranges)
    publish_lock = Lock()

    def worker(chunk_id: int, start: int, end: int) -> None:
        local_summary: DefaultDict[str, DefaultDict[str, DefaultDict[str, Decimal]]] = defaultdict(
            lambda: defaultdict(lambda: defaultdict(Decimal))
        )
        local_errors: List[SkippedRecordError] = []

        for idx in range(start, end):
            record = transactions[idx]
            normalized = _normalize_record(
                index=idx,
                record=record,
                base_currency=normalized_base_currency,
                prepared_rates=prepared_rates,
            )
            if isinstance(normalized, SkippedRecordError):
                local_errors.append(normalized)
                continue

            user_id, month_key, category, amount_in_base = normalized
            local_summary[user_id][month_key][category] += amount_in_base

        # Publish atomically into shared slots. This preserves thread safety while avoiding
        # high-frequency lock contention during per-record processing.
        with publish_lock:
            published_partials[chunk_id] = local_summary
            published_errors[chunk_id] = local_errors

    with ThreadPoolExecutor(max_workers=worker_threads) as executor:
        futures = [
            executor.submit(worker, chunk_id, start, end)
            for chunk_id, (start, end) in enumerate(chunk_ranges)
        ]
        for future in futures:
            future.result()

    # Deterministic merge in chunk order, independent of thread completion order.
    merged: DefaultDict[str, DefaultDict[str, DefaultDict[str, Decimal]]] = defaultdict(
        lambda: defaultdict(lambda: defaultdict(Decimal))
    )
    all_errors: List[SkippedRecordError] = []

    for chunk_id in range(len(chunk_ranges)):
        partial = published_partials[chunk_id]
        errors = published_errors[chunk_id]

        if partial:
            for user_id, months in partial.items():
                for month_key, categories in months.items():
                    for category, amount in categories.items():
                        merged[user_id][month_key][category] += amount

        if errors:
            all_errors.extend(errors)

    summary = _finalize_summary(merged)
    error_list = [
        {
            "index": err.index,
            "reason": err.reason,
            "record": dict(err.record),
        }
        for err in sorted(all_errors, key=lambda e: e.index)
    ]
    return summary, error_list


def _build_chunk_ranges(total_records: int, worker_threads: int) -> List[Tuple[int, int]]:
    """
    Split input into contiguous chunks to preserve deterministic processing partitions.
    """
    if total_records <= 0:
        return []

    worker_count = min(worker_threads, total_records)
    base_size, remainder = divmod(total_records, worker_count)

    ranges: List[Tuple[int, int]] = []
    start = 0
    for i in range(worker_count):
        size = base_size + (1 if i < remainder else 0)
        end = start + size
        ranges.append((start, end))
        start = end
    return ranges


def _prepare_exchange_rates(
    exchange_rates_by_day: ExchangeRatesType,
) -> Dict[str, Dict[str, Decimal]]:
    """
    Normalize exchange rate keys and values once up front for performance.

    Invalid rate entries are ignored so that malformed rate data does not crash the entire run.
    Missing/invalid rates are later reported per affected transaction as skipped-record errors.
    """
    prepared: Dict[str, Dict[str, Decimal]] = {}

    for day_key, currency_map in exchange_rates_by_day.items():
        if not isinstance(day_key, str) or not isinstance(currency_map, Mapping):
            continue

        normalized_day = day_key.strip()
        if not normalized_day:
            continue

        day_rates: Dict[str, Decimal] = {}
        for currency, rate in currency_map.items():
            normalized_currency = _normalize_currency_code(currency)
            if not normalized_currency:
                continue

            decimal_rate = _to_decimal(rate)
            if decimal_rate is None or decimal_rate <= 0:
                continue

            day_rates[normalized_currency] = decimal_rate

        if day_rates:
            prepared[normalized_day] = day_rates

    return prepared


def _normalize_record(
    index: int,
    record: Mapping[str, Any],
    base_currency: str,
    prepared_rates: Mapping[str, Mapping[str, Decimal]],
) -> Tuple[str, str, str, Decimal] | SkippedRecordError:
    """
    Validate and normalize a single transaction record.

    Returns:
        (user_id, month_key, category, amount_in_base_currency)
        or SkippedRecordError
    """
    if not isinstance(record, Mapping):
        return SkippedRecordError(index=index, reason="record is not a mapping", record={"value": record})

    required_fields = ("user_id", "timestamp", "amount", "currency", "category", "type")
    missing = [field for field in required_fields if field not in record]
    if missing:
        return SkippedRecordError(
            index=index,
            reason=f"missing required fields: {', '.join(missing)}",
            record=record,
        )

    user_id = record.get("user_id")
    if user_id is None or (isinstance(user_id, str) and not user_id.strip()):
        return SkippedRecordError(index=index, reason="invalid user_id", record=record)

    category = record.get("category")
    if category is None or (isinstance(category, str) and not category.strip()):
        return SkippedRecordError(index=index, reason="invalid category", record=record)

    tx_type_raw = record.get("type")
    tx_type = str(tx_type_raw).strip().lower() if tx_type_raw is not None else ""
    if tx_type not in {"debit", "credit"}:
        return SkippedRecordError(index=index, reason="unknown transaction type", record=record)

    # Only debit transactions contribute to spending totals.
    if tx_type != "debit":
        return SkippedRecordError(index=index, reason="non-debit transaction excluded", record=record)

    amount = _to_decimal(record.get("amount"))
    if amount is None:
        return SkippedRecordError(index=index, reason="invalid amount", record=record)
    if amount < 0:
        return SkippedRecordError(index=index, reason="negative amount", record=record)

    currency = _normalize_currency_code(record.get("currency"))
    if not currency:
        return SkippedRecordError(index=index, reason="invalid currency", record=record)

    parsed_dt = _parse_timestamp(record.get("timestamp"))
    if parsed_dt is None:
        return SkippedRecordError(index=index, reason="invalid timestamp", record=record)

    day_key = parsed_dt.date().isoformat()
    month_key = parsed_dt.strftime("%Y-%m")

    amount_in_base = amount if currency == base_currency else _convert_amount(
        amount=amount,
        source_currency=currency,
        day_key=day_key,
        prepared_rates=prepared_rates,
    )
    if amount_in_base is None:
        return SkippedRecordError(
            index=index,
            reason=f"missing exchange rate for {currency} on {day_key}",
            record=record,
        )

    return str(user_id), month_key, str(category), amount_in_base


def _convert_amount(
    amount: Decimal,
    source_currency: str,
    day_key: str,
    prepared_rates: Mapping[str, Mapping[str, Decimal]],
) -> Optional[Decimal]:
    """
    Convert amount into base currency using the historical rate for the given day.

    Rate semantics:
        amount_in_base = amount * rate[day][source_currency]
    """
    day_rates = prepared_rates.get(day_key)
    if not day_rates:
        return None

    rate = day_rates.get(source_currency)
    if rate is None or rate <= 0:
        return None

    return amount * rate


def _parse_timestamp(value: Any) -> Optional[datetime]:
    """
    Parse supported timestamp formats into a datetime.

    Supported:
    - datetime
    - date
    - ISO 8601 strings, including trailing 'Z'
    """
    if isinstance(value, datetime):
        return value

    if isinstance(value, date):
        return datetime(value.year, value.month, value.day)

    if not isinstance(value, str):
        return None

    text = value.strip()
    if not text:
        return None

    try:
        if text.endswith("Z"):
            text = text[:-1] + "+00:00"
        return datetime.fromisoformat(text)
    except ValueError:
        return None


def _to_decimal(value: Any) -> Optional[Decimal]:
    """
    Convert a value to Decimal safely.

    Floats are converted through str() to reduce binary floating-point artifacts.
    """
    try:
        if isinstance(value, Decimal):
            return value
        if isinstance(value, float):
            return Decimal(str(value))
        return Decimal(str(value))
    except (InvalidOperation, ValueError, TypeError):
        return None


def _normalize_currency_code(value: Any) -> str:
    """
    Normalize currency codes to uppercase strings.
    """
    if not isinstance(value, str):
        return ""
    return value.strip().upper()


def _finalize_summary(
    merged: Mapping[str, Mapping[str, Mapping[str, Decimal]]]
) -> SummaryType:
    """
    Convert Decimal totals into deterministic, sorted nested dictionaries.

    Amounts are quantized to 2 decimal places using bankers-safe financial rounding
    convention here chosen as ROUND_HALF_UP for user-facing summaries.
    """
    quant = Decimal("0.01")
    result: SummaryType = {}

    for user_id in sorted(merged.keys()):
        months = merged[user_id]
        result[user_id] = {}
        for month_key in sorted(months.keys()):
            categories = months[month_key]
            result[user_id][month_key] = {}
            for category in sorted(categories.keys()):
                amount = categories[category].quantize(quant, rounding=ROUND_HALF_UP)
                result[user_id][month_key][category] = format(amount, "f")

    return result

from collections import defaultdict
from typing import Any, Dict, List, Optional

from fastapi import APIRouter, FastAPI, HTTPException, status
from pydantic import BaseModel, Field, validator


class InstanceRecord(BaseModel):
    instance_id: str = Field(..., min_length=1)
    region: str = Field(..., min_length=1)
    instance_type: str = Field(..., min_length=1)
    state: str = Field(..., min_length=1)
    cpu_utilization: float = Field(..., ge=0.0, le=100.0)
    tags: Dict[str, str]

    @validator("instance_id", "region", "instance_type", "state")
    def non_empty_string(cls, value: str) -> str:
        if not isinstance(value, str) or not value.strip():
            raise ValueError("must be a non-empty string")
        return value.strip()

    @validator("tags")
    def validate_tags(cls, value: Dict[str, str]) -> Dict[str, str]:
        if not isinstance(value, dict):
            raise ValueError("tags must be an object of string key/value pairs")
        normalized: Dict[str, str] = {}
        for k, v in value.items():
            if not isinstance(k, str) or not k.strip():
                raise ValueError("tag keys must be non-empty strings")
            if not isinstance(v, str):
                raise ValueError("tag values must be strings")
            normalized[k.strip()] = v
        return normalized


class InstancesUploadRequest(BaseModel):
    instances: List[Dict[str, Any]] = Field(..., min_items=1)


class InvalidRecord(BaseModel):
    index: int
    errors: List[str]
    record: Optional[Dict[str, Any]] = None


class ValidationErrorResponse(BaseModel):
    message: str
    invalid_records: List[InvalidRecord]


class SummaryResponse(BaseModel):
    total_instance_count: int
    count_by_region: Dict[str, int]
    count_by_state: Dict[str, int]
    average_cpu_utilization_by_region: Dict[str, float]
    instances_missing_environment_tag: List[str]


def validate_instances(raw_instances: List[Dict[str, Any]]) -> List[InstanceRecord]:
    valid_instances: List[InstanceRecord] = []
    invalid_records: List[InvalidRecord] = []

    for idx, raw in enumerate(raw_instances):
        try:
            valid_instances.append(InstanceRecord.parse_obj(raw))
        except Exception as exc:
            errors: List[str] = []
            if hasattr(exc, "errors"):
                for err in exc.errors():
                    loc = ".".join(str(part) for part in err.get("loc", []))
                    msg = err.get("msg", "Invalid value")
                    errors.append(f"{loc}: {msg}" if loc else msg)
            else:
                errors.append(str(exc))

            invalid_records.append(
                InvalidRecord(index=idx, errors=errors, record=raw if isinstance(raw, dict) else None)
            )

    if invalid_records:
        raise HTTPException(
            status_code=status.HTTP_422_UNPROCESSABLE_ENTITY,
            detail={
                "message": "One or more instance records are invalid.",
                "invalid_records": [record.dict() for record in invalid_records],
            },
        )

    return valid_instances


def aggregate_instances(instances: List[InstanceRecord]) -> SummaryResponse:
    count_by_region: Dict[str, int] = defaultdict(int)
    count_by_state: Dict[str, int] = defaultdict(int)
    cpu_sum_by_region: Dict[str, float] = defaultdict(float)
    cpu_count_by_region: Dict[str, int] = defaultdict(int)
    missing_environment_tag: List[str] = []

    for instance in instances:
        count_by_region[instance.region] += 1
        count_by_state[instance.state] += 1
        cpu_sum_by_region[instance.region] += instance.cpu_utilization
        cpu_count_by_region[instance.region] += 1

        if "Environment" not in instance.tags or not instance.tags.get("Environment", "").strip():
            missing_environment_tag.append(instance.instance_id)

    average_cpu_utilization_by_region = {
        region: round(cpu_sum_by_region[region] / cpu_count_by_region[region], 2)
        for region in cpu_sum_by_region
    }

    return SummaryResponse(
        total_instance_count=len(instances),
        count_by_region=dict(count_by_region),
        count_by_state=dict(count_by_state),
        average_cpu_utilization_by_region=average_cpu_utilization_by_region,
        instances_missing_environment_tag=missing_environment_tag,
    )


router = APIRouter(prefix="/api/v1", tags=["ec2-metadata"])


@router.post(
    "/instances/validate-summary",
    response_model=SummaryResponse,
    status_code=status.HTTP_200_OK,
    responses={
        422: {
            "model": ValidationErrorResponse,
            "description": "Validation error for one or more uploaded instance records.",
        }
    },
)
def validate_and_summarize_instances(payload: InstancesUploadRequest) -> SummaryResponse:
    instances = validate_instances(payload.instances)
    return aggregate_instances(instances)


app = FastAPI(
    title="AWS EC2 Metadata Validation API",
    version="1.0.0",
    description="Validate and summarize uploaded AWS EC2 instance metadata for cloud operations dashboards.",
)

app.include_router(router)


@app.get("/health", status_code=status.HTTP_200_OK)
def health_check() -> Dict[str, str]:
    return {"status": "ok"}

class ModelMetadata:
    def __init__(self, name, version, framework, accuracy_score):
        self.name = name
        self.version = version
        self.framework = framework
        self.accuracy_score = accuracy_score

    @property
    def name(self):
        return self._name

    @name.setter
    def name(self, value):
        if not isinstance(value, str) or not value.strip():
            raise ValueError("Model name must be a non-empty string.")
        self._name = value.strip()

    @property
    def version(self):
        return self._version

    @version.setter
    def version(self, value):
        if not isinstance(value, str) or not value.strip():
            raise ValueError("Version must be a non-empty string.")
        self._version = value.strip()

    @property
    def framework(self):
        return self._framework

    @framework.setter
    def framework(self, value):
        if not isinstance(value, str) or not value.strip():
            raise ValueError("Framework must be a non-empty string.")
        self._framework = value.strip()

    @property
    def accuracy_score(self):
        return self._accuracy_score

    @accuracy_score.setter
    def accuracy_score(self, value):
        if not isinstance(value, (int, float)):
            raise ValueError("Accuracy score must be a number.")
        if not 0 <= value <= 100:
            raise ValueError("Accuracy score must be between 0 and 100.")
        self._accuracy_score = float(value)

    def update_metadata(self, name=None, version=None, framework=None, accuracy_score=None):
        if name is not None:
            self.name = name
        if version is not None:
            self.version = version
        if framework is not None:
            self.framework = framework
        if accuracy_score is not None:
            self.accuracy_score = accuracy_score

    def display_info(self):
        print("Model Information")
        print("-----------------")
        print(f"Name: {self.name}")
        print(f"Version: {self.version}")
        print(f"Framework: {self.framework}")
        print(f"Accuracy Score: {self.accuracy_score:.2f}%")

    def __str__(self):
        return (
            f"ModelMetadata(name='{self.name}', version='{self.version}', "
            f"framework='{self.framework}', accuracy_score={self.accuracy_score:.2f}%)"
        )


