class CloudProviderAdapter(ABC):
    provider_name: str

    @abstractmethod
    def list_instances(self) -> List[VMInstance]:
        raise NotImplementedError

    @abstractmethod
    def fetch_instance_metrics(self, instance: VMInstance) -> Dict[str, Any]:
        raise NotImplementedError


def retry_call(func, retry_config: RetryConfig, *args, **kwargs):
    attempt = 0
    delay = retry_config.initial_backoff_seconds
    while True:
        attempt += 1
        try:
            return func(*args, **kwargs)
        except TransientAPIError as exc:
            if attempt >= retry_config.max_attempts:
                LOGGER.error("Retry exhausted for %s: %s", func.__name__, exc)
                raise
            sleep_for = min(delay, retry_config.max_backoff_seconds) + random.uniform(
                0, retry_config.jitter_seconds
            )
            LOGGER.warning(
                "Transient failure in %s (attempt %s/%s): %s; retrying in %.2fs",
                func.__name__,
                attempt,
                retry_config.max_attempts,
                exc,
                sleep_for,
            )
            time.sleep(sleep_for)
            delay *= retry_config.backoff_multiplier


class AWSAdapter(CloudProviderAdapter):
    provider_name = "aws"

    def __init__(self, instances: Optional[List[VMInstance]] = None):
        self._instances = instances or [
            VMInstance("aws", "i-0a1b2c3d4e", "us-east-1", "web-1"),
            VMInstance("aws", "i-0f6g7h8i9j", "us-west-2", "db-1"),
        ]

    def list_instances(self) -> List[VMInstance]:
        return list(self._instances)

    def fetch_instance_metrics(self, instance: VMInstance) -> Dict[str, Any]:
        self._simulate_latency_and_failures(instance.instance_id)
        return {
            "InstanceId": instance.instance_id,
            "InstanceName": instance.name,
            "Region": instance.region,
            "Timestamp": datetime.now(timezone.utc).isoformat(),
            "CPUUtilization": round(random.uniform(10, 99), 2),
            "MemoryUtilization": round(random.uniform(20, 98), 2),
            "DiskUsedPercent": round(random.uniform(15, 97), 2),
            "NetworkInMbps": round(random.uniform(5, 1200), 2),
            "NetworkOutMbps": round(random.uniform(5, 1200), 2),
            "State": random.choice(["running", "running", "running", "degraded"]),
        }

    @staticmethod
    def _simulate_latency_and_failures(seed: str) -> None:
        random.seed(f"aws-{seed}-{int(time.time()) // 10}")
        time.sleep(random.uniform(0.05, 0.25))
        p = random.random()
        if p < 0.08:
            raise TransientAPIError("AWS API throttling")
        if p < 0.10:
            raise PermanentAPIError("AWS instance not found")


