    @staticmethod
    def _simulate_latency_and_failures(seed: str) -> None:
        random.seed(f"gcp-{seed}-{int(time.time()) // 10}")
        time.sleep(random.uniform(0.05, 0.28))
        p = random.random()
        if p < 0.06:
            raise TransientAPIError("GCP metrics endpoint unavailable")
        if p < 0.08:
            raise PermanentAPIError("GCP instance deleted")


class MetricsNormalizer:
    @staticmethod
    def normalize(provider: str, raw: Dict[str, Any]) -> UnifiedMetrics:
        if provider == "aws":
            return UnifiedMetrics(
                provider="aws",
                instance_id=str(raw["InstanceId"]),
                instance_name=str(raw["InstanceName"]),
                region=str(raw["Region"]),
                timestamp=str(raw["Timestamp"]),
                cpu_percent=float(raw["CPUUtilization"]),
                memory_percent=float(raw["MemoryUtilization"]),
                disk_percent=float(raw["DiskUsedPercent"]),
                network_in_mbps=float(raw["NetworkInMbps"]),
                network_out_mbps=float(raw["NetworkOutMbps"]),
                status=str(raw["State"]),
                raw_metrics=raw,
            )
        if provider == "azure":
            return UnifiedMetrics(
                provider="azure",
                instance_id=str(raw["vmId"]),
                instance_name=str(raw["name"]),
                region=str(raw["location"]),
                timestamp=str(raw["timeGenerated"]),
                cpu_percent=float(raw["percentage CPU"]),
                memory_percent=float(raw["memory\\percentused"]),
                disk_percent=float(raw["disk\\used_percent"]),
                network_in_mbps=float(raw["network\\in_mbps"]),
                network_out_mbps=float(raw["network\\out_mbps"]),
                status=str(raw["powerState"]),
                raw_metrics=raw,
            )
        if provider == "gcp":
            return UnifiedMetrics(
                provider="gcp",
                instance_id=str(raw["id"]),
                instance_name=str(raw["instance_name"]),
                region=str(raw["zone"]),
                timestamp=str(raw["collected_at"]),
                cpu_percent=float(raw["cpu/utilization_percent"]),
                memory_percent=float(raw["memory/utilization_percent"]),
                disk_percent=float(raw["disk/utilization_percent"]),
                network_in_mbps=float(raw["network/rx_mbps"]),
                network_out_mbps=float(raw["network/tx_mbps"]),
                status=str(raw["health"]),
                raw_metrics=raw,
            )
        raise ValueError(f"Unsupported provider: {provider}")


class AlertEvaluator:
    @staticmethod
    def evaluate(metrics: UnifiedMetrics, thresholds: Thresholds) -> List[Alert]:
        alerts: List[Alert] = []

        def add_alert(metric: str, value: float, threshold: float):
            severity = "critical" if value >= threshold * 1.1 else "warning"
            alerts.append(
                Alert(
                    provider=metrics.provider,
                    instance_id=metrics.instance_id,
                    instance_name=metrics.instance_name,
                    region=metrics.region,
                    metric=metric,
                    value=round(value, 2),
                    threshold=threshold,
                    severity=severity,
                    timestamp=metrics.timestamp,
                    message=(
                        f"{metrics.provider}:{metrics.instance_name} ({metrics.instance_id}) "
                        f"{metric}={value:.2f} breached threshold {threshold:.2f}"
                    ),
                )
            )

        if metrics.cpu_percent >= thresholds.cpu_percent:
            add_alert("cpu_percent", metrics.cpu_percent, thresholds.cpu_percent)
        if metrics.memory_percent >= thresholds.memory_percent:
            add_alert("memory_percent", metrics.memory_percent, thresholds.memory_percent)
        if metrics.disk_percent >= thresholds.disk_percent:
            add_alert("disk_percent", metrics.disk_percent, thresholds.disk_percent)
        if metrics.network_in_mbps >= thresholds.network_mbps:
            add_alert("network_in_mbps", metrics.network_in_mbps, thresholds.network_mbps)
        if metrics.network_out_mbps >= thresholds.network_mbps:
            add_alert("network_out_mbps", metrics.network_out_mbps, thresholds.network_mbps)

        return alerts


class ReportGenerator:
    @staticmethod
    def generate(
        metrics: List[UnifiedMetrics],
        alerts: List[Alert],
        errors: List[Dict[str, Any]],
        generated_at: Optional[str] = None,
    ) -> Dict[str, Any]:
        generated_at = generated_at or datetime.now(timezone.utc).isoformat()
        provider_summary: Dict[str, Dict[str, int]] = {}

        for item in metrics:
            provider_summary.setdefault(
                item.provider,
                {"instances": 0, "alerts": 0},
            )
            provider_summary[item.provider]["instances"] += 1

        for alert in alerts:
            provider_summary.setdefault(
                alert.provider,
                {"instances": 0, "alerts": 0},
            )
            provider_summary[alert.provider]["alerts"] += 1

        return {
            "generated_at": generated_at,
            "summary": {
                "total_instances": len(metrics),
                "total_alerts": len(alerts),
                "total_errors": len(errors),
                "providers": provider_summary,
            },
            "metrics": [asdict(m) for m in metrics],
            "alerts": [asdict(a) for a in alerts],
            "errors": errors,
        }


class VMHealthMonitor:
    def __init__(self, adapters: List[CloudProviderAdapter], config: Optional[MonitorConfig] = None):
        self.adapters = adapters
        self.config = config or MonitorConfig()
        self._metrics: List[UnifiedMetrics] = []
        self._alerts: List[Alert] = []
        self._errors: List[Dict[str, Any]] = []
        self._lock = threading.Lock()

    def _record_metric_and_alerts(self, metric: UnifiedMetrics, alerts: List[Alert]) -> None:
        with self._lock:
            self._metrics.append(metric)
            self._alerts.extend(alerts)

    def _record_error(self, provider: str, instance: VMInstance, error: Exception) -> None:
        with self._lock:
            self._errors.append(
                {
                    "provider": provider,
                    "instance_id": instance.instance_id,
                    "instance_name": instance.name,
                    "region": instance.region,
                    "error_type": type(error).__name__,
                    "message": str(error),
                    "timestamp": datetime.now(timezone.utc).isoformat(),
                }
            )

    def _fetch_normalize_evaluate(
        self, adapter: CloudProviderAdapter, instance: VMInstance
    ) -> Tuple[Optional[UnifiedMetrics], List[Alert]]:
        raw = retry_call(
            adapter.fetch_instance_metrics,
            self.config.retry,
            instance,
        )
        normalized = MetricsNormalizer.normalize(adapter.provider_name, raw)
        alerts = AlertEvaluator.evaluate(normalized, self.config.thresholds)
        return normalized, alerts

    def poll_once(self) -> Dict[str, Any]:
        self._metrics = []
        self._alerts = []
        self._errors = []

        tasks = []
        with ThreadPoolExecutor(max_workers=self.config.max_workers) as executor:
            for adapter in self.adapters:
                for instance in adapter.list_instances():
                    tasks.append(
                        executor.submit(self._fetch_normalize_evaluate, adapter, instance)
                    )

            for future in as_completed(tasks):
                try:
                    metric, alerts = future.result()
                    if metric is not None:
                        self._record_metric_and_alerts(metric, alerts)
                except Exception as exc:
                    provider, instance = self._extract_context_from_exception(exc)
                    if provider and instance:
                        self._record_error(provider, instance, exc)
                    else:
                        with self._lock:
                            self._errors.append(
                                {
                                    "provider": "unknown",
                                    "instance_id": "unknown",
                                    "instance_name": "unknown",
                                    "region": "unknown",
                                    "error_type": type(exc).__name__,
                                    "message": str(exc),
                                    "timestamp": datetime.now(timezone.utc).isoformat(),
                                }
                            )

        return ReportGenerator.generate(
            metrics=sorted(self._metrics, key=lambda x: (x.provider, x.region, x.instance_name)),
            alerts=sorted(self._alerts, key=lambda x: (x.provider, x.instance_name, x.metric)),
            errors=self._errors,
        )

    def _extract_context_from_exception(self, exc: Exception) -> Tuple[Optional[str], Optional[VMInstance]]:
        cause = exc
        while cause:
            if hasattr(cause, "__dict__"):
                provider = getattr(cause, "_provider", None)
                instance = getattr(cause, "_instance", None)
                if provider and instance:
                    return provider, instance
            cause = cause.__cause__
        return None, None

    def run_forever(self) -> None:
        while True:
            report = self.poll_once()
            print(json.dumps(report, indent=2))
            time.sleep(self.config.polling_interval_seconds)


class ContextualAdapterWrapper(CloudProviderAdapter):
    def __init__(self, wrapped: CloudProviderAdapter):
        self.wrapped = wrapped
        self.provider_name = wrapped.provider_name

    def list_instances(self) -> List[VMInstance]:
        return self.wrapped.list_instances()

    def fetch_instance_metrics(self, instance: VMInstance) -> Dict[str, Any]:
        try:
            return self.wrapped.fetch_instance_metrics(instance)
        except Exception as exc:
            setattr(exc, "_provider", self.provider_name)
            setattr(exc, "_instance", instance)
            raise


def build_default_monitor() -> VMHealthMonitor:
    adapters: List[CloudProviderAdapter] = [
        ContextualAdapterWrapper(AWSAdapter()),
        ContextualAdapterWrapper(AzureAdapter()),
        ContextualAdapterWrapper(GCPAdapter()),
    ]
    config = MonitorConfig(
        polling_interval_seconds=15.0,
        max_workers=8,
        thresholds=Thresholds(
            cpu_percent=80.0,
            memory_percent=85.0,
            disk_percent=88.0,
            network_mbps=900.0,
        ),
        retry=RetryConfig(
            max_attempts=4,
            initial_backoff_seconds=0.25,
            backoff_multiplier=2.0,
            max_backoff_seconds=2.0,
            jitter_seconds=0.15,
        ),
    )
    return VMHealthMonitor(adapters=adapters, config=config)


if __name__ == "__main__":
    monitor = build_default_monitor()
    report = monitor.poll_once()
    print(json.dumps(report, indent=2))

from __future__ import annotations

from collections import defaultdict, deque
from dataclasses import dataclass, field
from typing import Any, Deque, Dict, Iterable, List, Optional


@dataclass
class BreakoutConfig:
    window_size: int = 5
    threshold_pct: float = 0.01
    allowed_signals: tuple = ("BUY", "SELL")

    def validate(self) -> None:
        if not isinstance(self.window_size, int) or self.window_size < 2:
            raise ValueError("window_size must be an integer >= 2")
        if not isinstance(self.threshold_pct, (int, float)) or self.threshold_pct < 0:
            raise ValueError("threshold_pct must be a non-negative number")
        if not isinstance(self.allowed_signals, tuple) or not self.allowed_signals:
            raise ValueError("allowed_signals must be a non-empty tuple")


@dataclass
class TickProcessor:
    config: BreakoutConfig
    windows: Dict[str, Deque[float]] = field(default_factory=lambda: defaultdict(deque))

    def __post_init__(self) -> None:
        self.config.validate()

    def ingest_tick(self, tick: Dict[str, Any]) -> Dict[str, Any]:
        validate_tick(tick)
        symbol = tick["symbol"]
        price = float(tick["price"])
        timestamp = tick.get("timestamp")
        previous_prices = list(self.windows[symbol])
        self.update_window(symbol, price)
        signal = self.evaluate_signal(symbol, price, previous_prices)
        return self.format_result(symbol, price, timestamp, signal, previous_prices)

    def update_window(self, symbol: str, price: float) -> None:
        if symbol not in self.windows:
            self.windows[symbol] = deque(maxlen=self.config.window_size)
        self.windows[symbol].append(price)

    def evaluate_signal(
        self, symbol: str, latest_price: float, previous_prices: List[float]
    ) -> Optional[str]:
        if len(previous_prices) < self.config.window_size:
            return None

        # Lambda extracts breakout reference levels from the prior window.
        get_bounds = lambda prices: (max(prices), min(prices))
        prev_max, prev_min = get_bounds(previous_prices)

        buy_trigger = prev_max * (1 + self.config.threshold_pct)
        sell_trigger = prev_min * (1 - self.config.threshold_pct)

        if latest_price > buy_trigger and "BUY" in self.config.allowed_signals:
            return "BUY"
        if latest_price < sell_trigger and "SELL" in self.config.allowed_signals:
            return "SELL"
        return None

    def format_result(
        self,
        symbol: str,
        price: float,
        timestamp: Any,
        signal: Optional[str],
        previous_prices: List[float],
    ) -> Dict[str, Any]:
        # Lambda rounds numeric values for compact output formatting.
        round_if_num = lambda x: round(x, 4) if isinstance(x, (int, float)) else x
        return {
            "symbol": symbol,
            "timestamp": timestamp,
            "price": round_if_num(price),
            "window_before_tick": list(map(round_if_num, previous_prices)),
            "window_after_tick": list(map(round_if_num, self.windows[symbol])),
            "signal": signal or "HOLD",
        }


def validate_tick(tick: Dict[str, Any]) -> None:
    if not isinstance(tick, dict):
        raise TypeError("Each tick must be a dictionary")
    if "symbol" not in tick or "price" not in tick:
        raise ValueError("Each tick must contain 'symbol' and 'price'")
    if not isinstance(tick["symbol"], str) or not tick["symbol"].strip():
        raise ValueError("'symbol' must be a non-empty string")
    if not isinstance(tick["price"], (int, float)):
        raise ValueError("'price' must be numeric")
    if tick["price"] <= 0:
        raise ValueError("'price' must be greater than 0")


def process_ticks(
    ticks: Iterable[Dict[str, Any]],
    window_size: int = 5,
    threshold_pct: float = 0.01,
) -> List[Dict[str, Any]]:
    if not isinstance(ticks, Iterable):
        raise TypeError("ticks must be an iterable of tick dictionaries")

    processor = TickProcessor(
        config=BreakoutConfig(window_size=window_size, threshold_pct=threshold_pct)
    )

    # Lambda filters only actionable signals for downstream use if needed.
    to_result = lambda tick: processor.ingest_tick(tick)
    results = list(map(to_result, ticks))
    return results


def example() -> None:
    sample_ticks = [
        {"symbol": "AAPL", "price": 100.0, "timestamp": "2026-04-19T09:30:00"},
        {"symbol": "AAPL", "price": 101.0, "timestamp": "2026-04-19T09:30:01"},
        {"symbol": "AAPL", "price": 100.5, "timestamp": "2026-04-19T09:30:02"},
        {"symbol": "AAPL", "price": 101.2, "timestamp": "2026-04-19T09:30:03"},
        {"symbol": "AAPL", "price": 100.8, "timestamp": "2026-04-19T09:30:04"},
        {"symbol": "AAPL", "price": 103.0, "timestamp": "2026-04-19T09:30:05"},  # BUY
        {"symbol": "MSFT", "price": 200.0, "timestamp": "2026-04-19T09:30:00"},
        {"symbol": "MSFT", "price": 199.5, "timestamp": "2026-04-19T09:30:01"},
        {"symbol": "MSFT", "price": 199.8, "timestamp": "2026-04-19T09:30:02"},
        {"symbol": "MSFT", "price": 199.2, "timestamp": "2026-04-19T09:30:03"},
        {"symbol": "MSFT", "price": 199.4, "timestamp": "2026-04-19T09:30:04"},
        {"symbol": "MSFT", "price": 196.5, "timestamp": "2026-04-19T09:30:05"},  # SELL
    ]

    results = process_ticks(sample_ticks, window_size=5, threshold_pct=0.01)

    # Lambda keeps output concise by selecting key fields.
    summarize = lambda r: {
        "timestamp": r["timestamp"],
        "symbol": r["symbol"],
        "price": r["price"],
        "signal": r["signal"],
    }

    for item in map(summarize, results):
        print(item)


