from __future__ import annotations

from dataclasses import dataclass, field
from datetime import date, datetime, time
from typing import Dict, List, Optional, Set, Tuple


@dataclass(frozen=True)
class Patient:
    patient_id: str
    name: str


@dataclass
class Doctor:
    doctor_id: str
    name: str
    available_slots: Dict[date, Set[time]] = field(default_factory=dict)

    def add_available_slots(self, appointment_date: date, slots: List[time]) -> None:
        if appointment_date not in self.available_slots:
            self.available_slots[appointment_date] = set()
        self.available_slots[appointment_date].update(slots)

    def is_slot_available(self, appointment_date: date, appointment_time: time) -> bool:
        return (
            appointment_date in self.available_slots
            and appointment_time in self.available_slots[appointment_date]
        )


@dataclass(frozen=True)
class Appointment:
    patient_id: str
    doctor_id: str
    appointment_date: date
    appointment_time: time
    consultation_type: str

    @property
    def starts_at(self) -> datetime:
        return datetime.combine(self.appointment_date, self.appointment_time)


class TelemedicineScheduler:
    VALID_CONSULTATION_TYPES = {"video", "phone"}

    def __init__(self) -> None:
        self.doctors: Dict[str, Doctor] = {}
        self.patients: Dict[str, Patient] = {}
        self.appointments_by_slot: Dict[Tuple[str, date, time], Appointment] = {}
        self.patient_appointments: Dict[str, List[Appointment]] = {}

    @staticmethod
    def _parse_date(value: date | str) -> date:
        if isinstance(value, date):
            return value
        return datetime.strptime(value, "%Y-%m-%d").date()

    @staticmethod
    def _parse_time(value: time | str) -> time:
        if isinstance(value, time):
            return value
        return datetime.strptime(value, "%H:%M").time()

    def register_patient(self, patient_id: str, name: str) -> None:
        if not patient_id or not name:
            raise ValueError("Patient ID and name are required.")
        if patient_id in self.patients:
            raise ValueError(f"Patient '{patient_id}' is already registered.")
        self.patients[patient_id] = Patient(patient_id=patient_id, name=name)
        self.patient_appointments[patient_id] = []

    def add_doctor(
        self,
        doctor_id: str,
        name: str,
        available_schedule: Optional[Dict[date | str, List[time | str]]] = None,
    ) -> None:
        if not doctor_id or not name:
            raise ValueError("Doctor ID and name are required.")
        if doctor_id in self.doctors:
            raise ValueError(f"Doctor '{doctor_id}' already exists.")

        doctor = Doctor(doctor_id=doctor_id, name=name)

        if available_schedule:
            for appointment_date, slots in available_schedule.items():
                parsed_date = self._parse_date(appointment_date)
                parsed_slots = [self._parse_time(slot) for slot in slots]
                doctor.add_available_slots(parsed_date, parsed_slots)

        self.doctors[doctor_id] = doctor

    def add_doctor_availability(
        self,
        doctor_id: str,
        appointment_date: date | str,
        slots: List[time | str],
    ) -> None:
        doctor = self._get_doctor(doctor_id)
        parsed_date = self._parse_date(appointment_date)
        parsed_slots = [self._parse_time(slot) for slot in slots]
        doctor.add_available_slots(parsed_date, parsed_slots)

    def book_appointment(
        self,
        patient_id: str,
        doctor_id: str,
        appointment_date: date | str,
        appointment_time: time | str,
        consultation_type: str,
    ) -> Appointment:
        if patient_id not in self.patients:
            raise ValueError(f"Patient '{patient_id}' is not registered.")

        doctor = self._get_doctor(doctor_id)
        parsed_date = self._parse_date(appointment_date)
        parsed_time = self._parse_time(appointment_time)
        consultation_type = consultation_type.strip().lower()

        if consultation_type not in self.VALID_CONSULTATION_TYPES:
            raise ValueError(
                f"Invalid consultation type. Allowed: {sorted(self.VALID_CONSULTATION_TYPES)}"
            )

        if not doctor.is_slot_available(parsed_date, parsed_time):
            raise ValueError(
                f"Doctor '{doctor_id}' is not available on {parsed_date} at {parsed_time.strftime('%H:%M')}."
            )

        slot_key = (doctor_id, parsed_date, parsed_time)
        if slot_key in self.appointments_by_slot:
            raise ValueError("This time slot is already booked.")

        appointment = Appointment(
            patient_id=patient_id,
            doctor_id=doctor_id,
            appointment_date=parsed_date,
            appointment_time=parsed_time,
            consultation_type=consultation_type,
        )

        self.appointments_by_slot[slot_key] = appointment
        self.patient_appointments[patient_id].append(appointment)
        self.patient_appointments[patient_id].sort(key=lambda a: a.starts_at)

        return appointment

    def cancel_appointment(
        self,
        patient_id: str,
        doctor_id: str,
        appointment_date: date | str,
        appointment_time: time | str,
    ) -> bool:
        parsed_date = self._parse_date(appointment_date)
        parsed_time = self._parse_time(appointment_time)
        slot_key = (doctor_id, parsed_date, parsed_time)

        appointment = self.appointments_by_slot.get(slot_key)
        if appointment is None:
            return False

        if appointment.patient_id != patient_id:
            raise ValueError("Appointment does not belong to the specified patient.")

        del self.appointments_by_slot[slot_key]
        self.patient_appointments[patient_id] = [
            appt
            for appt in self.patient_appointments.get(patient_id, [])
            if not (
                appt.doctor_id == doctor_id
                and appt.appointment_date == parsed_date
                and appt.appointment_time == parsed_time
            )
        ]
        return True

    def get_doctor_daily_schedule(
        self,
        doctor_id: str,
        appointment_date: date | str,
    ) -> List[Dict[str, Optional[str]]]:
        doctor = self._get_doctor(doctor_id)
        parsed_date = self._parse_date(appointment_date)
        slots = sorted(doctor.available_slots.get(parsed_date, set()))

        schedule: List[Dict[str, Optional[str]]] = []
        for slot in slots:
            appointment = self.appointments_by_slot.get((doctor_id, parsed_date, slot))
            schedule.append(
                {
                    "date": parsed_date.isoformat(),
                    "time": slot.strftime("%H:%M"),
                    "status": "booked" if appointment else "available",
                    "patient_id": appointment.patient_id if appointment else None,
                    "consultation_type": appointment.consultation_type if appointment else None,
                }
            )
        return schedule

    def list_upcoming_appointments_for_patient(
        self,
        patient_id: str,
        from_datetime: Optional[datetime] = None,
    ) -> List[Appointment]:
        if patient_id not in self.patients:
            raise ValueError(f"Patient '{patient_id}' is not registered.")

        reference = from_datetime or datetime.now()
        appointments = self.patient_appointments.get(patient_id, [])
        return [appt for appt in appointments if appt.starts_at >= reference]

    def generate_summary_report(self) -> Dict[str, int]:
        report = {doctor_id: 0 for doctor_id in self.doctors}
        for appointment in self.appointments_by_slot.values():
            report[appointment.doctor_id] += 1
        return report

    def _get_doctor(self, doctor_id: str) -> Doctor:
        doctor = self.doctors.get(doctor_id)
        if doctor is None:
            raise ValueError(f"Doctor '{doctor_id}' does not exist.")
        return doctor


if __name__ == "__main__":
    scheduler = TelemedicineScheduler()

    scheduler.register_patient("P001", "Alice Johnson")
    scheduler.register_patient("P002", "Bob Smith")

    scheduler.add_doctor(
        "D001",
        "Dr. Emily Carter",
        {
            "2026-05-01": ["09:00", "09:30", "10:00"],
            "2026-05-02": ["11:00", "11:30"],
        },
    )

    scheduler.add_doctor_availability("D001", "2026-05-01", ["10:30", "11:00"])

    scheduler.book_appointment("P001", "D001", "2026-05-01", "09:00", "video")
    scheduler.book_appointment("P002", "D001", "2026-05-01", "09:30", "phone")

    print(scheduler.get_doctor_daily_schedule("D001", "2026-05-01"))
    print(scheduler.list_upcoming_appointments_for_patient("P001", datetime(2026, 1, 1)))
    print(scheduler.generate_summary_report())

