    job_id: str
    start_time: Optional[float] = None
    end_time: Optional[float] = None
    logs: List[Tuple[float, str, str]] = field(default_factory=list)  # (ts, level, message)
    failure_patterns: Counter = field(default_factory=Counter)
    anomaly_flags: List[str] = field(default_factory=list)

    @property
    def duration(self) -> Optional[float]:
        if self.start_time is not None and self.end_time is not None and self.end_time >= self.start_time:
            return self.end_time - self.start_time
        return None


class PipelineLogMonitor:
    def __init__(
        self,
        pattern_rules: Optional[Dict[str, str]] = None,
        worker_count: int = 4,
        queue_maxsize: int = 10000,
        slow_stage_multiplier: float = 1.75,
        min_samples_for_anomaly: int = 3,
    ):
        self.pattern_rules = {
            "test_failure": r"\b(test(s)? failed|assertionerror|failed:\s+\d+|pytest.*failed)\b",
            "dependency_error": r"\b(npm ERR!|pip failed|could not resolve dependencies|dependency installation failed|no matching distribution found)\b",
            "container_build_problem": r"\b(docker build failed|failed to solve|executor failed running|image build error|buildkit.*error)\b",
            "deployment_timeout": r"\b(deployment timed out|context deadline exceeded|readiness probe failed|rollout status timeout)\b",
        }
        if pattern_rules:
            self.pattern_rules.update(pattern_rules)

        self.compiled_patterns = {
            name: re.compile(pattern, re.IGNORECASE) for name, pattern in self.pattern_rules.items()
        }

        self.worker_count = worker_count
        self.queue: "queue.Queue[LogEvent]" = queue.Queue(maxsize=queue_maxsize)
        self.stop_event = threading.Event()
        self.workers: List[threading.Thread] = []

        self.lock = threading.RLock()

        self.executions: Dict[str, Dict[str, Dict[str, StageExecution]]] = defaultdict(
            lambda: defaultdict(dict)
        )  # pipeline -> stage -> job_id -> StageExecution

        self.pipeline_logs: Dict[str, List[LogEvent]] = defaultdict(list)
        self.failure_counts: Counter = Counter()
        self.stage_durations: Dict[str, List[float]] = defaultdict(list)
        self.agent_job_counts: Counter = Counter()
        self.ingest_exceptions: List[str] = []

        self.slow_stage_multiplier = slow_stage_multiplier
        self.min_samples_for_anomaly = min_samples_for_anomaly

    def start(self) -> None:
        for idx in range(self.worker_count):
            t = threading.Thread(target=self._worker_loop, name=f"log-monitor-worker-{idx}", daemon=True)
            self.workers.append(t)
            t.start()

    def stop(self, timeout: Optional[float] = 5.0) -> None:
        self.stop_event.set()
        for _ in self.workers:
            self.queue.put(LogEvent(time.time(), "", "", "", "", "INFO", "shutdown", event_type="shutdown"))
        for t in self.workers:
            t.join(timeout=timeout)

    def submit_event(self, event: LogEvent, block: bool = True, timeout: Optional[float] = None) -> None:
        self.queue.put(event, block=block, timeout=timeout)

    def _worker_loop(self) -> None:
        while not self.stop_event.is_set() or not self.queue.empty():
            try:
                event = self.queue.get(timeout=0.2)
            except queue.Empty:
                continue

            try:
                if event.event_type == "shutdown":
                    self.queue.task_done()
                    break
                self._process_event(event)
            except Exception as exc:
                with self.lock:
                    self.ingest_exceptions.append(f"{threading.current_thread().name}: {exc!r}")
            finally:
                if event.event_type != "shutdown":
                    self.queue.task_done()

    def _get_or_create_execution(self, event: LogEvent) -> StageExecution:
        stage_map = self.executions[event.pipeline_id][event.stage]
        if event.job_id not in stage_map:
            stage_map[event.job_id] = StageExecution(
                pipeline_id=event.pipeline_id,
                stage=event.stage,
                agent_id=event.agent_id,
                job_id=event.job_id,
            )
        return stage_map[event.job_id]

    def _process_event(self, event: LogEvent) -> None:
        with self.lock:
            self.pipeline_logs[event.pipeline_id].append(event)
            self.agent_job_counts[event.agent_id] += 1 if event.event_type == "stage_start" else 0

            execution = self._get_or_create_execution(event)

            if event.event_type == "stage_start":
                if execution.start_time is None:
                    execution.start_time = event.timestamp
                else:
                    execution.anomaly_flags.append("duplicate_stage_start")

            elif event.event_type == "stage_end":
                if execution.end_time is None:
                    execution.end_time = event.timestamp
                    if execution.duration is not None:
                        self.stage_durations[event.stage].append(execution.duration)
                else:
                    execution.anomaly_flags.append("duplicate_stage_end")

            else:
                execution.logs.append((event.timestamp, event.level, event.message))
                matched = self._match_patterns(event.message)
                if matched:
                    for pattern_name in matched:
                        execution.failure_patterns[pattern_name] += 1
                        self.failure_counts[pattern_name] += 1

    def _match_patterns(self, message: str) -> List[str]:
        matches = []
        for name, pattern in self.compiled_patterns.items():
            if pattern.search(message):
                matches.append(name)
        return matches

    def finalize_anomalies(self) -> None:
        with self.lock:
            stage_baselines = {}
            for stage, durations in self.stage_durations.items():
                if len(durations) >= self.min_samples_for_anomaly:
                    mean_val = statistics.mean(durations)
                    stage_baselines[stage] = mean_val

            for pipeline_id, stage_map in self.executions.items():
                for stage, jobs in stage_map.items():
                    baseline = stage_baselines.get(stage)
                    for job_id, execution in jobs.items():
                        if execution.start_time is None:
                            execution.anomaly_flags.append("missing_stage_start")
                        if execution.end_time is None:
                            execution.anomaly_flags.append("missing_stage_end")
                        if execution.duration is not None and execution.duration < 0:
                            execution.anomaly_flags.append("negative_duration")
                        if baseline is not None and execution.duration is not None:
                            if execution.duration > baseline * self.slow_stage_multiplier:
                                execution.anomaly_flags.append("slow_stage")
                        if sum(execution.failure_patterns.values()) >= 2:
                            execution.anomaly_flags.append("multiple_failure_signals")
                        if len(execution.logs) == 0:
                            execution.anomaly_flags.append("no_logs")

    def generate_summary_report(self, top_n_slowest: int = 5) -> Dict[str, Any]:
        self.finalize_anomalies()
        with self.lock:
            mean_stage_durations = {
                stage: round(statistics.mean(durations), 4) if durations else None
                for stage, durations in self.stage_durations.items()
            }

            slowest_jobs = []
            anomaly_counts = Counter()
            pipeline_failure_summary = defaultdict(Counter)

            for pipeline_id, stage_map in self.executions.items():
                for stage, jobs in stage_map.items():
                    for job_id, execution in jobs.items():
                        if execution.duration is not None:
                            slowest_jobs.append(
                                {
                                    "pipeline_id": pipeline_id,
                                    "stage": stage,
                                    "job_id": job_id,
                                    "agent_id": execution.agent_id,
                                    "duration": round(execution.duration, 4),
                                }
                            )
                        for failure_name, count in execution.failure_patterns.items():
                            pipeline_failure_summary[pipeline_id][failure_name] += count
                        for flag in execution.anomaly_flags:
                            anomaly_counts[flag] += 1

            slowest_jobs.sort(key=lambda x: x["duration"], reverse=True)

            pipelines = {}
            for pipeline_id, stage_map in self.executions.items():
                stage_info = {}
                for stage, jobs in stage_map.items():
                    stage_info[stage] = {
                        "jobs": len(jobs),
                        "completed_jobs": sum(1 for e in jobs.values() if e.duration is not None),
                        "mean_duration": round(
                            statistics.mean([e.duration for e in jobs.values() if e.duration is not None]), 4
                        ) if any(e.duration is not None for e in jobs.values()) else None,
                        "failure_counts": dict(sum((e.failure_patterns for e in jobs.values()), Counter())),
                        "anomaly_flags": dict(sum((Counter(e.anomaly_flags) for e in jobs.values()), Counter())),
                    }
                pipelines[pipeline_id] = {
                    "stages": stage_info,
                    "failure_counts": dict(pipeline_failure_summary[pipeline_id]),
                    "total_logs": len(self.pipeline_logs[pipeline_id]),
                }

            return {
                "global_failure_counts": dict(self.failure_counts),
                "mean_stage_durations": mean_stage_durations,
                "slowest_jobs": slowest_jobs[:top_n_slowest],
                "anomaly_counts": dict(anomaly_counts),
                "pipelines": pipelines,
                "ingest_exceptions": list(self.ingest_exceptions),
                "agents_seen": dict(self.agent_job_counts),
            }


def simulate_agent(
    agent_id: str,
    monitor: PipelineLogMonitor,
    pipelines: List[str],
    stages: List[str],
    jobs_per_pipeline: int,
    seed: int,
) -> None:
    rng = random.Random(seed)
    failure_messages = {
        "test_failure": [
            "Pytest run complete: tests failed: 3",
            "AssertionError in integration suite",
            "tests failed due to flaky endpoint",
        ],
        "dependency_error": [
            "npm ERR! dependency installation failed",
            "pip failed: no matching distribution found",
            "could not resolve dependencies for lockfile",
        ],
        "container_build_problem": [
            "docker build failed with exit code 1",
            "failed to solve with frontend dockerfile.v0",
            "executor failed running [/bin/sh -c make build]",
        ],
        "deployment_timeout": [
            "deployment timed out waiting for service",
            "context deadline exceeded during rollout",
            "rollout status timeout after 300s",
        ],
    }

    normal_messages = [
        "Fetching source code",
        "Installing dependencies",
        "Running unit tests",
        "Building container image",
        "Pushing artifacts",
        "Deploying application",
        "Health checks passed",
        "Stage completed successfully",
    ]

    for pipeline_id in pipelines:
        for job_num in range(jobs_per_pipeline):
            job_id = f"{pipeline_id}-job-{agent_id}-{job_num}"
            for stage in stages:
                start_ts = time.time()
                monitor.submit_event(
                    LogEvent(
                        timestamp=start_ts,
                        pipeline_id=pipeline_id,
                        stage=stage,
                        agent_id=agent_id,
                        job_id=job_id,
                        level="INFO",
                        message=f"Stage {stage} started",
                        event_type="stage_start",
                    )
                )

                for _ in range(rng.randint(3, 8)):
                    time.sleep(rng.uniform(0.005, 0.03))
                    if rng.random() < 0.18:
                        category = rng.choice(list(failure_messages.keys()))
                        message = rng.choice(failure_messages[category])
                        level = "ERROR"
                    else:
                        message = rng.choice(normal_messages)
                        level = rng.choice(["INFO", "DEBUG", "WARN"])

                    monitor.submit_event(
                        LogEvent(
                            timestamp=time.time(),
                            pipeline_id=pipeline_id,
                            stage=stage,
                            agent_id=agent_id,
                            job_id=job_id,
                            level=level,
                            message=message,
                            event_type="log",
                        )
                    )

                if rng.random() < 0.03:
                    continue

                time.sleep(rng.uniform(0.01, 0.05))
                monitor.submit_event(
                    LogEvent(
                        timestamp=time.time(),
                        pipeline_id=pipeline_id,
                        stage=stage,
                        agent_id=agent_id,
                        job_id=job_id,
                        level="INFO",
                        message=f"Stage {stage} ended",
                        event_type="stage_end",
                    )
                )


def main() -> None:
    monitor = PipelineLogMonitor(worker_count=6)
    monitor.start()

    pipelines = ["pipeline-A", "pipeline-B", "pipeline-C"]
    stages = ["checkout", "build", "test", "package", "deploy"]
    producer_threads = []

    agent_ids = [f"agent-{i}" for i in range(5)]
    for idx, agent_id in enumerate(agent_ids):
        t = threading.Thread(
            target=simulate_agent,
            args=(agent_id, monitor, pipelines, stages, 3, 100 + idx),
            name=f"producer-{agent_id}",
            daemon=True,
        )
        producer_threads.append(t)
        t.start()

    for t in producer_threads:
        t.join()

    monitor.queue.join()
    monitor.stop()

    report = monitor.generate_summary_report(top_n_slowest=10)

    import json
    print(json.dumps(report, indent=2, sort_keys=True))


if __name__ == "__main__":
    main()

from dataclasses import dataclass
from typing import List, Dict, Any


@dataclass
class Transaction:
    date: str          # Format: YYYY-MM-DD
    category: str
    amount: float
    type: str          # "income" or "expense"


def generate_monthly_summary(transactions: List[Transaction], target_month: str) -> Dict[str, Any]:
    summary = {
        "total_income": 0.0,
        "total_expenses": 0.0,
        "net_savings": 0.0,
        "expense_breakdown": {}
    }

    for transaction in transactions:
        if not transaction.date.startswith(target_month):
            continue

        if transaction.type == "income":
            summary["total_income"] += transaction.amount
        elif transaction.type == "expense":
            summary["total_expenses"] += transaction.amount
            if transaction.category in summary["expense_breakdown"]:
                summary["expense_breakdown"][transaction.category] += transaction.amount
            else:
                summary["expense_breakdown"][transaction.category] = transaction.amount

    summary["net_savings"] = summary["total_income"] - summary["total_expenses"]
    return summary


if __name__ == "__main__":
    transactions = [
        Transaction("2025-05-01", "Salary", 3000.0, "income"),
        Transaction("2025-05-03", "Groceries", 120.5, "expense"),
        Transaction("2025-05-05", "Rent", 1000.0, "expense"),
        Transaction("2025-05-10", "Transport", 60.0, "expense"),
        Transaction("2025-04-28", "Groceries", 80.0, "expense"),
    ]

    result = generate_monthly_summary(transactions, "2025-05")
    print(result)

from __future__ import annotations

from dataclasses import dataclass, field
from statistics import mean
from typing import Any, Dict, List, Sequence, Tuple


@dataclass
class PatientRecord:
    """
    Represents a patient's recent vital sign readings.

    Attributes:
        patient_id: Unique identifier for the patient.
        age: Patient age in years.
        heart_rate_readings: Recent heart rate readings in beats per minute.
        systolic_bp_readings: Recent systolic blood pressure readings in mmHg.
        diastolic_bp_readings: Recent diastolic blood pressure readings in mmHg.
        temperature_readings: Recent body temperature readings in Celsius.
        blood_oxygen_readings: Recent blood oxygen saturation readings in percent.
    """

    patient_id: str
    age: int
    heart_rate_readings: List[float] = field(default_factory=list)
    systolic_bp_readings: List[float] = field(default_factory=list)
    diastolic_bp_readings: List[float] = field(default_factory=list)
    temperature_readings: List[float] = field(default_factory=list)
    blood_oxygen_readings: List[float] = field(default_factory=list)

    def __post_init__(self) -> None:
        self._validate()

    def _validate(self) -> None:
        """Validate patient record fields and reading ranges."""
        if not isinstance(self.patient_id, str) or not self.patient_id.strip():
            raise ValueError("patient_id must be a non-empty string.")

        if not isinstance(self.age, int) or self.age <= 0 or self.age > 130:
            raise ValueError("age must be an integer between 1 and 130.")

        reading_groups = {
            "heart_rate_readings": self.heart_rate_readings,
            "systolic_bp_readings": self.systolic_bp_readings,
            "diastolic_bp_readings": self.diastolic_bp_readings,
            "temperature_readings": self.temperature_readings,
            "blood_oxygen_readings": self.blood_oxygen_readings,
        }

        for name, readings in reading_groups.items():
            if not isinstance(readings, list) or len(readings) < 2:
                raise ValueError(f"{name} must be a list with at least 2 numeric readings.")
            if not all(isinstance(value, (int, float)) for value in readings):
                raise ValueError(f"All values in {name} must be numeric.")

        if not (
            len(self.heart_rate_readings)
            == len(self.systolic_bp_readings)
            == len(self.diastolic_bp_readings)
            == len(self.temperature_readings)
            == len(self.blood_oxygen_readings)
        ):
            raise ValueError("All reading lists must have the same length.")

        self._validate_ranges()

    def _validate_ranges(self) -> None:
        """Validate realistic physiological ranges for readings."""
        for hr in self.heart_rate_readings:
            if hr < 20 or hr > 250:
                raise ValueError("Heart rate readings must be between 20 and 250 bpm.")

        for sbp in self.systolic_bp_readings:
            if sbp < 50 or sbp > 300:
                raise ValueError("Systolic blood pressure readings must be between 50 and 300 mmHg.")

        for dbp in self.diastolic_bp_readings:
            if dbp < 30 or dbp > 200:
                raise ValueError("Diastolic blood pressure readings must be between 30 and 200 mmHg.")

        for temp in self.temperature_readings:
            if temp < 30.0 or temp > 45.0:
                raise ValueError("Temperature readings must be between 30.0 and 45.0 °C.")

        for spo2 in self.blood_oxygen_readings:
            if spo2 < 50 or spo2 > 100:
                raise ValueError("Blood oxygen readings must be between 50 and 100 percent.")

    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> "PatientRecord":
        """
        Create a PatientRecord from a structured dictionary.

        Expected keys:
            patient_id, age, heart_rate_readings, systolic_bp_readings,
            diastolic_bp_readings, temperature_readings, blood_oxygen_readings
        """
        required_keys = {
            "patient_id",
            "age",
            "heart_rate_readings",
            "systolic_bp_readings",
            "diastolic_bp_readings",
            "temperature_readings",
            "blood_oxygen_readings",
        }
        missing = required_keys - data.keys()
        if missing:
            raise ValueError(f"Missing required patient data fields: {sorted(missing)}")

        return cls(
            patient_id=str(data["patient_id"]),
            age=int(data["age"]),
            heart_rate_readings=list(data["heart_rate_readings"]),
            systolic_bp_readings=list(data["systolic_bp_readings"]),
            diastolic_bp_readings=list(data["diastolic_bp_readings"]),
            temperature_readings=list(data["temperature_readings"]),
            blood_oxygen_readings=list(data["blood_oxygen_readings"]),
        )


class DiagnosticAnalyzer:
    """
    Rule-based analyzer for identifying early-warning conditions from recent vital signs.
    """

    def analyze_patient(self, patient: PatientRecord) -> Dict[str, Any]:
        """
        Analyze a patient's recent vital sign trends and return a diagnostic summary.

        Args:
            patient: A validated PatientRecord instance.

        Returns:
            A dictionary containing:
                - patient_id
                - detected_conditions
                - severity_score
                - recommended_follow_up_action
        """
        conditions: List[str] = []
        severity_score = 0

        hr_condition, hr_score = self._analyze_heart_rate(patient.heart_rate_readings, patient.age)
        bp_condition, bp_score = self._analyze_blood_pressure(
            patient.systolic_bp_readings,
            patient.diastolic_bp_readings,
        )
        temp_condition, temp_score = self._analyze_temperature(patient.temperature_readings)
        spo2_condition, spo2_score = self._analyze_blood_oxygen(patient.blood_oxygen_readings)

        for condition in (hr_condition, bp_condition, temp_condition, spo2_condition):
            if condition:
                if isinstance(condition, list):
                    conditions.extend(condition)
                else:
                    conditions.append(condition)

        severity_score += hr_score + bp_score + temp_score + spo2_score
        severity_score = min(severity_score, 10)

        follow_up = self._recommend_follow_up(conditions, severity_score)

        return {
            "patient_id": patient.patient_id,
            "detected_conditions": conditions,
            "severity_score": severity_score,
            "recommended_follow_up_action": follow_up,
        }

    def _analyze_heart_rate(self, readings: Sequence[float], age: int) -> Tuple[List[str], int]:
        """Analyze heart rate trend for tachycardia or bradycardia."""
        conditions: List[str] = []
        score = 0

        avg_hr = mean(readings)
        recent_hr = readings[-2:]
        increasing = self._is_increasing_trend(readings)
        decreasing = self._is_decreasing_trend(readings)

        tachy_threshold = 100 if age >= 18 else 110
        brady_threshold = 60 if age >= 18 else 50

        if avg_hr >= tachy_threshold and sum(hr >= tachy_threshold for hr in recent_hr) >= 2:
            conditions.append("tachycardia")
            score += 2
            if increasing or avg_hr >= 120:
                score += 1

        if avg_hr <= brady_threshold and sum(hr <= brady_threshold for hr in recent_hr) >= 2:
            conditions.append("bradycardia")
            score += 2
            if decreasing or avg_hr <= 50:
                score += 1

        return conditions, score

    def _analyze_blood_pressure(
        self,
        systolic_readings: Sequence[float],
        diastolic_readings: Sequence[float],
    ) -> Tuple[List[str], int]:
        """Analyze blood pressure trend for hypertension or hypotension."""
        conditions: List[str] = []
        score = 0

        avg_sbp = mean(systolic_readings)
        avg_dbp = mean(diastolic_readings)
        recent_pairs = list(zip(systolic_readings[-2:], diastolic_readings[-2:]))

        hypertensive_recent = sum(s >= 140 or d >= 90 for s, d in recent_pairs)
        hypotensive_recent = sum(s < 90 or d < 60 for s, d in recent_pairs)

        if avg_sbp >= 140 or avg_dbp >= 90:
            if hypertensive_recent >= 2 or self._is_increasing_trend(systolic_readings):
                conditions.append("hypertension")
                score += 2
                if avg_sbp >= 160 or avg_dbp >= 100:
                    score += 1

        if avg_sbp < 90 or avg_dbp < 60:
            if hypotensive_recent >= 2 or self._is_decreasing_trend(systolic_readings):
                conditions.append("hypotension")
                score += 2
                if avg_sbp < 80 or avg_dbp < 50:
                    score += 1

        return conditions, score

    def _analyze_temperature(self, readings: Sequence[float]) -> Tuple[List[str], int]:
        """Analyze temperature trend for fever."""
        conditions: List[str] = []
        score = 0

        avg_temp = mean(readings)
        recent_temp = readings[-2:]

        if avg_temp >= 38.0 and sum(t >= 38.0 for t in recent_temp) >= 2:
            conditions.append("fever")
            score += 2
            if self._is_increasing_trend(readings) or avg_temp >= 39.0:
                score += 1

        return conditions, score

    def _analyze_blood_oxygen(self, readings: Sequence[float]) -> Tuple[List[str], int]:
        """Analyze oxygen saturation trend for hypoxia."""
        conditions: List[str] = []
        score = 0

        avg_spo2 = mean(readings)
        recent_spo2 = readings[-2:]

        if avg_spo2 < 92 and sum(v < 92 for v in recent_spo2) >= 2:
            conditions.append("hypoxia")
            score += 3
            if self._is_decreasing_trend(readings) or avg_spo2 < 88:
                score += 1

        return conditions, score

    @staticmethod
    def _is_increasing_trend(readings: Sequence[float]) -> bool:
        """Return True if readings show a meaningful upward trend."""
        return readings[-1] > readings[0] and mean(readings[-2:]) > mean(readings[:2])

    @staticmethod
    def _is_decreasing_trend(readings: Sequence[float]) -> bool:
        """Return True if readings show a meaningful downward trend."""
        return readings[-1] < readings[0] and mean(readings[-2:]) < mean(readings[:2])

    @staticmethod
    def _recommend_follow_up(conditions: Sequence[str], severity_score: int) -> str:
        """Generate a recommended follow-up action based on findings."""
        high_risk_conditions = {"hypoxia", "hypotension", "tachycardia", "bradycardia"}

        if severity_score >= 8 or ("hypoxia" in conditions and len(conditions) >= 2):
            return "Urgent clinical evaluation recommended immediately."
        if severity_score >= 5 or any(cond in high_risk_conditions for cond in conditions):
            return "Schedule same-day medical review and continue close monitoring."
        if severity_score >= 2:
            return "Arrange routine clinician follow-up and repeat vital signs monitoring."
        return "No immediate warning signs detected; continue standard monitoring."


if __name__ == "__main__":
    example_data = {
        "patient_id": "P-10027",
        "age": 67,
        "heart_rate_readings": [96, 101, 108, 112],
        "systolic_bp_readings": [138, 142, 148, 152],
        "diastolic_bp_readings": [86, 89, 92, 95],
