from __future__ import annotations

from dataclasses import dataclass
from datetime import date, datetime, time
from typing import Any, Dict, Iterable, List, Optional, Tuple


VALID_STATUSES = {"completed", "cancelled", "no_show"}


class AppointmentValidationError(ValueError):
    pass


def _parse_date(value: Any) -> date:
    if isinstance(value, date) and not isinstance(value, datetime):
        return value
    if isinstance(value, datetime):
        return value.date()
    if isinstance(value, str):
        for fmt in ("%Y-%m-%d", "%m/%d/%Y", "%Y/%m/%d"):
            try:
                return datetime.strptime(value, fmt).date()
            except ValueError:
                continue
    raise AppointmentValidationError(f"Invalid appointment_date: {value!r}")


def _parse_time(value: Any) -> time:
    if isinstance(value, time):
        return value
    if isinstance(value, datetime):
        return value.time()
    if isinstance(value, str):
        for fmt in ("%H:%M", "%H:%M:%S", "%I:%M %p", "%I:%M:%S %p"):
            try:
                return datetime.strptime(value, fmt).time()
            except ValueError:
                continue
    raise AppointmentValidationError(f"Invalid time value: {value!r}")


def _minutes_between(start: time, end: time) -> int:
    start_dt = datetime.combine(date.today(), start)
    end_dt = datetime.combine(date.today(), end)
    minutes = int((end_dt - start_dt).total_seconds() // 60)
    if minutes <= 0:
        raise AppointmentValidationError("end_time must be later than start_time")
    return minutes


@dataclass(frozen=True)
class Appointment:
    patient_id: str
    provider_id: str
    appointment_date: date
    start_time: time
    end_time: time
    status: str
    appointment_type: str

    @classmethod
    def from_record(cls, record: Dict[str, Any]) -> "Appointment":
        required_fields = {
            "patient_id",
            "provider_id",
            "appointment_date",
            "start_time",
            "end_time",
            "status",
            "appointment_type",
        }
        missing = [field for field in required_fields if field not in record or record[field] in (None, "")]
        if missing:
            raise AppointmentValidationError(f"Missing required fields: {', '.join(sorted(missing))}")

        status = str(record["status"]).strip().lower()
        if status not in VALID_STATUSES:
            raise AppointmentValidationError(f"Invalid status: {record['status']!r}")

        appointment_date = _parse_date(record["appointment_date"])
        start_time = _parse_time(record["start_time"])
        end_time = _parse_time(record["end_time"])
        _minutes_between(start_time, end_time)

        return cls(
            patient_id=str(record["patient_id"]),
            provider_id=str(record["provider_id"]),
            appointment_date=appointment_date,
            start_time=start_time,
            end_time=end_time,
            status=status,
            appointment_type=str(record["appointment_type"]),
        )

    @property
    def duration_minutes(self) -> int:
        return _minutes_between(self.start_time, self.end_time)

    @property
    def interval(self) -> Tuple[time, time]:
        return self.start_time, self.end_time


class ProviderSchedule:
    def __init__(self, provider_id: str, report_date: date, available_hours: float = 8.0) -> None:
        if available_hours <= 0:
            raise ValueError("available_hours must be greater than 0")
        self.provider_id = provider_id
        self.report_date = report_date
        self.available_hours = float(available_hours)
        self._appointments: List[Appointment] = []

    def add_appointment(self, appointment: Appointment) -> None:
        if appointment.provider_id != self.provider_id:
            raise ValueError("Appointment provider_id does not match schedule provider_id")
        if appointment.appointment_date != self.report_date:
            raise ValueError("Appointment date does not match schedule report_date")
        self._appointments.append(appointment)

    @property
    def appointments(self) -> List[Appointment]:
        return list(self._appointments)

    def _merged_completed_minutes(self) -> int:
        completed = [
            appt for appt in self._appointments
            if appt.status == "completed"
        ]
        if not completed:
            return 0

        intervals: List[Tuple[datetime, datetime]] = []
        for appt in completed:
            start_dt = datetime.combine(self.report_date, appt.start_time)
            end_dt = datetime.combine(self.report_date, appt.end_time)
            intervals.append((start_dt, end_dt))

        intervals.sort(key=lambda x: x[0])

        merged: List[Tuple[datetime, datetime]] = []
        current_start, current_end = intervals[0]

        for start_dt, end_dt in intervals[1:]:
            if start_dt <= current_end:
                if end_dt > current_end:
                    current_end = end_dt
            else:
                merged.append((current_start, current_end))
                current_start, current_end = start_dt, end_dt

        merged.append((current_start, current_end))

        total_minutes = 0
        for start_dt, end_dt in merged:
            total_minutes += int((end_dt - start_dt).total_seconds() // 60)
        return total_minutes

    def generate_report(self) -> Dict[str, Any]:
        total_scheduled = len(self._appointments)
        completed_visits = sum(1 for appt in self._appointments if appt.status == "completed")
        cancellations = sum(1 for appt in self._appointments if appt.status == "cancelled")
        no_shows = sum(1 for appt in self._appointments if appt.status == "no_show")
        total_booked_minutes = self._merged_completed_minutes()
        available_minutes = int(self.available_hours * 60)
        utilization_percentage = round((total_booked_minutes / available_minutes) * 100, 2) if available_minutes else 0.0

        return {
            "provider_id": self.provider_id,
            "appointment_date": self.report_date.isoformat(),
            "total_scheduled_appointments": total_scheduled,
            "completed_visits": completed_visits,
            "cancellations": cancellations,
            "no_shows": no_shows,
            "total_booked_minutes": total_booked_minutes,
            "available_clinic_hours": self.available_hours,
            "utilization_percentage": utilization_percentage,
        }


def generate_daily_provider_utilization_report(
    appointment_records: Iterable[Dict[str, Any]],
    report_date: Any,
    available_clinic_hours: float = 8.0,
    include_errors: bool = False,
) -> Dict[str, Any]:
    target_date = _parse_date(report_date)
    schedules: Dict[str, ProviderSchedule] = {}
    errors: List[Dict[str, Any]] = []

    for index, record in enumerate(appointment_records):
        try:
            appointment = Appointment.from_record(record)
            if appointment.appointment_date != target_date:
                continue

            if appointment.provider_id not in schedules:
                schedules[appointment.provider_id] = ProviderSchedule(
                    provider_id=appointment.provider_id,
                    report_date=target_date,
                    available_hours=available_clinic_hours,
                )

            schedules[appointment.provider_id].add_appointment(appointment)

        except (AppointmentValidationError, ValueError, TypeError) as exc:
            if include_errors:
                errors.append(
                    {
                        "record_index": index,
                        "error": str(exc),
                        "record": record,
                    }
                )

    reports = [
        schedules[provider_id].generate_report()
        for provider_id in sorted(schedules.keys())
    ]

    result: Dict[str, Any] = {
        "report_date": target_date.isoformat(),
        "providers": reports,
    }

    if include_errors:
        result["errors"] = errors

    return result

from typing import Any, Dict, List


def top_failing_stages(stages: List[Dict[str, Any]], n: int) -> List[Dict[str, Any]]:
    """Return the top n CI/CD pipeline stages sorted by failure rate, failed runs, and stage name."""
    if not isinstance(stages, list):
        raise TypeError("stages must be a list of dictionaries")
    if not isinstance(n, int):
        raise TypeError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non-negative")

    required_keys = {"stage_name", "total_runs", "failed_runs"}
    processed: List[Dict[str, Any]] = []

    for index, stage in enumerate(stages):
        if not isinstance(stage, dict):
            raise TypeError(f"Each item in stages must be a dictionary; item at index {index} is invalid")
        if not required_keys.issubset(stage.keys()):
            missing = required_keys - set(stage.keys())
            raise ValueError(f"Stage at index {index} is missing required keys: {sorted(missing)}")

        stage_name = stage["stage_name"]
        total_runs = stage["total_runs"]
        failed_runs = stage["failed_runs"]

        if not isinstance(stage_name, str):
            raise TypeError(f"stage_name at index {index} must be a string")
        if not isinstance(total_runs, int) or isinstance(total_runs, bool):
            raise TypeError(f"total_runs at index {index} must be an integer")
        if not isinstance(failed_runs, int) or isinstance(failed_runs, bool):
            raise TypeError(f"failed_runs at index {index} must be an integer")
        if total_runs < 0:
            raise ValueError(f"total_runs at index {index} must be non-negative")
        if failed_runs < 0:
            raise ValueError(f"failed_runs at index {index} must be non-negative")

        failure_rate = (failed_runs / total_runs) if total_runs > 0 else 0.0

        processed.append(
            {
                "stage_name": stage_name,
                "failure_rate": failure_rate,
                "failed_runs": failed_runs,
            }
        )

    sorted_stages = sorted(
        processed,
        key=lambda x: (-x["failure_rate"], -x["failed_runs"], x["stage_name"]),
    )

    return sorted_stages[:n]


if __name__ == "__main__":
    sample_stages = [
        {"stage_name": "build", "total_runs": 100, "failed_runs": 10},
        {"stage_name": "test", "total_runs": 80, "failed_runs": 20},
        {"stage_name": "deploy", "total_runs": 50, "failed_runs": 5},
        {"stage_name": "lint", "total_runs": 0, "failed_runs": 0},
        {"stage_name": "security_scan", "total_runs": 40, "failed_runs": 10},
        {"stage_name": "integration", "total_runs": 80, "failed_runs": 20},
    ]

    result = top_failing_stages(sample_stages, 3)
    print(result)

