from datetime import datetime
from enum import Enum
from typing import Generator, List, Optional

from fastapi import APIRouter, Depends, FastAPI, HTTPException, Query, Request, status
from fastapi.exceptions import RequestValidationError
from fastapi.responses import JSONResponse
from pydantic import BaseModel, ConfigDict, Field, field_validator
from sqlalchemy import DateTime, String, create_engine, func, select
from sqlalchemy.orm import DeclarativeBase, Mapped, Session, mapped_column, sessionmaker

# -----------------------------------------------------------------------------
# Database setup
# -----------------------------------------------------------------------------

DATABASE_URL = "sqlite:///./deployments.db"

engine = create_engine(DATABASE_URL, connect_args={"check_same_thread": False})
SessionLocal = sessionmaker(bind=engine, autoflush=False, autocommit=False)


class Base(DeclarativeBase):
    pass


# -----------------------------------------------------------------------------
# Models
# -----------------------------------------------------------------------------

class EnvironmentEnum(str, Enum):
    development = "development"
    staging = "staging"
    production = "production"


class DeploymentStatusEnum(str, Enum):
    pending = "pending"
    active = "active"
    inactive = "inactive"
    failed = "failed"
    retired = "retired"


class Deployment(Base):
    __tablename__ = "deployments"

    deployment_id: Mapped[str] = mapped_column(String(64), primary_key=True, index=True)
    model_name: Mapped[str] = mapped_column(String(255), index=True, nullable=False)
    model_version: Mapped[str] = mapped_column(String(100), nullable=False)
    environment: Mapped[str] = mapped_column(String(50), index=True, nullable=False)
    status: Mapped[str] = mapped_column(String(50), index=True, nullable=False, default=DeploymentStatusEnum.pending.value)
    created_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), nullable=False, server_default=func.now())
    updated_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True), nullable=False, server_default=func.now(), onupdate=func.now()
    )


# -----------------------------------------------------------------------------
# Schemas
# -----------------------------------------------------------------------------

class ErrorResponse(BaseModel):
    detail: str
    error_code: str
    fields: Optional[List[dict]] = None


class DeploymentBase(BaseModel):
    model_name: str = Field(..., min_length=1, max_length=255, examples=["fraud-detector"])
    model_version: str = Field(..., min_length=1, max_length=100, examples=["1.0.0"])
    environment: EnvironmentEnum
    status: DeploymentStatusEnum = DeploymentStatusEnum.pending

    @field_validator("model_name", "model_version")
    @classmethod
    def strip_non_empty(cls, value: str) -> str:
        value = value.strip()
        if not value:
            raise ValueError("must not be empty")
        return value


class DeploymentCreate(DeploymentBase):
    deployment_id: str = Field(..., min_length=1, max_length=64, examples=["dep_001"])

    @field_validator("deployment_id")
    @classmethod
    def validate_deployment_id(cls, value: str) -> str:
        value = value.strip()
        if not value:
            raise ValueError("must not be empty")
        return value


class DeploymentUpdate(BaseModel):
    model_name: Optional[str] = Field(None, min_length=1, max_length=255)
    model_version: Optional[str] = Field(None, min_length=1, max_length=100)
    environment: Optional[EnvironmentEnum] = None
    status: Optional[DeploymentStatusEnum] = None

    @field_validator("model_name", "model_version")
    @classmethod
    def strip_optional_non_empty(cls, value: Optional[str]) -> Optional[str]:
        if value is None:
            return value
        value = value.strip()
        if not value:
            raise ValueError("must not be empty")
        return value


class DeploymentRead(BaseModel):
    model_config = ConfigDict(from_attributes=True)

    deployment_id: str
    model_name: str
    model_version: str
    environment: EnvironmentEnum
    status: DeploymentStatusEnum
    created_at: datetime
    updated_at: datetime


# -----------------------------------------------------------------------------
# Dependencies
# -----------------------------------------------------------------------------

def get_db() -> Generator[Session, None, None]:
    db = SessionLocal()
    try:
        yield db
    finally:
        db.close()


# -----------------------------------------------------------------------------
# Services
# -----------------------------------------------------------------------------

class DeploymentService:
    @staticmethod
    def _ensure_no_duplicate_active(
        db: Session,
        *,
        deployment_id_to_exclude: Optional[str],
        model_name: str,
        model_version: str,
        environment: str,
        status_value: str,
    ) -> None:
        # Prevent duplicate active deployment for same model/version/environment
        if status_value != DeploymentStatusEnum.active.value:
            return

        stmt = select(Deployment).where(
            Deployment.model_name == model_name,
            Deployment.model_version == model_version,
            Deployment.environment == environment,
            Deployment.status == DeploymentStatusEnum.active.value,
        )
        if deployment_id_to_exclude:
            stmt = stmt.where(Deployment.deployment_id != deployment_id_to_exclude)

        existing = db.execute(stmt).scalar_one_or_none()
        if existing:
            raise HTTPException(
                status_code=status.HTTP_409_CONFLICT,
                detail={
                    "detail": "An active deployment for this model version already exists in the target environment.",
                    "error_code": "DUPLICATE_ACTIVE_DEPLOYMENT",
                },
            )

    @staticmethod
    def create_deployment(db: Session, payload: DeploymentCreate) -> Deployment:
        existing = db.get(Deployment, payload.deployment_id)
        if existing:
            raise HTTPException(
                status_code=status.HTTP_409_CONFLICT,
                detail={
                    "detail": f"Deployment '{payload.deployment_id}' already exists.",
                    "error_code": "DEPLOYMENT_ALREADY_EXISTS",
                },
            )

        DeploymentService._ensure_no_duplicate_active(
            db,
            deployment_id_to_exclude=None,
            model_name=payload.model_name,
            model_version=payload.model_version,
            environment=payload.environment.value,
            status_value=payload.status.value,
        )

        deployment = Deployment(
            deployment_id=payload.deployment_id,
            model_name=payload.model_name,
            model_version=payload.model_version,
            environment=payload.environment.value,
            status=payload.status.value,
        )
        db.add(deployment)
        db.commit()
        db.refresh(deployment)
        return deployment

    @staticmethod
    def list_deployments(
        db: Session,
        environment: Optional[EnvironmentEnum] = None,
        status_filter: Optional[DeploymentStatusEnum] = None,
    ) -> List[Deployment]:
        stmt = select(Deployment)
        if environment:
            stmt = stmt.where(Deployment.environment == environment.value)
        if status_filter:
            stmt = stmt.where(Deployment.status == status_filter.value)
        stmt = stmt.order_by(Deployment.created_at.desc())
        return list(db.execute(stmt).scalars().all())

    @staticmethod
    def get_deployment(db: Session, deployment_id: str) -> Deployment:
        deployment = db.get(Deployment, deployment_id)
        if not deployment:
            raise HTTPException(
                status_code=status.HTTP_404_NOT_FOUND,
                detail={
                    "detail": f"Deployment '{deployment_id}' not found.",
                    "error_code": "DEPLOYMENT_NOT_FOUND",
                },
            )
        return deployment

    @staticmethod
    def update_deployment(db: Session, deployment_id: str, payload: DeploymentUpdate) -> Deployment:
        deployment = DeploymentService.get_deployment(db, deployment_id)

        new_model_name = payload.model_name if payload.model_name is not None else deployment.model_name
        new_model_version = payload.model_version if payload.model_version is not None else deployment.model_version
        new_environment = payload.environment.value if payload.environment is not None else deployment.environment
        new_status = payload.status.value if payload.status is not None else deployment.status

        DeploymentService._ensure_no_duplicate_active(
            db,
            deployment_id_to_exclude=deployment_id,
            model_name=new_model_name,
            model_version=new_model_version,
            environment=new_environment,
            status_value=new_status,
        )

        if payload.model_name is not None:
            deployment.model_name = payload.model_name
        if payload.model_version is not None:
            deployment.model_version = payload.model_version
        if payload.environment is not None:
            deployment.environment = payload.environment.value
        if payload.status is not None:
            deployment.status = payload.status.value

        deployment.updated_at = datetime.utcnow()
        db.commit()
        db.refresh(deployment)
        return deployment

    @staticmethod
    def delete_deployment(db: Session, deployment_id: str) -> None:
        deployment = DeploymentService.get_deployment(db, deployment_id)
        db.delete(deployment)
        db.commit()


# -----------------------------------------------------------------------------
# Routers
# -----------------------------------------------------------------------------

router = APIRouter(prefix="/deployments", tags=["deployments"])


@router.post(
    "",
    response_model=DeploymentRead,
    status_code=status.HTTP_201_CREATED,
    responses={
        409: {"model": ErrorResponse},
        422: {"model": ErrorResponse},
    },
)
def create_deployment(payload: DeploymentCreate, db: Session = Depends(get_db)) -> Deployment:
    return DeploymentService.create_deployment(db, payload)


@router.get(
    "",
    response_model=List[DeploymentRead],
    responses={422: {"model": ErrorResponse}},
)
def list_deployments(
    environment: Optional[EnvironmentEnum] = Query(None),
    status_filter: Optional[DeploymentStatusEnum] = Query(None, alias="status"),
    db: Session = Depends(get_db),
) -> List[Deployment]:
    return DeploymentService.list_deployments(db, environment, status_filter)


@router.get(
    "/{deployment_id}",
    response_model=DeploymentRead,
    responses={404: {"model": ErrorResponse}},
)
def get_deployment(deployment_id: str, db: Session = Depends(get_db)) -> Deployment:
    return DeploymentService.get_deployment(db, deployment_id)


@router.put(
    "/{deployment_id}",
    response_model=DeploymentRead,
    responses={
        404: {"model": ErrorResponse},
        409: {"model": ErrorResponse},
        422: {"model": ErrorResponse},
    },
)
def update_deployment(
    deployment_id: str,
    payload: DeploymentUpdate,
    db: Session = Depends(get_db),
) -> Deployment:
    return DeploymentService.update_deployment(db, deployment_id, payload)


@router.delete(
    "/{deployment_id}",
    status_code=status.HTTP_204_NO_CONTENT,
    responses={404: {"model": ErrorResponse}},
)
def delete_deployment(deployment_id: str, db: Session = Depends(get_db)) -> JSONResponse:
    DeploymentService.delete_deployment(db, deployment_id)
    return JSONResponse(status_code=status.HTTP_204_NO_CONTENT, content=None)


