class EHRSystem:
    def create_medication_summary(self, patient_id, medications):
        if not isinstance(patient_id, str) or not patient_id.strip():
            return "Error: Patient ID cannot be empty."

        if not isinstance(medications, list) or len(medications) == 0:
            return "Error: Medication list cannot be empty."

        cleaned_medications = []
        for medication in medications:
            if isinstance(medication, str) and medication.strip():
                cleaned_medications.append(medication.strip())

        if len(cleaned_medications) == 0:
            return "Error: Medication list must contain at least one valid medication name."

        sorted_medications = sorted(cleaned_medications, key=str.lower)

        summary = (
            f"Patient ID: {patient_id.strip()}\n"
            f"Total Medications: {len(sorted_medications)}\n"
            f"Medications: {', '.join(sorted_medications)}"
        )
        return summary


