from dataclasses import dataclass
from typing import Dict, List, Optional, Tuple


class ModelRegistryError(Exception):
    """Base exception for model registry errors."""


class DuplicateModelVersionError(ModelRegistryError):
    """Raised when attempting to register a duplicate model-version pair."""


class InvalidDeploymentStatusError(ModelRegistryError):
    """Raised when an invalid deployment status is provided."""


class ModelNotFoundError(ModelRegistryError):
    """Raised when a requested model or version does not exist."""


@dataclass(frozen=True)
class ModelRecord:
    model_name: str
    version: str
    framework: str
    accuracy: float
    deployment_status: str


class ModelDeploymentManager:
    VALID_STATUSES = {"staging", "production", "archived"}

    def __init__(self) -> None:
        self._models: Dict[Tuple[str, str], ModelRecord] = {}

    def register_model(
        self,
        model_name: str,
        version: str,
        framework: str,
        accuracy: float,
        deployment_status: str,
    ) -> None:
        self._validate_status(deployment_status)
        key = self._make_key(model_name, version)

        if key in self._models:
            raise DuplicateModelVersionError(
                f"Model '{model_name}' with version '{version}' is already registered."
            )

        self._models[key] = ModelRecord(
            model_name=model_name.strip(),
            version=version.strip(),
            framework=framework.strip(),
            accuracy=float(accuracy),
            deployment_status=deployment_status.strip().lower(),
        )

    def update_deployment_status(
        self, model_name: str, version: str, new_status: str
    ) -> None:
        self._validate_status(new_status)
        key = self._make_key(model_name, version)

        if key not in self._models:
            raise ModelNotFoundError(
                f"Model '{model_name}' with version '{version}' was not found."
            )

        existing = self._models[key]
        self._models[key] = ModelRecord(
            model_name=existing.model_name,
            version=existing.version,
            framework=existing.framework,
            accuracy=existing.accuracy,
            deployment_status=new_status.strip().lower(),
        )

    def get_latest_production_ready_version(self, model_name: str) -> Optional[ModelRecord]:
        candidates = [
            record
            for record in self._models.values()
            if record.model_name.lower() == model_name.strip().lower()
            and record.deployment_status == "production"
        ]

        if not candidates:
            return None

        return max(candidates, key=lambda record: self._version_sort_key(record.version))

    def list_models(
        self,
        framework: Optional[str] = None,
        status: Optional[str] = None,
    ) -> List[ModelRecord]:
        if status is not None:
            self._validate_status(status)

        results = list(self._models.values())

        if framework is not None:
            framework_normalized = framework.strip().lower()
            results = [
                record
                for record in results
                if record.framework.lower() == framework_normalized
            ]

        if status is not None:
            status_normalized = status.strip().lower()
            results = [
                record
                for record in results
                if record.deployment_status == status_normalized
            ]

        return sorted(
            results,
            key=lambda record: (
                record.model_name.lower(),
                self._version_sort_key(record.version),
            ),
        )

    def _validate_status(self, status: str) -> None:
        normalized = status.strip().lower()
        if normalized not in self.VALID_STATUSES:
            raise InvalidDeploymentStatusError(
                f"Invalid deployment status '{status}'. "
                f"Valid statuses are: {sorted(self.VALID_STATUSES)}"
            )

    @staticmethod
    def _make_key(model_name: str, version: str) -> Tuple[str, str]:
        return model_name.strip().lower(), version.strip().lower()

    @staticmethod
    def _version_sort_key(version: str) -> Tuple:
        cleaned = version.strip().lower()
        if cleaned.startswith("v"):
            cleaned = cleaned[1:]

        parts = cleaned.split(".")
        parsed_parts = []
        for part in parts:
            if part.isdigit():
                parsed_parts.append((0, int(part)))
            else:
                parsed_parts.append((1, part))
        return tuple(parsed_parts)


