def monthly_spending_summary(
    transactions: List[Dict[str, Any]], target_month: str
) -> Dict[str, float]:
    """
    Return a monthly spending summary in the format {category: total_spent}
    for the given month (YYYY-MM).

    Includes only expense transactions (negative amounts), converts them to
    positive totals, and ignores income transactions.
    """
    monthly_expenses = [
        tx
        for tx in transactions
        if str(tx.get("date", "")).startswith(target_month)
        and isinstance(tx.get("amount"), (int, float))
        and tx["amount"] < 0
    ]

    if not monthly_expenses:
        return {}

    categories = {tx.get("category", "Uncategorized") for tx in monthly_expenses}

    return {
        category: sum(
            -tx["amount"]
            for tx in monthly_expenses
            if tx.get("category", "Uncategorized") == category
        )
        for category in categories
    }


