from collections import defaultdict
from typing import Any, Dict, List, Optional


def _is_number(value: Any) -> bool:
    """Return True if value is an int/float (excluding booleans)."""
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def validate_vm_record(vm: Dict[str, Any], index: Optional[int] = None) -> None:
    """
    Validate a single VM record.

    Required fields:
      - instance_id: str
      - region: str
      - cpu_avg_percent: number between 0 and 100
      - memory_avg_percent: number between 0 and 100
      - monthly_cost: non-negative number
    """
    if not isinstance(vm, dict):
        prefix = f"Record at index {index}: " if index is not None else ""
        raise TypeError(f"{prefix}Each VM entry must be a dictionary.")

    required_fields = {
        "instance_id",
        "region",
        "cpu_avg_percent",
        "memory_avg_percent",
        "monthly_cost",
    }

    missing = required_fields - vm.keys()
    if missing:
        prefix = f"Record at index {index}: " if index is not None else ""
        raise ValueError(f"{prefix}Missing required fields: {sorted(missing)}")

    if not isinstance(vm["instance_id"], str) or not vm["instance_id"].strip():
        raise ValueError(f"Record at index {index}: 'instance_id' must be a non-empty string.")

    if not isinstance(vm["region"], str) or not vm["region"].strip():
        raise ValueError(f"Record at index {index}: 'region' must be a non-empty string.")

    if not _is_number(vm["cpu_avg_percent"]) or not (0 <= vm["cpu_avg_percent"] <= 100):
        raise ValueError(
            f"Record at index {index}: 'cpu_avg_percent' must be a number between 0 and 100."
        )

    if not _is_number(vm["memory_avg_percent"]) or not (0 <= vm["memory_avg_percent"] <= 100):
        raise ValueError(
            f"Record at index {index}: 'memory_avg_percent' must be a number between 0 and 100."
        )

    if not _is_number(vm["monthly_cost"]) or vm["monthly_cost"] < 0:
        raise ValueError(
            f"Record at index {index}: 'monthly_cost' must be a non-negative number."
        )


def validate_inputs(
    vm_list: List[Dict[str, Any]],
    cpu_threshold: float,
    memory_threshold: float,
) -> None:
    """Validate the overall input list and threshold values."""
    if not isinstance(vm_list, list):
        raise TypeError("Input 'vm_list' must be a list of dictionaries.")

    if not _is_number(cpu_threshold) or not (0 <= cpu_threshold <= 100):
        raise ValueError("'cpu_threshold' must be a number between 0 and 100.")

    if not _is_number(memory_threshold) or not (0 <= memory_threshold <= 100):
        raise ValueError("'memory_threshold' must be a number between 0 and 100.")

    for idx, vm in enumerate(vm_list):
        validate_vm_record(vm, idx)


def find_underutilized_instances(
    vm_list: List[Dict[str, Any]],
    cpu_threshold: float = 20.0,
    memory_threshold: float = 30.0,
) -> List[Dict[str, Any]]:
    """
    Filter VMs whose CPU and memory utilization are both below the given thresholds.

    Uses a list comprehension for concise filtering.
    """
    validate_inputs(vm_list, cpu_threshold, memory_threshold)

    return [
        vm
        for vm in vm_list
        if vm["cpu_avg_percent"] < cpu_threshold
        and vm["memory_avg_percent"] < memory_threshold
    ]


def summarize_underutilized_instances(
    vm_list: List[Dict[str, Any]],
    cpu_threshold: float = 20.0,
    memory_threshold: float = 30.0,
) -> Dict[str, Any]:
    """
    Analyze VM utilization and return a structured summary dictionary.

    Output structure:
    {
        "thresholds": {...},
        "totals": {...},
        "regions": {
            "region-name": {
                "underutilized_count": int,
                "total_monthly_cost": float,
                "instances": [...]
            },
            ...
        }
    }
    """
    underutilized = find_underutilized_instances(
        vm_list=vm_list,
        cpu_threshold=cpu_threshold,
        memory_threshold=memory_threshold,
    )

    # Group underutilized instances by region.
    grouped_by_region: Dict[str, List[Dict[str, Any]]] = defaultdict(list)
    for vm in underutilized:
        grouped_by_region[vm["region"]].append(vm)

    # Build a structured regional summary.
    regions_summary = {
        region: {
            "underutilized_count": len(instances),
            "total_monthly_cost": round(sum(vm["monthly_cost"] for vm in instances), 2),
            "instances": [
                {
                    "instance_id": vm["instance_id"],
                    "cpu_avg_percent": vm["cpu_avg_percent"],
                    "memory_avg_percent": vm["memory_avg_percent"],
                    "monthly_cost": vm["monthly_cost"],
                }
                for vm in instances
            ],
        }
        for region, instances in sorted(grouped_by_region.items())
    }

    overall_cost = round(sum(vm["monthly_cost"] for vm in underutilized), 2)

    summary = {
        "thresholds": {
            "cpu_avg_percent_below": float(cpu_threshold),
            "memory_avg_percent_below": float(memory_threshold),
        },
        "totals": {
            "total_instances_analyzed": len(vm_list),
            "underutilized_instances_count": len(underutilized),
            "underutilized_total_monthly_cost": overall_cost,
        },
        "regions": regions_summary,
    }

    return summary


