from __future__ import annotations

from collections import defaultdict, deque
from dataclasses import dataclass, field
from datetime import datetime, timedelta, timezone
from typing import Any, Deque, Dict, Iterable, Iterator, List, Mapping, MutableMapping, Optional, Tuple


LAB_WINDOW = timedelta(hours=24)


def _parse_iso8601(value: Any) -> Optional[datetime]:
    if not isinstance(value, str):
        return None
    try:
        dt = datetime.fromisoformat(value.replace("Z", "+00:00"))
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return dt
    except (ValueError, TypeError):
        return None


def _normalize_medication(value: Any) -> Optional[str]:
    if not isinstance(value, str):
        return None
    med = value.strip().lower()
    return med or None


def _normalize_lab_name(value: Any) -> Optional[str]:
    if not isinstance(value, str):
        return None
    lab = value.strip().upper()
    return lab or None


def _to_float(value: Any) -> Optional[float]:
    try:
        if value is None or value == "":
            return None
        return float(value)
    except (TypeError, ValueError):
        return None


@dataclass
class PatientState:
    allergies: set[str] = field(default_factory=set)
    orders: Dict[str, Dict[str, Any]] = field(default_factory=dict)
    labs: Dict[str, Deque[Tuple[datetime, float]]] = field(default_factory=lambda: defaultdict(deque))

    def prune_expired_labs(self, now: datetime) -> None:
        cutoff = now - LAB_WINDOW
        for lab_name in list(self.labs.keys()):
            dq = self.labs[lab_name]
            while dq and dq[0][0] < cutoff:
                dq.popleft()
            if not dq:
                del self.labs[lab_name]

    def add_lab(self, lab_name: str, timestamp: datetime, value: float) -> None:
        dq = self.labs[lab_name]
        dq.append((timestamp, value))

    def latest_valid_lab_within_window(self, lab_name: str, now: datetime) -> Optional[Tuple[datetime, float]]:
        self.prune_expired_labs(now)
        dq = self.labs.get(lab_name)
        if not dq:
            return None
        for ts, val in reversed(dq):
            if ts <= now and ts >= now - LAB_WINDOW:
                return ts, val
        return None


def stream_medication_safety_violations(
    events: Iterable[Mapping[str, Any]],
    lab_rules: Mapping[str, Mapping[str, Any]],
    *,
    include_malformed_as_violations: bool = False,
) -> Iterator[Dict[str, Any]]:
    """
    Stream EHR events and lazily yield medication administration safety violations.

    Example:
        events = iter([
            {"patient_id": "p1", "timestamp": "2025-01-01T08:00:00Z", "event_type": "allergy",
             "data": {"medication": "warfarin", "active": True}},
            {"patient_id": "p1", "timestamp": "2025-01-01T09:00:00Z", "event_type": "lab_result",
             "data": {"lab": "INR", "value": 4.2}},
            {"patient_id": "p1", "timestamp": "2025-01-01T10:00:00Z", "event_type": "medication_order",
             "data": {"medication": "warfarin", "dose": 5}},
            {"patient_id": "p1", "timestamp": "2025-01-01T11:00:00Z", "event_type": "medication_admin",
             "data": {"medication": "warfarin", "dose": 7}},
        ])
        rules = {"warfarin": {"lab": "INR", "min": 2.0, "max": 3.5}}
        first_violation = next(stream_medication_safety_violations(events, rules))
    """
    normalized_rules: Dict[str, Dict[str, Any]] = {}
    for med, rule in lab_rules.items():
        nmed = _normalize_medication(med)
        lab_name = _normalize_lab_name(rule.get("lab")) if isinstance(rule, Mapping) else None
        if not nmed or not lab_name:
            continue
        normalized_rules[nmed] = {
            "lab": lab_name,
            "min": _to_float(rule.get("min")),
            "max": _to_float(rule.get("max")),
        }

    patient_states: MutableMapping[str, PatientState] = defaultdict(PatientState)

    for raw_event in events:
        if not isinstance(raw_event, Mapping):
            if include_malformed_as_violations:
                yield {
                    "patient_id": None,
                    "timestamp": None,
                    "medication": None,
                    "violation_types": ["malformed_event"],
                    "context": {"reason": "event is not a mapping", "event": raw_event},
                }
            continue

        patient_id = raw_event.get("patient_id")
        timestamp_raw = raw_event.get("timestamp")
        event_type = raw_event.get("event_type")
        data = raw_event.get("data")

        if not isinstance(patient_id, str) or not patient_id.strip():
            if include_malformed_as_violations:
                yield {
                    "patient_id": patient_id,
                    "timestamp": timestamp_raw,
                    "medication": None,
                    "violation_types": ["malformed_event"],
                    "context": {"reason": "missing/invalid patient_id", "event": dict(raw_event)},
                }
            continue

        timestamp = _parse_iso8601(timestamp_raw)
        if timestamp is None or not isinstance(event_type, str) or not isinstance(data, Mapping):
            if include_malformed_as_violations:
                yield {
                    "patient_id": patient_id,
                    "timestamp": timestamp_raw,
                    "medication": None,
                    "violation_types": ["malformed_event"],
                    "context": {"reason": "invalid timestamp, event_type, or data", "event": dict(raw_event)},
                }
            continue

        state = patient_states[patient_id]
        state.prune_expired_labs(timestamp)

        if event_type == "allergy":
            medication = _normalize_medication(data.get("medication"))
            if not medication:
                if include_malformed_as_violations:
                    yield {
                        "patient_id": patient_id,
                        "timestamp": timestamp_raw,
                        "medication": None,
                        "violation_types": ["malformed_event"],
                        "context": {"reason": "allergy event missing medication", "event": dict(raw_event)},
                    }
                continue
            active = data.get("active", True)
            if bool(active):
                state.allergies.add(medication)
            else:
                state.allergies.discard(medication)

        elif event_type == "lab_result":
            lab_name = _normalize_lab_name(data.get("lab"))
            value = _to_float(data.get("value"))
            if not lab_name or value is None:
                if include_malformed_as_violations:
                    yield {
                        "patient_id": patient_id,
                        "timestamp": timestamp_raw,
                        "medication": None,
                        "violation_types": ["malformed_event"],
                        "context": {"reason": "lab_result missing lab or value", "event": dict(raw_event)},
                    }
                continue
            state.add_lab(lab_name, timestamp, value)

        elif event_type == "medication_order":
            medication = _normalize_medication(data.get("medication"))
            dose = _to_float(data.get("dose"))
            if not medication or dose is None:
                if include_malformed_as_violations:
                    yield {
                        "patient_id": patient_id,
                        "timestamp": timestamp_raw,
                        "medication": medication,
                        "violation_types": ["malformed_event"],
                        "context": {"reason": "medication_order missing medication or dose", "event": dict(raw_event)},
                    }
                continue
            state.orders[medication] = {
                "dose": dose,
                "timestamp": timestamp,
                "raw_timestamp": timestamp_raw,
            }

        elif event_type == "medication_admin":
            medication = _normalize_medication(data.get("medication"))
            admin_dose = _to_float(data.get("dose"))
            if not medication or admin_dose is None:
                if include_malformed_as_violations:
                    yield {
                        "patient_id": patient_id,
                        "timestamp": timestamp_raw,
                        "medication": medication,
                        "violation_types": ["malformed_event"],
                        "context": {"reason": "medication_admin missing medication or dose", "event": dict(raw_event)},
                    }
                continue

            violation_types: List[str] = []
            context: Dict[str, Any] = {
                "admin_dose": admin_dose,
            }

            if medication in state.allergies:
                violation_types.append("allergy_conflict")
                context["active_allergy"] = True

            order = state.orders.get(medication)
            if order is not None:
                ordered_dose = order.get("dose")
                context["most_recent_order"] = {
                    "dose": ordered_dose,
                    "timestamp": order.get("raw_timestamp"),
                }
                if isinstance(ordered_dose, (int, float)) and admin_dose > float(ordered_dose):
                    violation_types.append("dose_exceeds_order")
            else:
                context["most_recent_order"] = None

            rule = normalized_rules.get(medication)
            if rule:
                lab_name = rule["lab"]
                min_allowed = rule.get("min")
                max_allowed = rule.get("max")
                latest_lab = state.latest_valid_lab_within_window(lab_name, timestamp)
                context["lab_rule"] = {
                    "lab": lab_name,
                    "min": min_allowed,
                    "max": max_allowed,
                    "window_hours": 24,
                }

                if latest_lab is None:
                    violation_types.append("required_lab_missing")
                    context["latest_lab"] = None
                else:
                    lab_ts, lab_value = latest_lab
                    context["latest_lab"] = {
                        "lab": lab_name,
                        "value": lab_value,
                        "timestamp": lab_ts.isoformat(),
                    }
                    out_of_range = (
                        (min_allowed is not None and lab_value < min_allowed) or
                        (max_allowed is not None and lab_value > max_allowed)
                    )
                    if out_of_range:
                        violation_types.append("required_lab_out_of_range")

            if violation_types:
                yield {
                    "patient_id": patient_id,
                    "timestamp": timestamp_raw,
                    "medication": medication,
                    "violation_types": violation_types,
                    "context": context,
                }

        else:
            if include_malformed_as_violations:
                yield {
