import re
from typing import List, Dict, Any, Optional


FAILURE_PATTERNS = [
    {
        "name": "github_actions_error",
        "tool": "GitHub Actions",
        "pattern": re.compile(
            r"(?P<timestamp>\d{4}-\d{2}-\d{2}[T ][\d:\.\-+Z]+)?\s*::error::(?P<message>.+)",
            re.IGNORECASE,
        ),
        "remediation": "Review the GitHub Actions step logs and validate workflow commands, secrets, and environment variables.",
    },
    {
        "name": "jenkins_error",
        "tool": "Jenkins",
        "pattern": re.compile(
            r"(?P<timestamp>\d{4}-\d{2}-\d{2}[T ][\d:\.\-+Z]+)?\s*(ERROR|hudson\.AbortException:)\s*(?P<message>.+)",
            re.IGNORECASE,
        ),
        "remediation": "Inspect the Jenkins stage output, verify build scripts, and confirm agent/tool configuration.",
    },
    {
        "name": "gitlab_job_failed",
        "tool": "GitLab CI",
        "pattern": re.compile(
            r"(?P<timestamp>\d{4}-\d{2}-\d{2}[T ][\d:\.\-+Z]+)?\s*(Job failed:|ERROR: Job failed:)\s*(?P<message>.+)?",
            re.IGNORECASE,
        ),
        "remediation": "Check the GitLab job trace, validate runner availability, and review script exit codes.",
    },
    {
        "name": "generic_deploy_failure",
        "tool": "Generic CI/CD",
        "pattern": re.compile(
            r"(?P<timestamp>\d{4}-\d{2}-\d{2}[T ][\d:\.\-+Z]+)?\s*(?P<message>.*(?:deployment failed|deploy failed|release failed|failed to deploy).*)",
            re.IGNORECASE,
        ),
        "remediation": "Review deployment configuration, target environment connectivity, and application release artifacts.",
    },
    {
        "name": "non_zero_exit",
        "tool": "Generic CI/CD",
        "pattern": re.compile(
            r"(?P<timestamp>\d{4}-\d{2}-\d{2}[T ][\d:\.\-+Z]+)?\s*(?P<message>.*(?:exit code\s*[1-9]\d*|returned non-zero exit status).*)",
            re.IGNORECASE,
        ),
        "remediation": "Inspect the failing command, verify script logic, and review upstream dependency failures.",
    },
]


STAGE_PATTERNS = [
    re.compile(r"\b(stage|pipeline stage)\s*[:=-]?\s*(?P<stage>[A-Za-z0-9_\- /.]+)", re.IGNORECASE),
    re.compile(r"\[(?P<stage>Build|Test|Deploy|Release|Package|Publish|Rollback)\]", re.IGNORECASE),
    re.compile(r"\b(?P<stage>build|test|deploy|release|package|publish|rollback)\b", re.IGNORECASE),
]

TIMESTAMP_PATTERNS = [
    re.compile(r"\b\d{4}-\d{2}-\d{2}[T ][\d:\.\-+Z]+\b"),
    re.compile(r"\b\d{2}:\d{2}:\d{2}\b"),
]


def validate_log_input(log_text: str) -> None:
    if not isinstance(log_text, str):
        raise TypeError("log_text must be a string.")
    if not log_text.strip():
        raise ValueError("log_text cannot be empty.")


def split_log_lines(log_text: str) -> List[str]:
    return [line.rstrip() for line in log_text.splitlines() if line.strip()]


def extract_timestamp(line: str) -> Optional[str]:
    for pattern in TIMESTAMP_PATTERNS:
        match = pattern.search(line)
        if match:
            return match.group(0)
    return None


def extract_stage(line: str, previous_stage: Optional[str] = None) -> Optional[str]:
    for pattern in STAGE_PATTERNS:
        match = pattern.search(line)
        if match:
            stage = match.group("stage").strip(" :-[]")
            return stage.title()
    return previous_stage


def normalize_message(message: str) -> str:
    if not message:
        return "Unknown deployment failure."
    return re.sub(r"\s+", " ", message).strip(" -:")


def detect_failures(lines: List[str]) -> List[Dict[str, Any]]:
    failures: List[Dict[str, Any]] = []
    current_stage: Optional[str] = None

    for index, line in enumerate(lines):
        current_stage = extract_stage(line, current_stage)

        for rule in FAILURE_PATTERNS:
            match = rule["pattern"].search(line)
            if not match:
                continue

            message = normalize_message(match.groupdict().get("message", "") or line)
            timestamp = match.groupdict().get("timestamp") or extract_timestamp(line)
            stage = current_stage or infer_stage_from_context(lines, index) or "Unknown"

            failures.append(
                {
                    "pipeline_stage": stage,
                    "error_message": message,
                    "timestamp": timestamp or "Unknown",
                    "suggested_remediation": rule["remediation"],
                    "source_tool": rule["tool"],
                    "pattern_name": rule["name"],
                }
            )
            break

    return failures


def infer_stage_from_context(lines: List[str], current_index: int, window: int = 3) -> Optional[str]:
    start = max(0, current_index - window)
    end = min(len(lines), current_index + window + 1)

    for idx in range(start, end):
        stage = extract_stage(lines[idx])
        if stage:
            return stage
    return None


def summarize_failures(failures: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    # Use lambda functions to filter valid failure entries.
    valid_failures = list(
        filter(
            lambda item: isinstance(item, dict)
            and item.get("error_message")
            and item.get("pipeline_stage"),
            failures,
        )
    )

    # Use lambda functions to transform entries into concise report dictionaries.
    concise_report = list(
        map(
            lambda item: {
                "pipeline_stage": item["pipeline_stage"],
                "error_message": item["error_message"],
                "timestamp": item["timestamp"],
                "suggested_remediation": item["suggested_remediation"],
            },
            valid_failures,
        )
    )

    return concise_report


def parse_pipeline_logs(log_text: str) -> List[Dict[str, Any]]:
    """
    Parse CI/CD pipeline logs and return a concise summary of failed deployment steps.

    Returns:
        List of dictionaries with:
        - pipeline_stage
        - error_message
        - timestamp
        - suggested_remediation
    """
    validate_log_input(log_text)
    lines = split_log_lines(log_text)
    failures = detect_failures(lines)
    return summarize_failures(failures)


def main(log_text: str) -> List[Dict[str, Any]]:
    return parse_pipeline_logs(log_text)


