class Transaction:
    def __init__(self, date, category, amount, transaction_type):
        self.date = date
        self.category = category
        self.amount = self.validate_amount(amount)
        self.transaction_type = self.validate_type(transaction_type)

    def validate_amount(self, amount):
        if amount < 0:
            raise ValueError("Amount cannot be negative.")
        return amount

    def validate_type(self, transaction_type):
        valid_types = ["income", "expense"]
        if transaction_type not in valid_types:
            raise ValueError("Transaction type must be 'income' or 'expense'.")
        return transaction_type


class FinanceTracker:
    def __init__(self):
        self.transactions = []

    def add_transaction(self, transaction):
        if not isinstance(transaction, Transaction):
            raise TypeError("Only Transaction objects can be added.")
        self.transactions.append(transaction)

    def get_total_income(self):
        total = 0
        for transaction in self.transactions:
            if transaction.transaction_type == "income":
                total += transaction.amount
        return total

    def get_total_expenses(self):
        total = 0
        for transaction in self.transactions:
            if transaction.transaction_type == "expense":
                total += transaction.amount
        return total

    def get_balance(self):
        return self.get_total_income() - self.get_total_expenses()

    def get_spending_by_category(self):
        summary = {}
        for transaction in self.transactions:
            if transaction.transaction_type == "expense":
                if transaction.category in summary:
                    summary[transaction.category] += transaction.amount
                else:
                    summary[transaction.category] = transaction.amount
        return summary

    def generate_report(self):
        print("=" * 40)
        print("PERSONAL FINANCE REPORT")
        print("=" * 40)
        print("\nTransactions:")
        for transaction in self.transactions:
            print(
                f"Date: {transaction.date} | "
                f"Category: {transaction.category} | "
                f"Type: {transaction.transaction_type} | "
                f"Amount: ${transaction.amount:.2f}"
            )

        print("\n" + "-" * 40)
        print(f"Total Income:   ${self.get_total_income():.2f}")
        print(f"Total Expenses: ${self.get_total_expenses():.2f}")
        print(f"Current Balance:${self.get_balance():.2f}")

        print("\nSpending by Category:")
        spending_summary = self.get_spending_by_category()
        if spending_summary:
            for category, amount in spending_summary.items():
                print(f"- {category}: ${amount:.2f}")
        else:
            print("No expenses recorded.")
        print("=" * 40)


