def generate_monthly_summary(transactions, year, month):
    if not 1 <= month <= 12:
        raise ValueError("month must be between 1 and 12")

    month_label = f"{year:04d}-{month:02d}"

    if not transactions:
        return {
            "month": month_label,
            "total_income": 0.0,
            "total_expenses": 0.0,
            "net_savings": 0.0,
            "category_breakdown": {},
        }

    monthly_transactions = [
        transaction
        for transaction in transactions
        if datetime.strptime(transaction["date"], "%Y-%m-%d").year == year
        and datetime.strptime(transaction["date"], "%Y-%m-%d").month == month
    ]

    if not monthly_transactions:
        return {
            "month": month_label,
            "total_income": 0.0,
            "total_expenses": 0.0,
            "net_savings": 0.0,
            "category_breakdown": {},
        }

    total_income = round(
        sum(t["amount"] for t in monthly_transactions if t["amount"] > 0), 2
    )
    total_expenses = round(
        abs(sum(t["amount"] for t in monthly_transactions if t["amount"] < 0)), 2
    )
    net_savings = round(total_income - total_expenses, 2)

    category_totals = defaultdict(float)
    for transaction in monthly_transactions:
        amount = transaction["amount"]
        category = transaction["category"]
        if amount < 0:
            category_totals[category] += abs(amount)

    category_breakdown = {
        category: round(total, 2)
        for category, total in category_totals.items()
        if total > 0
    }

    return {
        "month": month_label,
        "total_income": total_income,
        "total_expenses": total_expenses,
        "net_savings": net_savings,
        "category_breakdown": category_breakdown,
    }


