from typing import Any, Dict, List, Union

ALLOWED_TOOLS = {"git", "docker", "pytest"}


def validate_pipeline_config(pipeline: Dict[str, Any]) -> Union[List[str], str]:
    errors: List[str] = []

    if not isinstance(pipeline, dict):
        return ["Pipeline configuration must be a dictionary."]

    required_pipeline_fields = ["name", "branch", "steps"]
    for field in required_pipeline_fields:
        if field not in pipeline:
            errors.append(f"Missing required pipeline field: '{field}'.")

    if "steps" in pipeline:
        steps = pipeline["steps"]

        if not isinstance(steps, list):
            errors.append("Field 'steps' must be a list.")
        else:
            if len(steps) == 0:
                errors.append("Field 'steps' must not be empty.")

            for index, step in enumerate(steps, start=1):
                if not isinstance(step, dict):
                    errors.append(f"Step {index} must be a dictionary.")
                    continue

                required_step_fields = ["step_name", "tool", "timeout"]
                for field in required_step_fields:
                    if field not in step:
                        errors.append(f"Step {index} is missing required field: '{field}'.")

                if "tool" in step and step["tool"] not in ALLOWED_TOOLS:
                    errors.append(
                        f"Step {index} has invalid tool '{step['tool']}'. "
                        f"Allowed tools: {', '.join(sorted(ALLOWED_TOOLS))}."
                    )

                if "timeout" in step:
                    timeout = step["timeout"]
                    if not isinstance(timeout, int) or isinstance(timeout, bool) or timeout <= 0:
                        errors.append(
                            f"Step {index} has invalid timeout '{timeout}'. "
                            "Timeout must be a positive integer."
                        )

    if errors:
        return errors

    return "Pipeline configuration is valid."


