class TelemedicineQueue:
    def __init__(self):
        self.patients = []

    def get_urgency_priority(self, urgency_level):
        priority_map = {
            "high": 3,
            "medium": 2,
            "low": 1
        }
        return priority_map.get(urgency_level.lower(), 0)

    def add_patient(self, name, requested_time, urgency_level):
        patient_record = {
            "name": name,
            "requested_time": requested_time,
            "urgency": urgency_level,
            "priority": self.get_urgency_priority(urgency_level)
        }
        self.patients.append(patient_record)

    def sort_queue(self):
        self.patients.sort(
            key=lambda patient: (-patient["priority"], patient["requested_time"])
        )

    def get_patient_order(self):
        self.sort_queue()
        return [patient["name"] for patient in self.patients]


def get_telemedicine_appointment_order(patient_records):
    if not patient_records:
        return []

    queue = TelemedicineQueue()

    for record in patient_records:
        name = record["name"]
        requested_time = record["requested_time"]
        urgency_level = record["urgency"]
        queue.add_patient(name, requested_time, urgency_level)

    return queue.get_patient_order()

from __future__ import annotations

from collections import defaultdict, deque
from datetime import datetime, timedelta, timezone
from typing import Any, Callable, Deque, Dict, Generator, Hashable, Iterable, Iterator, Mapping, Optional, Tuple, Union


Record = Any
TimestampLike = Union[datetime, int, float, str]
Key = Tuple[str, str, str, str]


def _parse_timestamp(value: TimestampLike) -> datetime:
    if isinstance(value, datetime):
        dt = value
    elif isinstance(value, (int, float)):
        dt = datetime.fromtimestamp(value, tz=timezone.utc)
    elif isinstance(value, str):
        s = value.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        dt = datetime.fromisoformat(s)
    else:
        raise TypeError(f"Unsupported timestamp type: {type(value).__name__}")

    if dt.tzinfo is None:
        return dt.replace(tzinfo=timezone.utc)
    return dt.astimezone(timezone.utc)


def _extract_field(record: Record, field: str) -> Any:
    if isinstance(record, Mapping):
        return record[field]
    return getattr(record, field)


def _normalize_key_part(value: Any, field_name: str) -> str:
    if value is None:
        raise ValueError(f"Missing required field: {field_name}")
    return str(value)


def _default_error_handler(record: Record, exc: Exception) -> None:
    return None


def first_unique_misconfigurations(
    records: Iterable[Record],
    *,
    window: timedelta = timedelta(hours=24),
    timestamp_field: str = "timestamp",
    account_id_field: str = "cloud_account_id",
    resource_id_field: str = "resource_id",
    resource_type_field: str = "resource_type",
    misconfiguration_code_field: str = "misconfiguration_code",
    on_error: Optional[Callable[[Record, Exception], None]] = None,
) -> Iterator[Record]:
    if window.total_seconds() <= 0:
        raise ValueError("window must be positive")

    error_handler = on_error or _default_error_handler

    active_counts: Dict[Key, int] = defaultdict(int)
    expiry_queue: Deque[Tuple[datetime, Key]] = deque()
    last_timestamp: Optional[datetime] = None

    for record in records:
        try:
            event_ts = _parse_timestamp(_extract_field(record, timestamp_field))

            if last_timestamp is not None and event_ts < last_timestamp:
                raise ValueError("Input records must be sorted by non-decreasing timestamp")
            last_timestamp = event_ts

            expire_before = event_ts - window
            while expiry_queue and expiry_queue[0][0] <= expire_before:
                _, expired_key = expiry_queue.popleft()
                count = active_counts.get(expired_key, 0)
                if count <= 1:
                    active_counts.pop(expired_key, None)
                else:
                    active_counts[expired_key] = count - 1

            key: Key = (
                _normalize_key_part(_extract_field(record, account_id_field), account_id_field),
                _normalize_key_part(_extract_field(record, resource_id_field), resource_id_field),
                _normalize_key_part(_extract_field(record, resource_type_field), resource_type_field),
                _normalize_key_part(_extract_field(record, misconfiguration_code_field), misconfiguration_code_field),
            )

            is_first_in_window = active_counts.get(key, 0) == 0
            active_counts[key] += 1
            expiry_queue.append((event_ts, key))

            if is_first_in_window:
                yield record

        except Exception as exc:
            error_handler(record, exc)


