class BudgetError(Exception):
    pass


@dataclass(frozen=True)
class Transaction:
    date: date
    category: str
    amount: Decimal
    transaction_type: str
    description: str = ""

    def __post_init__(self) -> None:
        if not isinstance(self.date, date):
            raise ValueError("date must be a datetime.date instance")

        category = (self.category or "").strip()
        if not category:
            raise ValueError("category cannot be empty")
        object.__setattr__(self, "category", category)

        if not isinstance(self.amount, Decimal):
            raise ValueError("amount must be a Decimal")
        if self.amount <= Decimal("0"):
            raise ValueError("amount must be greater than zero")

        transaction_type = (self.transaction_type or "").strip().lower()
        if transaction_type not in {"income", "expense"}:
            raise ValueError("transaction_type must be 'income' or 'expense'")
        object.__setattr__(self, "transaction_type", transaction_type)

        object.__setattr__(self, "description", (self.description or "").strip())

    @classmethod
    def from_csv_row(cls, row: Dict[str, str]) -> "Transaction":
        required_fields = {"date", "category", "amount", "type"}
        missing = [field for field in required_fields if field not in row]
        if missing:
            raise ValueError(f"missing required columns: {', '.join(missing)}")

        raw_date = (row.get("date") or "").strip()
        raw_category = (row.get("category") or "").strip()
        raw_amount = (row.get("amount") or "").strip()
        raw_type = (row.get("type") or "").strip()
        raw_description = (row.get("description") or "").strip()

        try:
            parsed_date = datetime.strptime(raw_date, "%Y-%m-%d").date()
        except ValueError as exc:
            raise ValueError(f"invalid date '{raw_date}', expected YYYY-MM-DD") from exc

        try:
            parsed_amount = Decimal(raw_amount)
        except (InvalidOperation, ValueError) as exc:
            raise ValueError(f"invalid amount '{raw_amount}'") from exc

        return cls(
            date=parsed_date,
            category=raw_category,
            amount=parsed_amount,
            transaction_type=raw_type,
            description=raw_description,
        )


class Account:
    def __init__(self, name: str) -> None:
        name = (name or "").strip()
        if not name:
            raise ValueError("account name cannot be empty")
        self._name = name
        self._transactions: List[Transaction] = []

    @property
    def name(self) -> str:
        return self._name

    def add_transaction(self, transaction: Transaction) -> None:
        if not isinstance(transaction, Transaction):
            raise TypeError("transaction must be a Transaction instance")
        self._transactions.append(transaction)

    def get_transactions(
        self,
        start_date: Optional[date] = None,
        end_date: Optional[date] = None,
        category: Optional[str] = None,
    ) -> List[Transaction]:
        if start_date and end_date and start_date > end_date:
            raise ValueError("start_date cannot be after end_date")

        normalized_category = category.strip().lower() if category else None
        results: List[Transaction] = []

        for transaction in self._transactions:
            if start_date and transaction.date < start_date:
                continue
            if end_date and transaction.date > end_date:
                continue
            if normalized_category and transaction.category.lower() != normalized_category:
                continue
            results.append(transaction)

        return sorted(results, key=lambda t: (t.date, t.category, t.amount))

    def calculate_balance(self) -> Decimal:
        balance = Decimal("0")
        for transaction in self._transactions:
            if transaction.transaction_type == "income":
                balance += transaction.amount
            else:
                balance -= transaction.amount
        return balance

    def __iter__(self) -> Iterable[Transaction]:
        return iter(self._transactions)


class BudgetManager:
    def __init__(self) -> None:
        self._accounts: Dict[str, Account] = {}
        self._category_budgets: Dict[str, Decimal] = {}

    def add_account(self, account: Account) -> None:
        if not isinstance(account, Account):
            raise TypeError("account must be an Account instance")
        if account.name in self._accounts:
            raise ValueError(f"account '{account.name}' already exists")
        self._accounts[account.name] = account

    def get_account(self, name: str) -> Account:
        try:
            return self._accounts[name]
        except KeyError as exc:
            raise KeyError(f"account '{name}' not found") from exc

    def set_category_budget(self, category: str, amount: Decimal) -> None:
        category = (category or "").strip()
        if not category:
            raise ValueError("category cannot be empty")
        if not isinstance(amount, Decimal):
            raise TypeError("budget amount must be a Decimal")
        if amount < Decimal("0"):
            raise ValueError("budget amount cannot be negative")
        self._category_budgets[category] = amount

    def load_transactions_from_csv(
        self,
        csv_path: str,
        default_account_name: str = "Main",
        account_column: str = "account",
    ) -> List[str]:
        errors: List[str] = []

        if default_account_name not in self._accounts:
            self.add_account(Account(default_account_name))

        try:
            with open(csv_path, "r", newline="", encoding="utf-8") as file:
                reader = csv.DictReader(file)
                if reader.fieldnames is None:
                    raise BudgetError("CSV file is empty or missing a header row")

                for line_number, row in enumerate(reader, start=2):
                    try:
                        if not any((value or "").strip() for value in row.values()):
                            continue

                        account_name = (row.get(account_column) or default_account_name).strip()
                        if not account_name:
                            account_name = default_account_name

                        if account_name not in self._accounts:
                            self.add_account(Account(account_name))

                        transaction = Transaction.from_csv_row(row)
                        self._accounts[account_name].add_transaction(transaction)
                    except Exception as exc:
                        errors.append(f"Line {line_number}: {exc}")
        except FileNotFoundError:
            raise FileNotFoundError(f"CSV file not found: {csv_path}")
        except OSError as exc:
            raise OSError(f"Unable to read CSV file '{csv_path}': {exc}") from exc

        return errors

    def _month_date_range(self, year: int, month: int) -> Tuple[date, date]:
        if not 1 <= month <= 12:
            raise ValueError("month must be between 1 and 12")
        start = date(year, month, 1)
        if month == 12:
            end = date(year, 12, 31)
        else:
            next_month = date(year, month + 1, 1)
            end = next_month.fromordinal(next_month.toordinal() - 1)
        return start, end

    def _all_transactions_for_month(self, year: int, month: int) -> List[Transaction]:
        start, end = self._month_date_range(year, month)
        transactions: List[Transaction] = []
        for account in self._accounts.values():
            transactions.extend(account.get_transactions(start_date=start, end_date=end))
        return transactions

    def calculate_monthly_totals(self, year: int, month: int) -> Dict[str, Decimal]:
        transactions = self._all_transactions_for_month(year, month)
        total_income = sum(
            (t.amount for t in transactions if t.transaction_type == "income"),
            Decimal("0"),
        )
        total_expenses = sum(
            (t.amount for t in transactions if t.transaction_type == "expense"),
            Decimal("0"),
        )
        net_savings = total_income - total_expenses
        return {
            "income": total_income,
            "expenses": total_expenses,
            "net_savings": net_savings,
        }

    def compare_budget(self, year: int, month: int) -> Dict[str, Dict[str, Decimal or str]]:
        transactions = self._all_transactions_for_month(year, month)
        actual_spending: Dict[str, Decimal] = {}

        for transaction in transactions:
            if transaction.transaction_type != "expense":
                continue
            actual_spending[transaction.category] = actual_spending.get(
                transaction.category, Decimal("0")
            ) + transaction.amount

        categories = set(actual_spending.keys()) | set(self._category_budgets.keys())
        comparison: Dict[str, Dict[str, Decimal or str]] = {}

        for category in sorted(categories):
            budget = self._category_budgets.get(category, Decimal("0"))
            actual = actual_spending.get(category, Decimal("0"))
            difference = budget - actual
            status = "under budget"
            if actual > budget:
                status = "over budget"
            elif actual == budget:
                status = "on budget"

            comparison[category] = {
                "budget": budget,
                "actual": actual,
                "difference": difference,
                "status": status,
            }

        return comparison

    def generate_monthly_report(self, year: int, month: int) -> str:
        totals = self.calculate_monthly_totals(year, month)
        comparison = self.compare_budget(year, month)

        lines: List[str] = []
        lines.append(f"Monthly Budget Report - {year:04d}-{month:02d}")
        lines.append("=" * 50)
        lines.append(f"Total Income   : {self._format_currency(totals['income'])}")
        lines.append(f"Total Expenses : {self._format_currency(totals['expenses'])}")
        lines.append(f"Net Savings    : {self._format_currency(totals['net_savings'])}")
        lines.append("")

        lines.append("Account Balances")
        lines.append("-" * 50)
        if self._accounts:
            for account_name in sorted(self._accounts):
                balance = self._accounts[account_name].calculate_balance()
                lines.append(f"{account_name:<25} {self._format_currency(balance):>15}")
        else:
            lines.append("No accounts available.")
        lines.append("")

        lines.append("Category Budget Comparison")
        lines.append("-" * 50)
        if comparison:
            header = f"{'Category':<20} {'Budget':>12} {'Actual':>12} {'Diff':>12} {'Status':>14}"
            lines.append(header)
            lines.append("-" * len(header))
            for category, data in comparison.items():
                lines.append(
                    f"{category:<20} "
                    f"{self._format_currency(data['budget']):>12} "
                    f"{self._format_currency(data['actual']):>12} "
                    f"{self._format_currency(data['difference']):>12} "
                    f"{str(data['status']):>14}"
                )
        else:
            lines.append("No budget or expense data for this month.")

        return "\n".join(lines)

    @staticmethod
    def _format_currency(amount: Decimal) -> str:
        return f"${amount.quantize(Decimal('0.01')):,.2f}"


def parse_budget_args(args: List[str]) -> Dict[str, Decimal]:
    budgets: Dict[str, Decimal] = {}
    for item in args:
        if "=" not in item:
            raise ValueError(f"invalid budget format '{item}', expected Category=Amount")
        category, raw_amount = item.split("=", 1)
        category = category.strip()
        if not category:
            raise ValueError(f"invalid budget category in '{item}'")
        try:
            amount = Decimal(raw_amount.strip())
        except (InvalidOperation, ValueError) as exc:
            raise ValueError(f"invalid budget amount in '{item}'") from exc
        if amount < Decimal("0"):
            raise ValueError(f"budget amount cannot be negative in '{item}'")
        budgets[category] = amount
    return budgets


def print_usage() -> None:
    script_name = sys.argv[0] if sys.argv else "budget_tool.py"
    print(
        f"Usage:\n"
        f"  python {script_name} <csv_file> <YYYY-MM> [Category=Budget ...]\n\n"
        f"CSV columns required:\n"
        f"  date, category, amount, type\n"
        f"Optional columns:\n"
        f"  description, account\n\n"
        f"Example:\n"
        f"  python {script_name} transactions.csv 2025-03 Food=500 Rent=1200 Transport=150"
    )


def main() -> None:
    if len(sys.argv) < 3:
        print_usage()
        sys.exit(1)

    csv_file = sys.argv[1]
    month_text = sys.argv[2]

    try:
        report_month = datetime.strptime(month_text, "%Y-%m")
        year = report_month.year
        month = report_month.month
    except ValueError:
        print("Error: month must be in YYYY-MM format.", file=sys.stderr)
        sys.exit(1)

    try:
        budgets = parse_budget_args(sys.argv[3:])
    except ValueError as exc:
        print(f"Error: {exc}", file=sys.stderr)
        sys.exit(1)

    manager = BudgetManager()
    for category, amount in budgets.items():
        manager.set_category_budget(category, amount)

    try:
        errors = manager.load_transactions_from_csv(csv_file)
    except Exception as exc:
        print(f"Error: {exc}", file=sys.stderr)
        sys.exit(1)

    report = manager.generate_monthly_report(year, month)
    print(report)

    if errors:
        print("\nWarnings")
        print("-" * 50)
        for error in errors:
            print(error)


if __name__ == "__main__":
    main()

from __future__ import annotations

from collections import defaultdict
from concurrent.futures import ThreadPoolExecutor, as_completed
from dataclasses import dataclass, field
from datetime import datetime, timedelta, timezone
from threading import Lock
from typing import Any, Dict, Iterable, List, Optional, Tuple
import os


@dataclass
class PatientAggregate:
    patient_id: str
    total_valid_encounters: int = 0
    unique_providers: set = field(default_factory=set)
    diagnosis_code_counts: Dict[str, int] = field(default_factory=lambda: defaultdict(int))
    medication_counts: Dict[str, int] = field(default_factory=lambda: defaultdict(int))
    first_encounter: Optional[datetime] = None
    last_encounter: Optional[datetime] = None
    duplicate_encounters: int = 0

    def to_dict(self) -> Dict[str, Any]:
        return {
            "patient_id": self.patient_id,
            "total_valid_encounters": self.total_valid_encounters,
            "unique_provider_count": len(self.unique_providers),
            "unique_providers": sorted(self.unique_providers),
            "diagnosis_code_counts": dict(self.diagnosis_code_counts),
            "medication_counts": dict(self.medication_counts),
            "first_encounter": self.first_encounter.isoformat() if self.first_encounter else None,
            "last_encounter": self.last_encounter.isoformat() if self.last_encounter else None,
            "duplicate_encounters": self.duplicate_encounters,
        }


class ThreadSafeCollector:
    def __init__(self) -> None:
        self.valid_records: List[Dict[str, Any]] = []
        self.validation_errors: List[Dict[str, Any]] = []
        self.duplicates: List[Dict[str, Any]] = []
        self.patient_aggregates: Dict[str, PatientAggregate] = {}
        self._valid_lock = Lock()
        self._error_lock = Lock()
        self._dup_lock = Lock()
        self._agg_lock = Lock()

    def add_valid_record(self, record: Dict[str, Any]) -> None:
        with self._valid_lock:
            self.valid_records.append(record)

    def add_validation_error(self, error: Dict[str, Any]) -> None:
        with self._error_lock:
            self.validation_errors.append(error)

    def add_duplicate(self, duplicate_info: Dict[str, Any]) -> None:
        with self._dup_lock:
            self.duplicates.append(duplicate_info)

    def update_patient_aggregate(
        self,
        patient_id: str,
        timestamp: datetime,
        provider_id: str,
        diagnosis_codes: List[str],
        medications: List[str],
        is_duplicate: bool,
    ) -> None:
        with self._agg_lock:
            agg = self.patient_aggregates.get(patient_id)
            if agg is None:
                agg = PatientAggregate(patient_id=patient_id)
                self.patient_aggregates[patient_id] = agg

            agg.total_valid_encounters += 1
            agg.unique_providers.add(provider_id)

            for code in diagnosis_codes:
                agg.diagnosis_code_counts[code] += 1

            for med in medications:
                agg.medication_counts[med] += 1

            if agg.first_encounter is None or timestamp < agg.first_encounter:
                agg.first_encounter = timestamp
            if agg.last_encounter is None or timestamp > agg.last_encounter:
                agg.last_encounter = timestamp

            if is_duplicate:
                agg.duplicate_encounters += 1


def _parse_timestamp(value: Any) -> datetime:
    if isinstance(value, datetime):
        dt = value
    elif isinstance(value, str):
        normalized = value.strip()
        if normalized.endswith("Z"):
            normalized = normalized[:-1] + "+00:00"
        dt = datetime.fromisoformat(normalized)
    else:
        raise ValueError("encounter_timestamp must be an ISO-8601 string or datetime")

    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    return dt


def _normalize_string_list(value: Any, field_name: str) -> List[str]:
    if value is None:
        return []
    if not isinstance(value, list):
        raise ValueError(f"{field_name} must be a list")
    result = []
    for item in value:
        if item is None:
            continue
        if not isinstance(item, str):
            raise ValueError(f"{field_name} must contain only strings")
        cleaned = item.strip()
        if cleaned:
            result.append(cleaned)
    return result


def _validate_record(record: Any, record_index: int) -> Tuple[Optional[Dict[str, Any]], Optional[Dict[str, Any]]]:
    try:
        if not isinstance(record, dict):
            raise ValueError("record must be a dictionary")

        patient_id = record.get("patient_id")
        provider_id = record.get("provider_id")
        encounter_timestamp = record.get("encounter_timestamp")
        diagnosis_codes = record.get("diagnosis_codes", [])
        medication_list = record.get("medication_list", [])

        if not isinstance(patient_id, str) or not patient_id.strip():
            raise ValueError("patient_id is required and must be a non-empty string")
        if not isinstance(provider_id, str) or not provider_id.strip():
            raise ValueError("provider_id is required and must be a non-empty string")

        parsed_timestamp = _parse_timestamp(encounter_timestamp)
        normalized_diagnosis_codes = _normalize_string_list(diagnosis_codes, "diagnosis_codes")
        normalized_medication_list = _normalize_string_list(medication_list, "medication_list")

        normalized = {
            "record_index": record_index,
            "patient_id": patient_id.strip(),
            "provider_id": provider_id.strip(),
            "encounter_timestamp": parsed_timestamp,
            "diagnosis_codes": normalized_diagnosis_codes,
            "medication_list": normalized_medication_list,
            "raw_record": record,
        }
        return normalized, None

    except Exception as exc:
        return None, {
            "record_index": record_index,
            "error": str(exc),
            "record": record,
        }


def process_patient_encounters(
    encounters: List[Dict[str, Any]],
    duplicate_time_window_minutes: int = 60,
    max_workers: Optional[int] = None,
    include_raw_valid_records: bool = False,
) -> Dict[str, Any]:
    if not isinstance(encounters, list):
        raise TypeError("encounters must be a list of dictionaries")
    if not isinstance(duplicate_time_window_minutes, int) or duplicate_time_window_minutes < 0:
        raise ValueError("duplicate_time_window_minutes must be a non-negative integer")

    if max_workers is None:
        cpu = os.cpu_count() or 4
        max_workers = min(32, max(4, cpu * 2))
    if not isinstance(max_workers, int) or max_workers <= 0:
        raise ValueError("max_workers must be a positive integer")

    collector = ThreadSafeCollector()
    duplicate_window = timedelta(minutes=duplicate_time_window_minutes)

    validated_records: List[Dict[str, Any]] = []

    with ThreadPoolExecutor(max_workers=max_workers, thread_name_prefix="ehr-validate") as executor:
        futures = {
            executor.submit(_validate_record, record, idx): idx
            for idx, record in enumerate(encounters)
        }

        for future in as_completed(futures):
            try:
                normalized, error = future.result()
                if error is not None:
                    collector.add_validation_error(error)
                elif normalized is not None:
                    validated_records.append(normalized)
                else:
                    collector.add_validation_error(
                        {
                            "record_index": futures[future],
                            "error": "Unknown validation outcome",
                            "record": encounters[futures[future]],
                        }
                    )
            except Exception as exc:
                idx = futures[future]
                collector.add_validation_error(
                    {
                        "record_index": idx,
                        "error": f"Unhandled worker exception: {exc}",
                        "record": encounters[idx],
                    }
                )

    validated_records.sort(
        key=lambda r: (r["patient_id"], r["encounter_timestamp"], r["provider_id"], r["record_index"])
    )

    patient_recent_signatures: Dict[str, List[Tuple[datetime, str, Tuple[str, ...], Tuple[str, ...], int]]] = defaultdict(list)

    for record in validated_records:
        patient_id = record["patient_id"]
        timestamp = record["encounter_timestamp"]
        provider_id = record["provider_id"]
        diagnosis_codes = tuple(sorted(record["diagnosis_codes"]))
        medication_list = tuple(sorted(record["medication_list"]))

        recent = patient_recent_signatures[patient_id]
        if duplicate_window.total_seconds() > 0:
            cutoff = timestamp - duplicate_window
            recent = [entry for entry in recent if entry[0] >= cutoff]
            patient_recent_signatures[patient_id] = recent

        is_duplicate = False
        duplicate_of_index: Optional[int] = None

        for prev_ts, prev_provider, prev_dx, prev_meds, prev_index in recent:
            if (
                prev_provider == provider_id
                and prev_dx == diagnosis_codes
                and prev_meds == medication_list
                and abs(timestamp - prev_ts) <= duplicate_window
            ):
                is_duplicate = True
                duplicate_of_index = prev_index
                break

        recent.append((timestamp, provider_id, diagnosis_codes, medication_list, record["record_index"]))
        patient_recent_signatures[patient_id] = recent

        output_record = {
            "record_index": record["record_index"],
            "patient_id": patient_id,
            "provider_id": provider_id,
            "encounter_timestamp": timestamp.isoformat(),
            "diagnosis_codes": list(record["diagnosis_codes"]),
            "medication_list": list(record["medication_list"]),
        }
        if include_raw_valid_records:
            output_record["raw_record"] = record["raw_record"]

        collector.add_valid_record(output_record)

        if is_duplicate:
            collector.add_duplicate(
                {
                    "record_index": record["record_index"],
                    "duplicate_of_record_index": duplicate_of_index,
                    "patient_id": patient_id,
                    "provider_id": provider_id,
                    "encounter_timestamp": timestamp.isoformat(),
                    "duplicate_window_minutes": duplicate_time_window_minutes,
                }
            )

        collector.update_patient_aggregate(
            patient_id=patient_id,
            timestamp=timestamp,
            provider_id=provider_id,
            diagnosis_codes=record["diagnosis_codes"],
            medications=record["medication_list"],
            is_duplicate=is_duplicate,
        )

    patient_summaries = {
        patient_id: aggregate.to_dict()
        for patient_id, aggregate in sorted(collector.patient_aggregates.items(), key=lambda x: x[0])
    }

    collector.valid_records.sort(key=lambda r: r["record_index"])
    collector.validation_errors.sort(key=lambda e: e["record_index"])
    collector.duplicates.sort(key=lambda d: d["record_index"])

    return {
        "summary": {
            "total_input_records": len(encounters),
            "total_valid_records": len(collector.valid_records),
            "total_validation_errors": len(collector.validation_errors),
            "total_duplicates": len(collector.duplicates),
            "patients_processed": len(patient_summaries),
            "duplicate_time_window_minutes": duplicate_time_window_minutes,
            "max_workers": max_workers,
        },
        "valid_records": collector.valid_records,
        "validation_errors": collector.validation_errors,
        "duplicates": collector.duplicates,
        "patient_aggregates": patient_summaries,
    }


if __name__ == "__main__":
