from typing import Any, Dict, List, Tuple
import math


REQUIRED_KEYS = {
    "endpoint_name",
    "request_count",
    "avg_latency_ms",
    "error_rate",
    "gpu_utilization",
}


class ValidationError(ValueError):
    pass


def _is_valid_number(value: Any) -> bool:
    return isinstance(value, (int, float)) and not isinstance(value, bool) and math.isfinite(value)


def validate_log_entry(entry: Dict[str, Any], index: int | None = None) -> Dict[str, Any]:
    if not isinstance(entry, dict):
        prefix = f"Entry at index {index}: " if index is not None else ""
        raise ValidationError(f"{prefix}Each log entry must be a dictionary.")

    missing_keys = REQUIRED_KEYS - entry.keys()
    if missing_keys:
        prefix = f"Entry at index {index}: " if index is not None else ""
        raise ValidationError(f"{prefix}Missing required keys: {sorted(missing_keys)}")

    if not isinstance(entry["endpoint_name"], str) or not entry["endpoint_name"].strip():
        prefix = f"Entry at index {index}: " if index is not None else ""
        raise ValidationError(f"{prefix}'endpoint_name' must be a non-empty string.")

    numeric_fields = ["request_count", "avg_latency_ms", "error_rate", "gpu_utilization"]
    invalid_fields = [field for field in numeric_fields if not _is_valid_number(entry[field])]
    if invalid_fields:
        prefix = f"Entry at index {index}: " if index is not None else ""
        raise ValidationError(f"{prefix}Invalid numeric type for fields: {invalid_fields}")

    if entry["request_count"] < 0:
        prefix = f"Entry at index {index}: " if index is not None else ""
        raise ValidationError(f"{prefix}'request_count' cannot be negative.")
    if entry["avg_latency_ms"] < 0:
        prefix = f"Entry at index {index}: " if index is not None else ""
        raise ValidationError(f"{prefix}'avg_latency_ms' cannot be negative.")
    if entry["error_rate"] < 0:
        prefix = f"Entry at index {index}: " if index is not None else ""
        raise ValidationError(f"{prefix}'error_rate' cannot be negative.")
    if entry["gpu_utilization"] < 0:
        prefix = f"Entry at index {index}: " if index is not None else ""
        raise ValidationError(f"{prefix}'gpu_utilization' cannot be negative.")

    return entry


def validate_logs(logs: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    if not isinstance(logs, list):
        raise ValidationError("Input logs must be a list of dictionaries.")
    return [validate_log_entry(entry, index=i) for i, entry in enumerate(logs)]


def is_underperforming(entry: Dict[str, Any]) -> bool:
    return entry["avg_latency_ms"] > 300 or entry["error_rate"] > 0.05


def compute_risk_score(entry: Dict[str, Any]) -> float:
    return (
        (entry["avg_latency_ms"] / 100.0)
        + (entry["error_rate"] * 100.0)
        - (entry["gpu_utilization"] / 10.0)
    )


def analyze_inference_logs(logs: List[Dict[str, Any]]) -> List[Tuple[str, float]]:
    validated_logs = validate_logs(logs)

    flagged = [entry for entry in validated_logs if is_underperforming(entry)]

    scored = [
        (entry["endpoint_name"], round(compute_risk_score(entry), 4))
        for entry in flagged
    ]

    return sorted(scored, key=lambda item: item[1], reverse=True)


