class CloudServerManager:
    def __init__(self):
        self.servers = []

    def add_server(self, server_id, name, status, cpu_usage):
        if not isinstance(server_id, str) or server_id.strip() == "":
            return "Error: Server id must be a non-empty string."

        if not isinstance(name, str) or name.strip() == "":
            return "Error: Server name must be a non-empty string."

        if not isinstance(status, str) or status.strip() == "":
            return "Error: Server status must be a non-empty string."

        if not isinstance(cpu_usage, int) or cpu_usage < 0 or cpu_usage > 100:
            return "Error: CPU usage must be an integer between 0 and 100."

        for server in self.servers:
            if server["id"] == server_id:
                return "Error: A server with this id already exists."

        new_server = {
            "id": server_id,
            "name": name,
            "status": status,
            "cpu_usage": cpu_usage
        }

        self.servers.append(new_server)
        return "Server added successfully."

    def remove_server(self, server_id):
        for server in self.servers:
            if server["id"] == server_id:
                self.servers.remove(server)
                return "Server removed successfully."
        return "Error: Server not found."

    def update_status(self, server_id, new_status):
        if not isinstance(new_status, str) or new_status.strip() == "":
            return "Error: New status must be a non-empty string."

        for server in self.servers:
            if server["id"] == server_id:
                server["status"] = new_status
                return "Server status updated successfully."
        return "Error: Server not found."

    def get_running_servers(self):
        running_servers = []
        for server in self.servers:
            if server["status"] == "running":
                running_servers.append(server)
        return running_servers

    def list_all_servers(self):
        return self.servers


if __name__ == "__main__":
    manager = CloudServerManager()

    print(manager.add_server("srv001", "Web Server", "running", 45))
    print(manager.add_server("srv002", "Database Server", "stopped", 20))
    print(manager.add_server("srv001", "Duplicate Server", "running", 50))

    print(manager.update_status("srv002", "running"))
    print(manager.update_status("srv999", "stopped"))

    print("Running servers:")
    for server in manager.get_running_servers():
        print(server)

    print(manager.remove_server("srv001"))
    print(manager.remove_server("srv999"))

    print("All servers:")
    for server in manager.list_all_servers():
        print(server)

from __future__ import annotations

import json
import logging
import math
import random
import threading
from collections import deque
from contextlib import AbstractContextManager
from dataclasses import dataclass, field
from datetime import datetime, time, timedelta, timezone
from pathlib import Path
from typing import Any, Deque, Dict, Iterable, Iterator, List, Optional, Protocol, TextIO, Tuple


def configure_logging(level: int = logging.INFO) -> logging.Logger:
    logger = logging.getLogger("trading_pipeline")
    if not logger.handlers:
        logger.setLevel(level)
        handler = logging.StreamHandler()
        formatter = logging.Formatter(
            fmt="%(asctime)s %(levelname)s %(name)s %(message)s"
        )
        handler.setFormatter(formatter)
        logger.addHandler(handler)
        logger.propagate = False
    return logger


LOGGER = configure_logging()


class PipelineError(Exception):
    pass


class ValidationError(PipelineError):
    pass


class FeedConnectionError(PipelineError):
    pass


@dataclass(frozen=True)
class Tick:
    symbol: str
    timestamp: datetime
    price: float
    volume: float
    bid: Optional[float] = None
    ask: Optional[float] = None

    def __post_init__(self) -> None:
        if not self.symbol:
            raise ValidationError("symbol must not be empty")
        if self.price <= 0:
            raise ValidationError("price must be positive")
        if self.volume < 0:
            raise ValidationError("volume must be non-negative")
        if self.timestamp.tzinfo is None:
            raise ValidationError("timestamp must be timezone-aware")


@dataclass(frozen=True)
class Signal:
    symbol: str
    timestamp: datetime
    action: str
    reason: str
    price: float
    indicators: Dict[str, float] = field(default_factory=dict)


@dataclass(frozen=True)
class StrategyConfig:
    ema_period: int = 20
    volatility_period: int = 20
    vwap_period: int = 50
    buy_threshold_pct: float = 0.002
    sell_threshold_pct: float = 0.002
    volatility_cap: float = 0.05

    def __post_init__(self) -> None:
        if self.ema_period <= 0 or self.volatility_period <= 1 or self.vwap_period <= 0:
            raise ValueError("indicator periods must be positive and volatility_period > 1")
        if self.buy_threshold_pct < 0 or self.sell_threshold_pct < 0:
            raise ValueError("thresholds must be non-negative")
        if self.volatility_cap < 0:
            raise ValueError("volatility_cap must be non-negative")


@dataclass(frozen=True)
class RiskLimits:
    max_position_per_symbol: int = 1000
    max_notional_per_symbol: float = 1_000_000.0
    max_signals_per_symbol_per_session: int = 100

    def __post_init__(self) -> None:
        if self.max_position_per_symbol < 0:
            raise ValueError("max_position_per_symbol must be non-negative")
        if self.max_notional_per_symbol < 0:
            raise ValueError("max_notional_per_symbol must be non-negative")
        if self.max_signals_per_symbol_per_session < 0:
            raise ValueError("max_signals_per_symbol_per_session must be non-negative")


@dataclass(frozen=True)
class SessionConfig:
    start: time
    end: time
    timezone_name: str = "UTC"

    def is_open(self, ts: datetime) -> bool:
        if ts.tzinfo is None:
            return False
        local_t = ts.timetz().replace(tzinfo=None)
        if self.start <= self.end:
            return self.start <= local_t <= self.end
        return local_t >= self.start or local_t <= self.end


@dataclass(frozen=True)
class PipelineConfig:
    symbols: Tuple[str, ...]
    strategy: StrategyConfig = field(default_factory=StrategyConfig)
    risk: RiskLimits = field(default_factory=RiskLimits)
    session: SessionConfig = field(
        default_factory=lambda: SessionConfig(start=time(9, 30), end=time(16, 0))
    )
    log_path: Optional[Path] = None


class PriceFeed(Protocol):
    def connect(self) -> None:
        ...

    def disconnect(self) -> None:
        ...

    def stream(self) -> Iterator[Dict[str, Any]]:
        ...


class MockPriceFeed(AbstractContextManager["MockPriceFeed"]):
    def __init__(
        self,
        symbols: Iterable[str],
        ticks_per_symbol: int = 100,
        interval_ms: int = 1000,
        seed: Optional[int] = 7,
        start_prices: Optional[Dict[str, float]] = None,
    ) -> None:
        self.symbols = tuple(symbols)
        self.ticks_per_symbol = ticks_per_symbol
        self.interval_ms = interval_ms
        self.seed = seed
        self.start_prices = start_prices or {s: 100.0 + i * 10 for i, s in enumerate(self.symbols)}
        self._connected = False
        self._rng = random.Random(seed)

    def __enter__(self) -> "MockPriceFeed":
        self.connect()
        return self

    def __exit__(self, exc_type, exc, tb) -> None:
        self.disconnect()

    def connect(self) -> None:
        if self._connected:
            raise FeedConnectionError("feed already connected")
        self._connected = True
        LOGGER.info("mock feed connected", extra={"symbols": self.symbols})

    def disconnect(self) -> None:
        if self._connected:
            self._connected = False
            LOGGER.info("mock feed disconnected")

    def stream(self) -> Iterator[Dict[str, Any]]:
        if not self._connected:
            raise FeedConnectionError("feed not connected")
        now = datetime.now(timezone.utc).replace(microsecond=0)
        prices = dict(self.start_prices)
        for i in range(self.ticks_per_symbol):
            for symbol in self.symbols:
                drift = self._rng.uniform(-0.003, 0.003)
                prices[symbol] = max(0.01, prices[symbol] * (1.0 + drift))
                spread = max(0.01, prices[symbol] * 0.0005)
                volume = float(self._rng.randint(1, 500))
                ts = now + timedelta(milliseconds=self.interval_ms * i)
                yield {
                    "symbol": symbol,
                    "timestamp": ts.isoformat(),
                    "price": round(prices[symbol], 4),
                    "volume": volume,
                    "bid": round(prices[symbol] - spread / 2, 4),
                    "ask": round(prices[symbol] + spread / 2, 4),
                }


class TransactionLogger(AbstractContextManager["TransactionLogger"]):
    def __init__(self, path: Optional[Path] = None) -> None:
        self.path = path
        self._fh: Optional[TextIO] = None
        self._lock = threading.Lock()

    def __enter__(self) -> "TransactionLogger":
        if self.path is not None:
            self.path.parent.mkdir(parents=True, exist_ok=True)
            self._fh = self.path.open("a", encoding="utf-8")
        return self

    def __exit__(self, exc_type, exc, tb) -> None:
        if self._fh:
            self._fh.flush()
            self._fh.close()
            self._fh = None

    def log_event(self, event_type: str, payload: Dict[str, Any]) -> None:
        record = {
            "event_type": event_type,
            "timestamp": datetime.now(timezone.utc).isoformat(),
            "payload": payload,
        }
        line = json.dumps(record, default=str)
        with self._lock:
            LOGGER.info("%s %s", event_type, line)
            if self._fh:
                self._fh.write(line + "\n")
                self._fh.flush()


class DataValidator:
    @staticmethod
    def normalize(record: Dict[str, Any]) -> Tick:
        try:
            symbol = str(record["symbol"]).strip().upper()
            raw_ts = record["timestamp"]
            if isinstance(raw_ts, datetime):
                ts = raw_ts
            else:
                ts = datetime.fromisoformat(str(raw_ts))
            if ts.tzinfo is None:
                ts = ts.replace(tzinfo=timezone.utc)
            price = float(record["price"])
            volume = float(record.get("volume", 0.0))
            bid = float(record["bid"]) if record.get("bid") is not None else None
            ask = float(record["ask"]) if record.get("ask") is not None else None
            if bid is not None and ask is not None and bid > ask:
                raise ValidationError("bid cannot exceed ask")
            return Tick(
                symbol=symbol,
                timestamp=ts,
                price=price,
                volume=volume,
                bid=bid,
                ask=ask,
            )
        except KeyError as exc:
            raise ValidationError(f"missing required field: {exc}") from exc
        except (TypeError, ValueError) as exc:
            raise ValidationError(f"invalid record format: {exc}") from exc


class RollingIndicators:
    def __init__(self, ema_period: int, volatility_period: int, vwap_period: int) -> None:
        self.ema_period = ema_period
        self.volatility_period = volatility_period
        self.vwap_period = vwap_period
        self.prices: Deque[float] = deque(maxlen=max(volatility_period, vwap_period))
        self.volumes: Deque[float] = deque(maxlen=vwap_period)
        self.ema_value: Optional[float] = None

    def update(self, price: float, volume: float) -> Dict[str, float]:
        self.prices.append(price)
        self.volumes.append(volume)

        alpha = 2.0 / (self.ema_period + 1.0)
        if self.ema_value is None:
            self.ema_value = price
        else:
            self.ema_value = alpha * price + (1.0 - alpha) * self.ema_value

        vwap = self._compute_vwap()
        volatility = self._compute_volatility()

        return {
            "ema": self.ema_value,
            "vwap": vwap,
            "volatility": volatility,
        }

    def _compute_vwap(self) -> float:
        n = min(len(self.prices), self.vwap_period)
        if n == 0:
            return 0.0
        recent_prices = list(self.prices)[-n:]
        recent_volumes = list(self.volumes)[-n:]
        total_volume = sum(recent_volumes)
        if total_volume <= 0:
            return recent_prices[-1]
        return sum(p * v for p, v in zip(recent_prices, recent_volumes)) / total_volume

    def _compute_volatility(self) -> float:
        n = min(len(self.prices), self.volatility_period)
        if n < 2:
            return 0.0
        recent = list(self.prices)[-n:]
        returns = []
        for i in range(1, len(recent)):
            prev = recent[i - 1]
            curr = recent[i]
            if prev <= 0:
                continue
            returns.append(math.log(curr / prev))
        if len(returns) < 2:
            return 0.0
        mean_r = sum(returns) / len(returns)
        variance = sum((r - mean_r) ** 2 for r in returns) / (len(returns) - 1)
        return math.sqrt(max(variance, 0.0))


@dataclass
class SymbolState:
    indicators: RollingIndicators
    position: int = 0
    signal_count: int = 0
    last_signal: str = "HOLD"


class SignalEngine:
    def __init__(self, config: PipelineConfig) -> None:
        self.config = config
        self.states: Dict[str, SymbolState] = {
            symbol: SymbolState(
                indicators=RollingIndicators(
                    ema_period=config.strategy.ema_period,
                    volatility_period=config.strategy.volatility_period,
                    vwap_period=config.strategy.vwap_period,
                )
            )
            for symbol in config.symbols
        }

    def evaluate(self, tick: Tick) -> Signal:
        if tick.symbol not in self.states:
            raise ValidationError(f"unsupported symbol: {tick.symbol}")

        state = self.states[tick.symbol]
        metrics = state.indicators.update(tick.price, tick.volume)
        ema = metrics["ema"]
        vwap = metrics["vwap"]
        volatility = metrics["volatility"]

        action = "HOLD"
        reason = "default_hold"

        if not self.config.session.is_open(tick.timestamp):
            reason = "outside_session"
        elif volatility > self.config.strategy.volatility_cap:
            reason = "volatility_cap_exceeded"
        elif state.signal_count >= self.config.risk.max_signals_per_symbol_per_session:
            reason = "signal_limit_reached"
        else:
            buy_trigger = tick.price > ema * (1.0 + self.config.strategy.buy_threshold_pct) and tick.price > vwap
            sell_trigger = tick.price < ema * (1.0 - self.config.strategy.sell_threshold_pct) and tick.price < vwap

            if buy_trigger and self._can_buy(state, tick.price):
                action = "BUY"
                reason = "price_above_ema_and_vwap"
                state.position += 1
                state.signal_count += 1
            elif sell_trigger and self._can_sell(state, tick.price):
                action = "SELL"
                reason = "price_below_ema_and_vwap"
                state.position -= 1
                state.signal_count += 1
            else:
                reason = "no_strategy_trigger"

        state.last_signal = action
        return Signal(
            symbol=tick.symbol,
            timestamp=tick.timestamp,
            action=action,
            reason=reason,
            price=tick.price,
            indicators=metrics,
        )

    def _can_buy(self, state: SymbolState, price: float) -> bool:
        projected_position = state.position + 1
        projected_notional = abs(projected_position * price)
        return (
            projected_position <= self.config.risk.max_position_per_symbol
            and projected_notional <= self.config.risk.max_notional_per_symbol
        )

    def _can_sell(self, state: SymbolState, price: float) -> bool:
        projected_position = state.position - 1
        projected_notional = abs(projected_position * price)
        return (
            abs(projected_position) <= self.config.risk.max_position_per_symbol
            and projected_notional <= self.config.risk.max_notional_per_symbol
        )


class MarketDataPipeline(AbstractContextManager["MarketDataPipeline"]):
    def __init__(
        self,
        feed: PriceFeed,
        config: PipelineConfig,
        transaction_logger: Optional[TransactionLogger] = None,
        logger: Optional[logging.Logger] = None,
    ) -> None:
        self.feed = feed
        self.config = config
        self.logger = logger or LOGGER
        self.transaction_logger = transaction_logger or TransactionLogger(config.log_path)
        self.signal_engine = SignalEngine(config)
        self._entered = False

    def __enter__(self) -> "MarketDataPipeline":
        self.transaction_logger.__enter__()
        try:
            self.feed.connect()
        except Exception:
            self.transaction_logger.__exit__(*__import__("sys").exc_info())
            raise
        self._entered = True
        self.transaction_logger.log_event(
            "pipeline_started",
            {"symbols": list(self.config.symbols)},
        )
        return self

    def __exit__(self, exc_type, exc, tb) -> None:
        try:
            self.feed.disconnect()
        finally:
            self.transaction_logger.log_event(
                "pipeline_stopped",
                {"error": str(exc) if exc else None},
            )
            self.transaction_logger.__exit__(exc_type, exc, tb)
            self._entered = False

    def run(self) -> Iterator[Signal]:
        if not self._entered:
            raise PipelineError("pipeline must be used within a context manager")

        for raw_record in self.feed.stream():
            try:
                tick = DataValidator.normalize(raw_record)
                if tick.symbol not in self.config.symbols:
                    self.transaction_logger.log_event(
                        "record_skipped",
                        {"reason": "unknown_symbol", "record": raw_record},
                    )
                    continue

                signal = self.signal_engine.evaluate(tick)
                self.transaction_logger.log_event(
                    "signal_generated",
                    {
                        "symbol": signal.symbol,
                        "timestamp": signal.timestamp.isoformat(),
                        "action": signal.action,
                        "reason": signal.reason,
                        "price": signal.price,
                        "indicators": signal.indicators,
                    },
                )
                yield signal
            except ValidationError as exc:
                self.transaction_logger.log_event(
                    "validation_error",
                    {"error": str(exc), "record": raw_record},
                )
            except Exception as exc:
                self.transaction_logger.log_event(
                    "processing_error",
                    {"error": str(exc), "record": raw_record},
                )


def build_default_pipeline(
    symbols: Iterable[str],
    log_path: Optional[str] = None,
    ticks_per_symbol: int = 50,
) -> MarketDataPipeline:
    symbol_tuple = tuple(s.upper() for s in symbols)
    config = PipelineConfig(
        symbols=symbol_tuple,
        log_path=Path(log_path) if log_path else None,
    )
    feed = MockPriceFeed(symbols=symbol_tuple, ticks_per_symbol=ticks_per_symbol)
    return MarketDataPipeline(feed=feed, config=config)


def main() -> None:
    pipeline = build_default_pipeline(
        symbols=["AAPL", "MSFT", "GOOG"],
        log_path="logs/trading_pipeline.jsonl",
        ticks_per_symbol=20,
    )
    with pipeline as p:
        for signal in p.run():
            print(
                json.dumps(
                    {
                        "symbol": signal.symbol,
                        "timestamp": signal.timestamp.isoformat(),
                        "action": signal.action,
                        "reason": signal.reason,
                        "price": signal.price,
                        "indicators": {
                            k: round(v, 6) for k, v in signal.indicators.items()
                        },
                    }
                )
            )


if __name__ == "__main__":
    main()

class Model:
    """Represents a simple machine learning model."""

    def __init__(self, name, version, framework, accuracy):
        self.name = name
        self.version = version
        self.framework = framework
        self.accuracy = accuracy

    def __str__(self):
        """Readable string representation of the model."""
        return (
            f"Model(name='{self.name}', version='{self.version}', "
            f"framework='{self.framework}', accuracy={self.accuracy:.2f})"
        )


class ModelRegistry:
    """Stores and manages multiple models."""

    def __init__(self):
        self.models = []

    def add_model(self, model):
        """Add a model to the registry."""
        self.models.append(model)

    def list_models(self):
        """Return all registered models."""
        return self.models

    def find_best_model(self):
        """Return the model with the highest accuracy."""
        if not self.models:
            return None
        return max(self.models, key=lambda model: model.accuracy)


def main():
    # Create a model registry
    registry = ModelRegistry()

    # Create sample models
    model_1 = Model("ImageClassifier", "1.0", "TensorFlow", 0.91)
    model_2 = Model("TextAnalyzer", "2.1", "PyTorch", 0.88)
    model_3 = Model("RecommendationEngine", "1.5", "Scikit-learn", 0.94)

    # Add models to the registry
    registry.add_model(model_1)
    registry.add_model(model_2)
    registry.add_model(model_3)

    # Print all registered models
    print("Registered Models:")
    for model in registry.list_models():
        print("-", model)

    # Find and print the best-performing model
    best_model = registry.find_best_model()
    print("\nBest Performing Model:")
    if best_model is not None:
        print(best_model)
    else:
        print("No models found in the registry.")


if __name__ == "__main__":
    main()
